import type { BankQuestion } from "@/lib/bank";

/** International Organisations and Groupings (General Knowledge): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"gk-international-orgs-1","question":"The headquarters of the United Nations is in:","options":["Geneva","New York","Washington, D.C.","Paris"],"answer":1,"explanation":"The UN headquarters is in New York; its main European office is at Geneva.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"संयुक्त राष्ट्र का मुख्यालय कहाँ स्थित है?","optionsHi":["जिनेवा","न्यूयॉर्क","वाशिंगटन, D.C.","पेरिस"],"explanationHi":"संयुक्त राष्ट्र का मुख्यालय न्यूयॉर्क में है; इसका यूरोप का मुख्य कार्यालय जिनेवा में है।"},
  {"id":"gk-international-orgs-2","question":"The headquarters of the World Trade Organization (WTO) is in:","options":["New York","Vienna","Geneva","Brussels"],"answer":2,"explanation":"The WTO, successor to GATT since 1995, is headquartered in Geneva, Switzerland. Vienna is the trap: it hosts the IAEA, OPEC and UNIDO, not the WTO.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"विश्व व्यापार संगठन (WTO) का मुख्यालय कहाँ है?","optionsHi":["न्यूयॉर्क","वियना","जिनेवा","ब्रुसेल्स"],"explanationHi":"WTO, जो 1995 से GATT का उत्तराधिकारी है, का मुख्यालय जिनेवा (स्विट्जरलैंड) में है। वियना भ्रम पैदा करने वाला विकल्प है: वहाँ IAEA, OPEC और UNIDO स्थित हैं, WTO नहीं।"},
  {"id":"gk-international-orgs-3","question":"United Nations Day is observed every year on:","options":["26 June","10 December","24 October","1 January"],"answer":2,"explanation":"The UN Charter came into force on 24 October 1945. It was signed on 26 June 1945; 10 December is Human Rights Day.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"संयुक्त राष्ट्र दिवस प्रत्येक वर्ष किस तिथि को मनाया जाता है?","optionsHi":["26 जून","10 दिसंबर","24 अक्टूबर","1 जनवरी"],"explanationHi":"संयुक्त राष्ट्र चार्टर 24 अक्टूबर 1945 को लागू हुआ था। इस पर 26 जून 1945 को हस्ताक्षर हुए थे; 10 दिसंबर मानवाधिकार दिवस है।"},
  {"id":"gk-international-orgs-4","question":"The secretariat of SAARC is located in:","options":["Kathmandu","New Delhi","Colombo","Dhaka"],"answer":0,"explanation":"The SAARC Secretariat has been in Kathmandu since 1987. SAARC itself was founded at Dhaka in 1985.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"सार्क (SAARC) का सचिवालय कहाँ स्थित है?","optionsHi":["काठमांडू","नई दिल्ली","कोलंबो","ढाका"],"explanationHi":"सार्क सचिवालय 1987 से काठमांडू में है। सार्क की स्थापना स्वयं 1985 में ढाका में हुई थी।"},
  {"id":"gk-international-orgs-5","question":"The IMF and the World Bank were created at a conference held in 1944 at:","options":["Bretton Woods","San Francisco","Yalta","Geneva"],"answer":0,"explanation":"The Bretton Woods Conference (New Hampshire, USA, July 1944) set up the IMF and the IBRD, so they are called the Bretton Woods twins. The UN Charter was signed at San Francisco.","difficulty":"moderate","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"1944 में आयोजित किस सम्मेलन में IMF और विश्व बैंक की स्थापना हुई थी?","optionsHi":["ब्रेटन वुड्स","सैन फ्रांसिस्को","याल्टा","जिनेवा"],"explanationHi":"ब्रेटन वुड्स सम्मेलन (न्यू हैम्पशायर, अमेरिका, जुलाई 1944) में IMF और IBRD की स्थापना हुई, इसलिए इन्हें ब्रेटन वुड्स जुड़वाँ संस्थाएँ कहा जाता है। संयुक्त राष्ट्र चार्टर पर हस्ताक्षर सैन फ्रांसिस्को में हुए थे।"},
  {"id":"gk-international-orgs-6","question":"Which of the following is NOT a permanent member of the UN Security Council?","options":["China","United Kingdom","France","Germany"],"answer":3,"explanation":"The five permanent members are the USA, the UK, France, Russia and China. Germany, like India, seeks a permanent seat (the G4 group).","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"निम्नलिखित में से कौन संयुक्त राष्ट्र सुरक्षा परिषद का स्थायी सदस्य नहीं है?","optionsHi":["चीन","यूनाइटेड किंगडम","फ्रांस","जर्मनी"],"explanationHi":"पाँच स्थायी सदस्य अमेरिका, ब्रिटेन, फ्रांस, रूस और चीन हैं। भारत की तरह जर्मनी भी स्थायी सीट चाहता है (G4 समूह)।"},
  {"id":"gk-international-orgs-7","question":"The secretariat of ASEAN is in:","options":["Jakarta","Bangkok","Kuala Lumpur","Singapore"],"answer":0,"explanation":"The ASEAN Secretariat is in Jakarta. ASEAN was founded by the Bangkok Declaration of 1967, which is why Bangkok is the trap.","difficulty":"moderate","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"आसियान (ASEAN) का सचिवालय कहाँ है?","optionsHi":["जकार्ता","बैंकॉक","कुआलालंपुर","सिंगापुर"],"explanationHi":"आसियान सचिवालय जकार्ता में है। आसियान की स्थापना 1967 की बैंकॉक घोषणा से हुई थी, इसीलिए बैंकॉक भ्रमित करने वाला विकल्प है।"},
  {"id":"gk-international-orgs-8","question":"The headquarters of the World Health Organization is in:","options":["Rome","Geneva","Vienna","New York"],"answer":1,"explanation":"WHO, founded in 1948, is based at Geneva. Rome hosts the FAO and Vienna the IAEA.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"विश्व स्वास्थ्य संगठन का मुख्यालय कहाँ है?","optionsHi":["रोम","जिनेवा","वियना","न्यूयॉर्क"],"explanationHi":"WHO, जिसकी स्थापना 1948 में हुई, का मुख्यालय जिनेवा में है। रोम में FAO और वियना में IAEA स्थित है।"},
  {"id":"gk-international-orgs-9","question":"The headquarters of UNESCO is in:","options":["Geneva","London","Brussels","Paris"],"answer":3,"explanation":"UNESCO is headquartered in Paris, France. Geneva is the tempting wrong pick because it hosts many UN bodies such as the WHO and ILO, but not UNESCO.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"UNESCO का मुख्यालय कहाँ है?","optionsHi":["जिनेवा","लंदन","ब्रुसेल्स","पेरिस"],"explanationHi":"UNESCO का मुख्यालय पेरिस (फ्रांस) में है। जिनेवा भ्रमित करने वाला गलत विकल्प है, क्योंकि वहाँ WHO और ILO जैसी कई संयुक्त राष्ट्र संस्थाएँ हैं, परंतु UNESCO नहीं।"},
  {"id":"gk-international-orgs-10","question":"Which country joined BRIC in 2010, making it BRICS?","options":["South Africa","Saudi Arabia","Argentina","Indonesia"],"answer":0,"explanation":"South Africa was invited in December 2010 and attended its first summit in 2011.","difficulty":"moderate","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"2010 में कौन-सा देश BRIC में शामिल हुआ, जिससे यह BRICS बना?","optionsHi":["दक्षिण अफ्रीका","सऊदी अरब","अर्जेंटीना","इंडोनेशिया"],"explanationHi":"दक्षिण अफ्रीका को दिसंबर 2010 में आमंत्रित किया गया और उसने 2011 में अपने पहले शिखर सम्मेलन में भाग लिया।"},
  {"id":"gk-international-orgs-11","question":"The secretariat of the Shanghai Cooperation Organisation (SCO) is in:","options":["Tashkent","Shanghai","Beijing","Moscow"],"answer":2,"explanation":"The SCO Secretariat is in Beijing; its Regional Anti-Terrorist Structure (RATS) is in Tashkent.","difficulty":"moderate","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"शंघाई सहयोग संगठन (SCO) का सचिवालय कहाँ है?","optionsHi":["ताशकंद","शंघाई","बीजिंग","मॉस्को"],"explanationHi":"SCO का सचिवालय बीजिंग में है; इसकी क्षेत्रीय आतंकवाद-रोधी संरचना (RATS) ताशकंद में है।"},
  {"id":"gk-international-orgs-12","question":"The International Court of Justice sits at:","options":["New York","Vienna","The Hague","Geneva"],"answer":2,"explanation":"The ICJ, the UN’s principal judicial organ, sits at the Peace Palace in The Hague, Netherlands; it is the only principal organ not based in New York.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अंतर्राष्ट्रीय न्यायालय (ICJ) कहाँ स्थित है?","optionsHi":["न्यूयॉर्क","वियना","द हेग","जिनेवा"],"explanationHi":"ICJ, जो संयुक्त राष्ट्र का प्रमुख न्यायिक अंग है, नीदरलैंड के द हेग में पीस पैलेस में स्थित है; यह एकमात्र प्रमुख अंग है जिसका मुख्यालय न्यूयॉर्क में नहीं है।"},
  {"id":"gk-international-orgs-13","question":"The World Trade Organization was established under which agreement, concluding the Uruguay Round?","options":["Doha Declaration","Havana Charter","Bali Package","Marrakesh Agreement"],"answer":3,"explanation":"The Marrakesh Agreement (April 1994) set up the WTO from 1 January 1995. The Havana Charter (1948) for an International Trade Organization never came into force; Doha (2001) launched a new round and the Bali Package came in 2013.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"उरुग्वे दौर को समाप्त करने वाले किस समझौते के अंतर्गत विश्व व्यापार संगठन की स्थापना हुई?","optionsHi":["दोहा घोषणा","हवाना चार्टर","बाली पैकेज","मराकेश समझौता"],"explanationHi":"मराकेश समझौते (अप्रैल 1994) से 1 जनवरी 1995 को WTO की स्थापना हुई। अंतर्राष्ट्रीय व्यापार संगठन के लिए हवाना चार्टर (1948) कभी लागू नहीं हुआ; दोहा (2001) में नया दौर शुरू हुआ और बाली पैकेज 2013 में आया।"},
  {"id":"gk-international-orgs-14","question":"The International Court of Justice has how many judges, and for what term?","options":["15 judges for 5-year terms","9 judges for 6-year terms","11 judges for 9-year terms","15 judges for 9-year terms"],"answer":3,"explanation":"The ICJ has 15 judges elected by the General Assembly and the Security Council for nine-year terms; a third of the bench is elected every three years.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"अंतर्राष्ट्रीय न्यायालय में कितने न्यायाधीश होते हैं और उनका कार्यकाल कितना होता है?","optionsHi":["15 न्यायाधीश, 5 वर्ष का कार्यकाल","9 न्यायाधीश, 6 वर्ष का कार्यकाल","11 न्यायाधीश, 9 वर्ष का कार्यकाल","15 न्यायाधीश, 9 वर्ष का कार्यकाल"],"explanationHi":"ICJ में 15 न्यायाधीश होते हैं, जिन्हें महासभा और सुरक्षा परिषद नौ वर्ष के कार्यकाल के लिए चुनती हैं; प्रत्येक तीन वर्ष में एक-तिहाई न्यायाधीश चुने जाते हैं।"},
  {"id":"gk-international-orgs-15","question":"The UN Security Council has how many non-permanent members, and for what term?","options":["10 members for two-year terms","6 members for two-year terms","15 members for two-year terms","10 members for three-year terms"],"answer":0,"explanation":"There are 10 non-permanent members elected by the General Assembly for two years (5 each year), making 15 members in all with the 5 permanent members.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"संयुक्त राष्ट्र सुरक्षा परिषद में कितने अस्थायी सदस्य होते हैं और उनका कार्यकाल कितना होता है?","optionsHi":["10 सदस्य, दो वर्ष का कार्यकाल","6 सदस्य, दो वर्ष का कार्यकाल","15 सदस्य, दो वर्ष का कार्यकाल","10 सदस्य, तीन वर्ष का कार्यकाल"],"explanationHi":"10 अस्थायी सदस्य होते हैं, जिन्हें महासभा दो वर्ष के लिए चुनती है (प्रतिवर्ष 5), और 5 स्थायी सदस्यों के साथ मिलाकर कुल 15 सदस्य होते हैं।"},
  {"id":"gk-international-orgs-16","question":"At the G20 Leaders’ Summit in New Delhi in September 2023, which body was admitted as a permanent member of the G20?","options":["Arab League","European Union","African Union","ASEAN"],"answer":2,"explanation":"The African Union joined the G20 at the New Delhi summit under India’s presidency. The European Union was already a member.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"सितंबर 2023 में नई दिल्ली में हुए G20 नेताओं के शिखर सम्मेलन में किस निकाय को G20 का स्थायी सदस्य बनाया गया?","optionsHi":["अरब लीग","यूरोपीय संघ","अफ्रीकी संघ","आसियान"],"explanationHi":"भारत की अध्यक्षता में नई दिल्ली शिखर सम्मेलन में अफ्रीकी संघ G20 में शामिल हुआ। यूरोपीय संघ पहले से सदस्य था।"},
  {"id":"gk-international-orgs-17","question":"India became a full member of the Shanghai Cooperation Organisation in:","options":["2001","2005","2017","2015"],"answer":2,"explanation":"India and Pakistan became full members at the Astana summit in June 2017; India had been an observer since 2005. The SCO was founded in 2001.","difficulty":"hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"भारत शंघाई सहयोग संगठन का पूर्ण सदस्य कब बना?","optionsHi":["2001","2005","2017","2015"],"explanationHi":"भारत और पाकिस्तान जून 2017 में अस्ताना शिखर सम्मेलन में पूर्ण सदस्य बने; भारत 2005 से पर्यवेक्षक था। SCO की स्थापना 2001 में हुई थी।"},
  {"id":"gk-international-orgs-18","question":"Which of these currencies is NOT in the basket that values the IMF’s Special Drawing Rights (SDR)?","options":["Swiss franc","Chinese renminbi","Pound sterling","Japanese yen"],"answer":0,"explanation":"The SDR basket has five currencies: US dollar, euro, Chinese renminbi (added in 2016), Japanese yen and pound sterling.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन-सी मुद्रा IMF के विशेष आहरण अधिकार (SDR) का मूल्य निर्धारित करने वाली टोकरी में शामिल नहीं है?","optionsHi":["स्विस फ्रैंक","चीनी रेनमिनबी","पाउंड स्टर्लिंग","जापानी येन"],"explanationHi":"SDR टोकरी में पाँच मुद्राएँ हैं: अमेरिकी डॉलर, यूरो, चीनी रेनमिनबी (2016 में जोड़ी गई), जापानी येन और पाउंड स्टर्लिंग।"},
  {"id":"gk-international-orgs-19","question":"The New Development Bank set up by the BRICS countries has its headquarters in:","options":["Shanghai","Beijing","New Delhi","Moscow"],"answer":0,"explanation":"The NDB is headquartered in Shanghai; its first president was India’s K.V. Kamath. The Asian Infrastructure Investment Bank is in Beijing.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"ब्रिक्स देशों द्वारा स्थापित न्यू डेवलपमेंट बैंक का मुख्यालय कहाँ है?","optionsHi":["शंघाई","बीजिंग","नई दिल्ली","मॉस्को"],"explanationHi":"NDB का मुख्यालय शंघाई में है; इसके पहले अध्यक्ष भारत के के.वी. कामथ थे। एशियन इंफ्रास्ट्रक्चर इन्वेस्टमेंट बैंक बीजिंग में है।"},
  {"id":"gk-international-orgs-20","question":"The Asian Infrastructure Investment Bank (AIIB) has its headquarters in:","options":["Beijing","Shanghai","Manila","Singapore"],"answer":0,"explanation":"The AIIB, which began operations in 2016, is based in Beijing; India is its second-largest shareholder. Manila hosts the Asian Development Bank.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एशियन इंफ्रास्ट्रक्चर इन्वेस्टमेंट बैंक (AIIB) का मुख्यालय कहाँ है?","optionsHi":["बीजिंग","शंघाई","मनीला","सिंगापुर"],"explanationHi":"AIIB, जिसने 2016 में कार्य शुरू किया, का मुख्यालय बीजिंग में है; भारत इसका दूसरा सबसे बड़ा शेयरधारक है। मनीला में एशियाई विकास बैंक स्थित है।"},
  {"id":"gk-international-orgs-21","question":"Which of the following was NOT a founding member of ASEAN in 1967?","options":["Indonesia","Singapore","Vietnam","Philippines"],"answer":2,"explanation":"The five founders were Indonesia, Malaysia, the Philippines, Singapore and Thailand. Vietnam joined in 1995.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन 1967 में आसियान का संस्थापक सदस्य नहीं था?","optionsHi":["इंडोनेशिया","सिंगापुर","वियतनाम","फिलीपींस"],"explanationHi":"पाँच संस्थापक सदस्य इंडोनेशिया, मलेशिया, फिलीपींस, सिंगापुर और थाईलैंड थे। वियतनाम 1995 में शामिल हुआ।"},
  {"id":"gk-international-orgs-22","question":"Which country was the last to join SAARC, in 2007?","options":["Bhutan","Afghanistan","Maldives","Myanmar"],"answer":1,"explanation":"SAARC was founded in 1985 by seven countries; Afghanistan became the eighth member in 2007. Myanmar is not a member.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"2007 में सार्क में सबसे अंत में कौन-सा देश शामिल हुआ?","optionsHi":["भूटान","अफगानिस्तान","मालदीव","म्यांमार"],"explanationHi":"सार्क की स्थापना 1985 में सात देशों ने की थी; अफगानिस्तान 2007 में आठवाँ सदस्य बना। म्यांमार सदस्य नहीं है।"},
  {"id":"gk-international-orgs-23","question":"The Secretary-General of the United Nations is appointed by the:","options":["General Assembly alone","Security Council alone","International Court of Justice","General Assembly on the recommendation of the Security Council"],"answer":3,"explanation":"Under Article 97 of the UN Charter, the General Assembly appoints the Secretary-General on the Security Council’s recommendation, so a permanent member can veto a candidate.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र के महासचिव की नियुक्ति कौन करता है?","optionsHi":["केवल महासभा","केवल सुरक्षा परिषद","अंतर्राष्ट्रीय न्यायालय","सुरक्षा परिषद की सिफारिश पर महासभा"],"explanationHi":"संयुक्त राष्ट्र चार्टर के अनुच्छेद 97 के अंतर्गत महासभा सुरक्षा परिषद की सिफारिश पर महासचिव की नियुक्ति करती है, इसलिए कोई स्थायी सदस्य किसी उम्मीदवार पर वीटो लगा सकता है।"},
  {"id":"gk-international-orgs-24","question":"Which of these is NOT an official language of the United Nations?","options":["Arabic","Russian","Portuguese","Spanish"],"answer":2,"explanation":"The six official UN languages are Arabic, Chinese, English, French, Russian and Spanish.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन-सी संयुक्त राष्ट्र की आधिकारिक भाषा नहीं है?","optionsHi":["अरबी","रूसी","पुर्तगाली","स्पेनिश"],"explanationHi":"संयुक्त राष्ट्र की छह आधिकारिक भाषाएँ अरबी, चीनी, अंग्रेजी, फ्रेंच, रूसी और स्पेनिश हैं।"},
  {"id":"gk-international-orgs-25","question":"Match the organisation with its headquarters: 1. Food and Agriculture Organization  2. International Labour Organization  3. International Atomic Energy Agency  4. UN Environment Programme; a. Rome  b. Vienna  c. Nairobi  d. Geneva","options":["1-a, 2-d, 3-c, 4-b","1-a, 2-b, 3-d, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-b, 4-c"],"answer":2,"explanation":"FAO: Rome; ILO: Geneva; IAEA: Vienna; UNEP: Nairobi (the first UN agency headquartered in the Global South).","difficulty":"very-hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"संगठन का उसके मुख्यालय से मिलान कीजिए: 1. खाद्य एवं कृषि संगठन  2. अंतर्राष्ट्रीय श्रम संगठन  3. अंतर्राष्ट्रीय परमाणु ऊर्जा एजेंसी  4. संयुक्त राष्ट्र पर्यावरण कार्यक्रम; a. रोम  b. वियना  c. नैरोबी  d. जिनेवा","optionsHi":["1-a, 2-d, 3-c, 4-b","1-a, 2-b, 3-d, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-b, 4-c"],"explanationHi":"FAO: रोम; ILO: जिनेवा; IAEA: वियना; UNEP: नैरोबी (वैश्विक दक्षिण में मुख्यालय वाली पहली संयुक्त राष्ट्र एजेंसी)।"},
  {"id":"gk-international-orgs-26","question":"How many of these statements about the principal organs of the UN are correct? I. The Trusteeship Council suspended its operations in 1994. II. The Economic and Social Council has 54 members. III. The International Court of Justice is located in New York. IV. UNICEF is one of the six principal organs.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. The ICJ is at The Hague (III wrong). The six principal organs are the General Assembly, Security Council, ECOSOC, Trusteeship Council, ICJ and Secretariat; UNICEF is a fund created by the General Assembly (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र के प्रमुख अंगों के बारे में इनमें से कितने कथन सही हैं? I. न्यास परिषद ने 1994 में अपना कार्य निलंबित कर दिया। II. आर्थिक एवं सामाजिक परिषद के 54 सदस्य हैं। III. अंतर्राष्ट्रीय न्यायालय न्यूयॉर्क में स्थित है। IV. UNICEF छह प्रमुख अंगों में से एक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। ICJ द हेग में है (III गलत)। छह प्रमुख अंग महासभा, सुरक्षा परिषद, ECOSOC, न्यास परिषद, ICJ और सचिवालय हैं; UNICEF महासभा द्वारा बनाया गया एक कोष है (IV गलत)।"},
  {"id":"gk-international-orgs-27","question":"Assertion (A): The International Development Association (IDA) gives concessional loans and grants to the poorest countries. Reason (R): The IBRD lends to middle-income and creditworthy low-income countries on near-market terms.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but R does not explain A. They describe two different arms of the World Bank; R explains the IBRD’s role, not why the IDA lends on soft terms.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): अंतर्राष्ट्रीय विकास संघ (IDA) सबसे गरीब देशों को रियायती ऋण और अनुदान देता है। कारण (R): IBRD मध्यम आय वाले और साख-योग्य निम्न आय वाले देशों को लगभग बाजार शर्तों पर ऋण देता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं, परंतु R से A की व्याख्या नहीं होती। ये विश्व बैंक की दो अलग शाखाओं का वर्णन हैं; R IBRD की भूमिका बताता है, यह नहीं कि IDA नरम शर्तों पर ऋण क्यों देता है।"},
  {"id":"gk-international-orgs-28","question":"Arrange the founding of these organisations in chronological order: 1. SAARC  2. NATO  3. WTO  4. ASEAN","options":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"answer":0,"explanation":"NATO was founded in 1949, ASEAN in 1967, SAARC in 1985 and the WTO in 1995, giving 2, 4, 1, 3. The trap 4, 2, 1, 3 assumes ASEAN is older than NATO, and 2, 4, 3, 1 wrongly places the WTO before SAARC.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"इन संगठनों की स्थापना को कालक्रम के अनुसार व्यवस्थित कीजिए: 1. SAARC  2. NATO  3. WTO  4. ASEAN","optionsHi":["2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3","2, 4, 3, 1"],"explanationHi":"NATO की स्थापना 1949 में, ASEAN की 1967 में, SAARC की 1985 में और WTO की 1995 में हुई, जिससे क्रम 2, 4, 1, 3 बनता है। 4, 2, 1, 3 में ASEAN को NATO से पुराना मान लिया गया है, और 2, 4, 3, 1 में WTO को गलती से SAARC से पहले रखा गया है।"},
  {"id":"gk-international-orgs-29","question":"As of 2024, how many of these statements about BRICS are correct? I. Egypt and Ethiopia became members in January 2024. II. The first BRIC summit was held in Brazil in 2009. III. The New Development Bank is headquartered in New Delhi. IV. Argentina joined BRICS in January 2024.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct: Egypt, Ethiopia, Iran and the UAE joined in January 2024 (Indonesia followed in January 2025). The first BRIC summit was held at Yekaterinburg, Russia, in 2009, the New Development Bank is headquartered in Shanghai, and Argentina declined its 2023 invitation.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"2024 की स्थिति के अनुसार, ब्रिक्स के बारे में इनमें से कितने कथन सही हैं? I. मिस्र और इथियोपिया जनवरी 2024 में सदस्य बने। II. पहला BRIC शिखर सम्मेलन 2009 में ब्राजील में हुआ। III. न्यू डेवलपमेंट बैंक का मुख्यालय नई दिल्ली में है। IV. अर्जेंटीना जनवरी 2024 में ब्रिक्स में शामिल हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है: मिस्र, इथियोपिया, ईरान और UAE जनवरी 2024 में शामिल हुए (इंडोनेशिया जनवरी 2025 में जुड़ा)। पहला BRIC शिखर सम्मेलन 2009 में रूस के येकातेरिनबर्ग में हुआ था, न्यू डेवलपमेंट बैंक का मुख्यालय शंघाई में है, और अर्जेंटीना ने 2023 में मिला आमंत्रण अस्वीकार कर दिया था।"},
  {"id":"gk-international-orgs-30","question":"Which of the following is NOT a specialised agency of the United Nations?","options":["UNICEF","UNESCO","International Labour Organization","World Health Organization"],"answer":0,"explanation":"UNICEF is a fund (subsidiary body) of the General Assembly, not a specialised agency. UNESCO, WHO and ILO are specialised agencies with their own membership and budgets.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"निम्नलिखित में से कौन संयुक्त राष्ट्र की विशिष्ट एजेंसी नहीं है?","optionsHi":["UNICEF","UNESCO","अंतर्राष्ट्रीय श्रम संगठन","विश्व स्वास्थ्य संगठन"],"explanationHi":"UNICEF महासभा का एक कोष (सहायक निकाय) है, विशिष्ट एजेंसी नहीं। UNESCO, WHO और ILO की अपनी सदस्यता और बजट वाली विशिष्ट एजेंसियाँ हैं।"},
  {"id":"gk-international-orgs-31","question":"Match the grouping with the year it was founded: 1. G20  2. Shanghai Cooperation Organisation  3. BIMSTEC  4. IBSA Dialogue Forum; a. 2001  b. 1999  c. 2003  d. 1997","options":["1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-d, 4-c","1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d"],"answer":1,"explanation":"G20: 1999 (after the Asian financial crisis); SCO: 2001; BIMSTEC: 1997 (Bangkok Declaration); IBSA: 2003 (Brasilia Declaration).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"समूह का उसकी स्थापना के वर्ष से मिलान कीजिए: 1. G20  2. शंघाई सहयोग संगठन  3. BIMSTEC  4. IBSA संवाद मंच; a. 2001  b. 1999  c. 2003  d. 1997","optionsHi":["1-b, 2-d, 3-a, 4-c","1-b, 2-a, 3-d, 4-c","1-a, 2-b, 3-d, 4-c","1-b, 2-a, 3-c, 4-d"],"explanationHi":"G20: 1999 (एशियाई वित्तीय संकट के बाद); SCO: 2001; BIMSTEC: 1997 (बैंकॉक घोषणा); IBSA: 2003 (ब्रासीलिया घोषणा)।"},
  {"id":"gk-international-orgs-32","question":"How many of these statements are correct? I. The IMF is headquartered in Washington, D.C. II. The World Bank is headquartered in Washington, D.C. III. By convention the World Bank President is an American and the IMF Managing Director a European. IV. India is a founding member of the IMF.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Both Bretton Woods institutions are in Washington, D.C.; the US–Europe leadership convention has held since 1946; India attended Bretton Woods and was a founding member.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"इनमें से कितने कथन सही हैं? I. IMF का मुख्यालय वाशिंगटन, D.C. में है। II. विश्व बैंक का मुख्यालय वाशिंगटन, D.C. में है। III. परंपरा के अनुसार विश्व बैंक का अध्यक्ष अमेरिकी और IMF का प्रबंध निदेशक यूरोपीय होता है। IV. भारत IMF का संस्थापक सदस्य है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। दोनों ब्रेटन वुड्स संस्थाएँ वाशिंगटन, D.C. में हैं; अमेरिका-यूरोप नेतृत्व की परंपरा 1946 से चली आ रही है; भारत ने ब्रेटन वुड्स सम्मेलन में भाग लिया था और वह संस्थापक सदस्य था।"},
  {"id":"gk-international-orgs-33","question":"Assertion (A): Any one permanent member of the UN Security Council can block a substantive resolution. Reason (R): Substantive decisions need nine affirmative votes including the concurring votes of all permanent members.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: because Article 27(3) requires the concurrence of all five permanent members, a single negative vote (the veto) defeats the resolution. An abstention, by practice, does not count as a veto.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): संयुक्त राष्ट्र सुरक्षा परिषद का कोई भी एक स्थायी सदस्य किसी सारभूत प्रस्ताव को रोक सकता है। कारण (R): सारभूत निर्णयों के लिए सभी स्थायी सदस्यों के सहमति-मतों सहित नौ सकारात्मक मत आवश्यक होते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R से A की व्याख्या होती है: अनुच्छेद 27(3) के अनुसार पाँचों स्थायी सदस्यों की सहमति आवश्यक है, इसलिए एक भी नकारात्मक मत (वीटो) प्रस्ताव को गिरा देता है। परंपरा के अनुसार मतदान से अनुपस्थित रहना वीटो नहीं माना जाता।"},
  {"id":"gk-international-orgs-34","question":"Match the year with the country that held the G20 presidency: 1. 2022  2. 2023  3. 2024  4. 2025; a. Indonesia  b. Brazil  c. India  d. South Africa","options":["1-a, 2-c, 3-b, 4-d","1-c, 2-a, 3-b, 4-d","1-a, 2-c, 3-d, 4-b","1-a, 2-b, 3-c, 4-d"],"answer":0,"explanation":"Indonesia (Bali, 2022), India (New Delhi, 2023), Brazil (Rio de Janeiro, 2024) and South Africa (Johannesburg, 2025), the first time four developing countries held it in a row.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"वर्ष का उस देश से मिलान कीजिए जिसके पास G20 की अध्यक्षता थी: 1. 2022  2. 2023  3. 2024  4. 2025; a. इंडोनेशिया  b. ब्राजील  c. भारत  d. दक्षिण अफ्रीका","optionsHi":["1-a, 2-c, 3-b, 4-d","1-c, 2-a, 3-b, 4-d","1-a, 2-c, 3-d, 4-b","1-a, 2-b, 3-c, 4-d"],"explanationHi":"इंडोनेशिया (बाली, 2022), भारत (नई दिल्ली, 2023), ब्राजील (रियो डी जनेरियो, 2024) और दक्षिण अफ्रीका (जोहान्सबर्ग, 2025); यह पहला अवसर था जब लगातार चार विकासशील देशों ने अध्यक्षता की।"},
  {"id":"gk-international-orgs-35","question":"How many of these statements are correct? I. The BIMSTEC Secretariat is in Dhaka. II. Thailand is a member of both SAARC and BIMSTEC. III. Bhutan and Nepal are members of both SAARC and BIMSTEC. IV. The Maldives is a member of BIMSTEC.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. Thailand is in BIMSTEC but not SAARC (II wrong), and the Maldives is in SAARC but not BIMSTEC (IV wrong). BIMSTEC’s members are Bangladesh, Bhutan, India, Myanmar, Nepal, Sri Lanka and Thailand.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"इनमें से कितने कथन सही हैं? I. BIMSTEC का सचिवालय ढाका में है। II. थाईलैंड सार्क और BIMSTEC दोनों का सदस्य है। III. भूटान और नेपाल सार्क और BIMSTEC दोनों के सदस्य हैं। IV. मालदीव BIMSTEC का सदस्य है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। थाईलैंड BIMSTEC में है, सार्क में नहीं (II गलत), और मालदीव सार्क में है, BIMSTEC में नहीं (IV गलत)। BIMSTEC के सदस्य बांग्लादेश, भूटान, भारत, म्यांमार, नेपाल, श्रीलंका और थाईलैंड हैं।"},
  {"id":"gk-international-orgs-36","question":"Which of the following is NOT a member of the G7?","options":["Russia","Japan","Canada","Italy"],"answer":0,"explanation":"The G7 is the USA, UK, France, Germany, Japan, Italy and Canada, with the EU attending. Russia joined to form the G8 in 1997 but was suspended in 2014 after annexing Crimea.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"निम्नलिखित में से कौन G7 का सदस्य नहीं है?","optionsHi":["रूस","जापान","कनाडा","इटली"],"explanationHi":"G7 में अमेरिका, ब्रिटेन, फ्रांस, जर्मनी, जापान, इटली और कनाडा हैं, और यूरोपीय संघ भी भाग लेता है। रूस 1997 में G8 बनाने के लिए शामिल हुआ था, परंतु क्रीमिया के विलय के बाद 2014 में उसे निलंबित कर दिया गया।"},
  {"id":"gk-international-orgs-37","question":"Match the organisation with its role: 1. Financial Action Task Force  2. Bank for International Settlements  3. OECD  4. World Intellectual Property Organization; a. Bank for central banks  b. Standards against money laundering and terror financing  c. Policy forum mainly of developed market economies  d. Protection of patents, copyrights and trademarks","options":["1-b, 2-c, 3-a, 4-d","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-b, 2-a, 3-c, 4-d"],"answer":3,"explanation":"FATF (Paris) sets anti-money-laundering standards and keeps the grey and black lists; BIS (Basel) is the central bankers’ bank; OECD (Paris) is a policy forum of mostly rich economies; WIPO (Geneva) handles intellectual property.","difficulty":"very-hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"संगठन का उसकी भूमिका से मिलान कीजिए: 1. वित्तीय कार्रवाई कार्य बल (FATF)  2. बैंक फॉर इंटरनेशनल सेटलमेंट्स  3. OECD  4. विश्व बौद्धिक संपदा संगठन; a. केंद्रीय बैंकों का बैंक  b. धन-शोधन और आतंकवाद के वित्तपोषण के विरुद्ध मानक  c. मुख्यतः विकसित बाजार अर्थव्यवस्थाओं का नीतिगत मंच  d. पेटेंट, कॉपीराइट और ट्रेडमार्क की सुरक्षा","optionsHi":["1-b, 2-c, 3-a, 4-d","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-d, 4-c","1-b, 2-a, 3-c, 4-d"],"explanationHi":"FATF (पेरिस) धन-शोधन-रोधी मानक तय करता है और ग्रे तथा ब्लैक सूचियाँ रखता है; BIS (बेसल) केंद्रीय बैंकरों का बैंक है; OECD (पेरिस) मुख्यतः धनी अर्थव्यवस्थाओं का नीतिगत मंच है; WIPO (जिनेवा) बौद्धिक संपदा से जुड़े कार्य देखता है।"},
  {"id":"gk-international-orgs-38","question":"How many of these statements about the WTO are correct? I. Its highest decision-making body is the Ministerial Conference. II. The Ministerial Conference meets at least once every two years. III. India is a founding member of the WTO. IV. The 12th Ministerial Conference (2022) was held in Nairobi.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. MC12 was held in Geneva in June 2022; Nairobi hosted MC10 in 2015 (IV wrong).","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"WTO के बारे में इनमें से कितने कथन सही हैं? I. इसका सर्वोच्च निर्णयकारी निकाय मंत्रिस्तरीय सम्मेलन है। II. मंत्रिस्तरीय सम्मेलन कम से कम प्रत्येक दो वर्ष में एक बार होता है। III. भारत WTO का संस्थापक सदस्य है। IV. 12वाँ मंत्रिस्तरीय सम्मेलन (2022) नैरोबी में हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। MC12 जून 2022 में जिनेवा में हुआ था; नैरोबी ने 2015 में MC10 की मेजबानी की थी (IV गलत)।"},
  {"id":"gk-international-orgs-39","question":"Assertion (A): Switzerland became a member of the United Nations only in 2002. Reason (R): Switzerland has a long tradition of neutrality, and its voters had earlier rejected UN membership.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: fears that membership would compromise neutrality led Swiss voters to reject joining in a 1986 referendum; a 2002 referendum approved it.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): स्विट्जरलैंड 2002 में ही संयुक्त राष्ट्र का सदस्य बना। कारण (R): स्विट्जरलैंड की तटस्थता की लंबी परंपरा रही है, और उसके मतदाताओं ने पहले संयुक्त राष्ट्र की सदस्यता को अस्वीकार कर दिया था।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R से A की व्याख्या होती है: सदस्यता से तटस्थता प्रभावित होने के भय के कारण स्विस मतदाताओं ने 1986 के जनमत संग्रह में शामिल होने को अस्वीकार कर दिया था; 2002 के जनमत संग्रह ने इसे स्वीकृति दी।"},
  {"id":"gk-international-orgs-40","question":"Match the organisation with the year it was founded: 1. United Nations  2. League of Nations  3. African Union  4. OPEC; a. 1920  b. 2002  c. 1960  d. 1945","options":["1-d, 2-b, 3-a, 4-c","1-d, 2-a, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-a, 2-d, 3-b, 4-c"],"answer":1,"explanation":"UN: 1945; League of Nations: 1920; African Union: 2002 (succeeding the OAU of 1963); OPEC: 1960 (Baghdad).","difficulty":"very-hard","source":"SSC CGL · IBPS PO · UPSC Prelims","questionHi":"संगठन का उसकी स्थापना के वर्ष से मिलान कीजिए: 1. संयुक्त राष्ट्र  2. राष्ट्र संघ  3. अफ्रीकी संघ  4. OPEC; a. 1920  b. 2002  c. 1960  d. 1945","optionsHi":["1-d, 2-b, 3-a, 4-c","1-d, 2-a, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-a, 2-d, 3-b, 4-c"],"explanationHi":"संयुक्त राष्ट्र: 1945; राष्ट्र संघ: 1920; अफ्रीकी संघ: 2002 (1963 के OAU का उत्तराधिकारी); OPEC: 1960 (बगदाद)।"},
  {"id":"gk-international-orgs-41","question":"The headquarters of UNICEF is in:","options":["Geneva","Paris","New York","Vienna"],"answer":2,"explanation":"UNICEF (founded 1946) is headquartered in New York. Many other UN bodies are in Geneva, which makes it the tempting wrong answer.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"UNICEF का मुख्यालय कहाँ है?","optionsHi":["जिनेवा","पेरिस","न्यूयॉर्क","वियना"],"explanationHi":"UNICEF (स्थापना 1946) का मुख्यालय न्यूयॉर्क में है। संयुक्त राष्ट्र की अनेक अन्य संस्थाएँ जिनेवा में हैं, इसलिए वह भ्रमित करने वाला गलत उत्तर बन जाता है।"},
  {"id":"gk-international-orgs-42","question":"The headquarters of NATO is in:","options":["Brussels","Washington, D.C.","London","The Hague"],"answer":0,"explanation":"NATO's headquarters moved from Paris to Brussels in 1967, after France left the integrated military command.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"NATO का मुख्यालय कहाँ है?","optionsHi":["ब्रुसेल्स","वाशिंगटन, D.C.","लंदन","द हेग"],"explanationHi":"फ्रांस के एकीकृत सैन्य कमान से बाहर होने के बाद 1967 में NATO का मुख्यालय पेरिस से ब्रुसेल्स चला गया।"},
  {"id":"gk-international-orgs-43","question":"The International Committee of the Red Cross (ICRC) is headquartered in:","options":["New York","Vienna","Paris","Geneva"],"answer":3,"explanation":"The ICRC was founded in Geneva in 1863 by Henry Dunant and others and is still based there.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"अंतर्राष्ट्रीय रेड क्रॉस समिति (ICRC) का मुख्यालय कहाँ है?","optionsHi":["न्यूयॉर्क","वियना","पेरिस","जिनेवा"],"explanationHi":"ICRC की स्थापना 1863 में जिनेवा में हेनरी ड्यूनेंट और अन्य लोगों ने की थी और यह आज भी वहीं स्थित है।"},
  {"id":"gk-international-orgs-44","question":"The Commonwealth Secretariat is located in:","options":["Ottawa","London","Canberra","New Delhi"],"answer":1,"explanation":"The Commonwealth Secretariat, set up in 1965, is at Marlborough House, London.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"राष्ट्रमंडल सचिवालय कहाँ स्थित है?","optionsHi":["ओटावा","लंदन","कैनबरा","नई दिल्ली"],"explanationHi":"1965 में स्थापित राष्ट्रमंडल सचिवालय लंदन के मार्लबरो हाउस में है।"},
  {"id":"gk-international-orgs-45","question":"Amnesty International, the human rights organisation, has its headquarters in:","options":["London","Geneva","Stockholm","New York"],"answer":0,"explanation":"Amnesty International was founded in London in 1961 by Peter Benenson; its International Secretariat is in London.","difficulty":"easy","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"मानवाधिकार संगठन एमनेस्टी इंटरनेशनल का मुख्यालय कहाँ है?","optionsHi":["लंदन","जिनेवा","स्टॉकहोम","न्यूयॉर्क"],"explanationHi":"एमनेस्टी इंटरनेशनल की स्थापना 1961 में लंदन में पीटर बेनेनसन ने की थी; इसका अंतर्राष्ट्रीय सचिवालय लंदन में है।"},
  {"id":"gk-international-orgs-46","question":"The Organization of the Petroleum Exporting Countries (OPEC) has its headquarters in:","options":["Riyadh","Vienna","Geneva","Kuwait City"],"answer":1,"explanation":"OPEC was founded at Baghdad in 1960 and moved its secretariat to Vienna in 1965. Austria is not a member.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"पेट्रोलियम निर्यातक देशों के संगठन (OPEC) का मुख्यालय कहाँ है?","optionsHi":["रियाद","वियना","जिनेवा","कुवैत सिटी"],"explanationHi":"OPEC की स्थापना 1960 में बगदाद में हुई थी और 1965 में इसका सचिवालय वियना चला गया। ऑस्ट्रिया इसका सदस्य नहीं है।"},
  {"id":"gk-international-orgs-47","question":"The euro was introduced as an accounting (non-cash) currency in:","options":["1993","1999","2002","2004"],"answer":1,"explanation":"The euro began as book money on 1 January 1999; euro notes and coins came into circulation on 1 January 2002.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"यूरो को लेखांकन (गैर-नकद) मुद्रा के रूप में किस वर्ष शुरू किया गया?","optionsHi":["1993","1999","2002","2004"],"explanationHi":"यूरो की शुरुआत 1 जनवरी 1999 को बही-मुद्रा के रूप में हुई; यूरो के नोट और सिक्के 1 जनवरी 2002 को प्रचलन में आए।"},
  {"id":"gk-international-orgs-48","question":"The headquarters of Interpol is in:","options":["Lyon","Paris","Brussels","Vienna"],"answer":0,"explanation":"Interpol (founded 1923 in Vienna) has had its General Secretariat in Lyon, France, since 1989.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"इंटरपोल का मुख्यालय कहाँ है?","optionsHi":["लियों","पेरिस","ब्रुसेल्स","वियना"],"explanationHi":"इंटरपोल (स्थापना 1923, वियना) का महासचिवालय 1989 से फ्रांस के लियों में है।"},
  {"id":"gk-international-orgs-49","question":"The first session of the UN General Assembly was held in January 1946 in:","options":["New York","San Francisco","London","Geneva"],"answer":2,"explanation":"The first session met at Methodist Central Hall, London. The UN Charter had been signed at San Francisco in June 1945.","difficulty":"moderate","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र महासभा का पहला सत्र जनवरी 1946 में कहाँ आयोजित हुआ था?","optionsHi":["न्यूयॉर्क","सैन फ्रांसिस्को","लंदन","जिनेवा"],"explanationHi":"पहला सत्र लंदन के मेथोडिस्ट सेंट्रल हॉल में हुआ था। संयुक्त राष्ट्र चार्टर पर जून 1945 में सैन फ्रांसिस्को में हस्ताक्षर हुए थे।"},
  {"id":"gk-international-orgs-50","question":"The World Wide Fund for Nature (WWF) is headquartered at:","options":["Gland, Switzerland","Nairobi, Kenya","Washington, D.C.","Bonn, Germany"],"answer":0,"explanation":"WWF International is based at Gland, Switzerland; the IUCN is also headquartered there.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"वर्ल्ड वाइड फंड फॉर नेचर (WWF) का मुख्यालय कहाँ है?","optionsHi":["ग्लैंड, स्विट्जरलैंड","नैरोबी, केन्या","वाशिंगटन, D.C.","बॉन, जर्मनी"],"explanationHi":"WWF इंटरनेशनल का मुख्यालय ग्लैंड (स्विट्जरलैंड) में है; IUCN का मुख्यालय भी वहीं है।"},
  {"id":"gk-international-orgs-51","question":"The headquarters of the African Union is in:","options":["Nairobi","Johannesburg","Addis Ababa","Cairo"],"answer":2,"explanation":"The African Union (2002), successor to the OAU (1963), has its headquarters in Addis Ababa, Ethiopia.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"अफ्रीकी संघ का मुख्यालय कहाँ है?","optionsHi":["नैरोबी","जोहान्सबर्ग","अदीस अबाबा","काहिरा"],"explanationHi":"अफ्रीकी संघ (2002), जो OAU (1963) का उत्तराधिकारी है, का मुख्यालय इथियोपिया के अदीस अबाबा में है।"},
  {"id":"gk-international-orgs-52","question":"The Quadrilateral Security Dialogue (Quad) brings together India, the United States, Japan and:","options":["South Korea","Australia","France","the United Kingdom"],"answer":1,"explanation":"The Quad comprises India, the USA, Japan and Australia; its leaders first met in 2021.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"चतुर्भुज सुरक्षा संवाद (क्वाड) में भारत, संयुक्त राज्य अमेरिका, जापान और कौन-सा देश शामिल है?","optionsHi":["दक्षिण कोरिया","ऑस्ट्रेलिया","फ्रांस","यूनाइटेड किंगडम"],"explanationHi":"क्वाड में भारत, अमेरिका, जापान और ऑस्ट्रेलिया शामिल हैं; इसके नेताओं की पहली बैठक 2021 में हुई थी।"},
  {"id":"gk-international-orgs-53","question":"UN-Habitat, the UN programme for human settlements, is headquartered in:","options":["Nairobi","Rome","Bangkok","Geneva"],"answer":0,"explanation":"UN-Habitat, like UNEP, has its headquarters in Nairobi, Kenya.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"मानव बस्तियों से संबंधित संयुक्त राष्ट्र कार्यक्रम UN-Habitat का मुख्यालय कहाँ है?","optionsHi":["नैरोबी","रोम","बैंकॉक","जिनेवा"],"explanationHi":"UN-Habitat का मुख्यालय, UNEP की तरह, केन्या के नैरोबी में है।"},
  {"id":"gk-international-orgs-54","question":"The International Solar Alliance was launched in 2015 at the COP21 climate summit in Paris by India and:","options":["The United States","Germany","France","Japan"],"answer":2,"explanation":"Prime Minister Modi and President Hollande launched the ISA; its headquarters is at Gurugram, India, making it the first treaty-based international body based in India.","difficulty":"moderate","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"अंतर्राष्ट्रीय सौर गठबंधन की शुरुआत 2015 में पेरिस के COP21 जलवायु शिखर सम्मेलन में भारत और किस देश ने की थी?","optionsHi":["संयुक्त राज्य अमेरिका","जर्मनी","फ्रांस","जापान"],"explanationHi":"प्रधानमंत्री मोदी और राष्ट्रपति ओलांद ने ISA की शुरुआत की; इसका मुख्यालय भारत के गुरुग्राम में है, जिससे यह भारत में स्थित पहला संधि-आधारित अंतर्राष्ट्रीय निकाय है।"},
  {"id":"gk-international-orgs-55","question":"Which country became the 193rd member of the United Nations in 2011?","options":["Montenegro","Timor-Leste","South Sudan","Kosovo"],"answer":2,"explanation":"South Sudan became independent and joined the UN in July 2011. Kosovo is not a UN member; Montenegro joined in 2006.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2011 में कौन-सा देश संयुक्त राष्ट्र का 193वाँ सदस्य बना?","optionsHi":["मोंटेनेग्रो","तिमोर-लेस्ते","दक्षिण सूडान","कोसोवो"],"explanationHi":"दक्षिण सूडान जुलाई 2011 में स्वतंत्र हुआ और संयुक्त राष्ट्र में शामिल हुआ। कोसोवो संयुक्त राष्ट्र का सदस्य नहीं है; मोंटेनेग्रो 2006 में शामिल हुआ था।"},
  {"id":"gk-international-orgs-56","question":"The UN Human Rights Council, set up in 2006, replaced the:","options":["UN Trusteeship Council","UN Commission on Human Rights","Office of the High Commissioner for Human Rights","International Labour Organization"],"answer":1,"explanation":"The 47-member Human Rights Council, based in Geneva, replaced the discredited Commission on Human Rights (1946–2006). The OHCHR still exists as its secretariat.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2006 में स्थापित संयुक्त राष्ट्र मानवाधिकार परिषद ने किसका स्थान लिया?","optionsHi":["संयुक्त राष्ट्र न्यास परिषद","संयुक्त राष्ट्र मानवाधिकार आयोग","मानवाधिकार उच्चायुक्त का कार्यालय","अंतर्राष्ट्रीय श्रम संगठन"],"explanationHi":"जिनेवा में स्थित 47 सदस्यीय मानवाधिकार परिषद ने साख खो चुके मानवाधिकार आयोग (1946-2006) का स्थान लिया। OHCHR अब भी इसके सचिवालय के रूप में कार्य करता है।"},
  {"id":"gk-international-orgs-57","question":"The headquarters of the Universal Postal Union is in:","options":["Geneva","Bern","Vienna","Paris"],"answer":1,"explanation":"The UPU, founded in 1874, is based in Bern, Switzerland. World Post Day (9 October) marks its founding.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"विश्व डाक संघ का मुख्यालय कहाँ है?","optionsHi":["जिनेवा","बर्न","वियना","पेरिस"],"explanationHi":"UPU (स्थापना 1874) का मुख्यालय स्विट्जरलैंड के बर्न में है। विश्व डाक दिवस (9 अक्टूबर) इसकी स्थापना की स्मृति में मनाया जाता है।"},
  {"id":"gk-international-orgs-58","question":"Which is the oldest specialised agency in the UN system, founded in 1865?","options":["Universal Postal Union","International Labour Organization","International Telecommunication Union","World Meteorological Organization"],"answer":2,"explanation":"The ITU began as the International Telegraph Union in 1865; the UPU came in 1874 and the ILO in 1919.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र प्रणाली की सबसे पुरानी विशिष्ट एजेंसी, जिसकी स्थापना 1865 में हुई, कौन-सी है?","optionsHi":["विश्व डाक संघ","अंतर्राष्ट्रीय श्रम संगठन","अंतर्राष्ट्रीय दूरसंचार संघ","विश्व मौसम विज्ञान संगठन"],"explanationHi":"ITU की शुरुआत 1865 में अंतर्राष्ट्रीय टेलीग्राफ संघ के रूप में हुई; UPU 1874 में और ILO 1919 में आया।"},
  {"id":"gk-international-orgs-59","question":"The International Fund for Agricultural Development (IFAD) is headquartered in:","options":["Rome","Nairobi","Manila","Geneva"],"answer":0,"explanation":"IFAD, like the FAO and the World Food Programme, is based in Rome.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"अंतर्राष्ट्रीय कृषि विकास कोष (IFAD) का मुख्यालय कहाँ है?","optionsHi":["रोम","नैरोबी","मनीला","जिनेवा"],"explanationHi":"IFAD का मुख्यालय, FAO और विश्व खाद्य कार्यक्रम की तरह, रोम में है।"},
  {"id":"gk-international-orgs-60","question":"The Asian Development Bank has its headquarters in:","options":["Beijing","Tokyo","Manila","Singapore"],"answer":2,"explanation":"The ADB (1966) is headquartered in Mandaluyong, Metro Manila. Beijing is the seat of the AIIB.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"एशियाई विकास बैंक का मुख्यालय कहाँ है?","optionsHi":["बीजिंग","टोक्यो","मनीला","सिंगापुर"],"explanationHi":"ADB (1966) का मुख्यालय मेट्रो मनीला के मंडालुयोंग में है। बीजिंग AIIB का मुख्यालय है।"},
  {"id":"gk-international-orgs-61","question":"The Wassenaar Arrangement, which India joined in December 2017, deals with:","options":["Export controls on conventional arms and dual-use goods","Nuclear fuel supply","Climate finance","Trade in endangered species"],"answer":0,"explanation":"The Wassenaar Arrangement (1996) is a voluntary export-control regime for conventional arms and dual-use technologies. India is also in the MTCR and the Australia Group.","difficulty":"hard","source":"UPSC Prelims","questionHi":"वासेनार व्यवस्था, जिसमें भारत दिसंबर 2017 में शामिल हुआ, किससे संबंधित है?","optionsHi":["पारंपरिक हथियारों और दोहरे उपयोग वाली वस्तुओं पर निर्यात नियंत्रण","परमाणु ईंधन की आपूर्ति","जलवायु वित्त","संकटग्रस्त प्रजातियों का व्यापार"],"explanationHi":"वासेनार व्यवस्था (1996) पारंपरिक हथियारों और दोहरे उपयोग वाली प्रौद्योगिकियों के लिए एक स्वैच्छिक निर्यात-नियंत्रण व्यवस्था है। भारत MTCR और ऑस्ट्रेलिया समूह का भी सदस्य है।"},
  {"id":"gk-international-orgs-62","question":"India became a member of the Missile Technology Control Regime (MTCR) in:","options":["2008","2016","2018","2020"],"answer":1,"explanation":"India joined the MTCR in June 2016, the Wassenaar Arrangement in 2017 and the Australia Group in 2018. It is still not in the Nuclear Suppliers Group.","difficulty":"hard","source":"UPSC Prelims","questionHi":"भारत मिसाइल प्रौद्योगिकी नियंत्रण व्यवस्था (MTCR) का सदस्य कब बना?","optionsHi":["2008","2016","2018","2020"],"explanationHi":"भारत जून 2016 में MTCR में, 2017 में वासेनार व्यवस्था में और 2018 में ऑस्ट्रेलिया समूह में शामिल हुआ। वह अब भी परमाणु आपूर्तिकर्ता समूह का सदस्य नहीं है।"},
  {"id":"gk-international-orgs-63","question":"The Nuclear Suppliers Group was formed in 1974 in response to:","options":["The Chernobyl accident","India's first nuclear test","China's first nuclear test","The signing of the NPT"],"answer":1,"explanation":"India's 'peaceful nuclear explosion' at Pokhran in May 1974 led supplier countries to form the NSG to control nuclear exports. Chernobyl was in 1986.","difficulty":"hard","source":"UPSC Prelims","questionHi":"परमाणु आपूर्तिकर्ता समूह का गठन 1974 में किस घटना की प्रतिक्रिया में हुआ था?","optionsHi":["चेर्नोबिल दुर्घटना","भारत का पहला परमाणु परीक्षण","चीन का पहला परमाणु परीक्षण","NPT पर हस्ताक्षर"],"explanationHi":"मई 1974 में पोखरण में भारत के ‘शांतिपूर्ण परमाणु विस्फोट’ के बाद आपूर्तिकर्ता देशों ने परमाणु निर्यात को नियंत्रित करने के लिए NSG बनाया। चेर्नोबिल दुर्घटना 1986 में हुई थी।"},
  {"id":"gk-international-orgs-64","question":"The secretariat of the Indian Ocean Rim Association (IORA) is located at:","options":["Ebene, Mauritius","Colombo, Sri Lanka","Perth, Australia","Durban, South Africa"],"answer":0,"explanation":"IORA, founded in 1997, has its secretariat at Ebene, Mauritius.","difficulty":"hard","source":"UPSC Prelims","questionHi":"हिंद महासागर रिम संघ (IORA) का सचिवालय कहाँ स्थित है?","optionsHi":["एबेन, मॉरीशस","कोलंबो, श्रीलंका","पर्थ, ऑस्ट्रेलिया","डरबन, दक्षिण अफ्रीका"],"explanationHi":"IORA (स्थापना 1997) का सचिवालय मॉरीशस के एबेन में है।"},
  {"id":"gk-international-orgs-65","question":"Which of the following is NOT a member of the Mekong–Ganga Cooperation?","options":["Laos","Cambodia","Malaysia","Vietnam"],"answer":2,"explanation":"The Mekong–Ganga Cooperation (2000) has six members: India, Cambodia, Laos, Myanmar, Thailand and Vietnam. Malaysia is not on the Mekong.","difficulty":"hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन मेकांग-गंगा सहयोग का सदस्य नहीं है?","optionsHi":["लाओस","कंबोडिया","मलेशिया","वियतनाम"],"explanationHi":"मेकांग-गंगा सहयोग (2000) के छह सदस्य हैं: भारत, कंबोडिया, लाओस, म्यांमार, थाईलैंड और वियतनाम। मलेशिया मेकांग नदी पर स्थित नहीं है।"},
  {"id":"gk-international-orgs-66","question":"Which country became the 32nd member of NATO in March 2024?","options":["Finland","Sweden","Ukraine","Montenegro"],"answer":1,"explanation":"Sweden joined on 7 March 2024, taking NATO to 32 members as of 2024; Finland had joined in April 2023 as the 31st member, both after Russia's invasion of Ukraine.","difficulty":"hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"मार्च 2024 में कौन-सा देश NATO का 32वाँ सदस्य बना?","optionsHi":["फिनलैंड","स्वीडन","यूक्रेन","मोंटेनेग्रो"],"explanationHi":"स्वीडन 7 मार्च 2024 को शामिल हुआ, जिससे 2024 की स्थिति में NATO के 32 सदस्य हो गए; फिनलैंड अप्रैल 2023 में 31वें सदस्य के रूप में शामिल हुआ था, दोनों रूस के यूक्रेन पर आक्रमण के बाद।"},
  {"id":"gk-international-orgs-67","question":"As of its 2021–22 term, how many times has India served as a non-permanent member of the UN Security Council?","options":["Six","Seven","Eight","Nine"],"answer":2,"explanation":"India has been elected eight times: 1950–51, 1967–68, 1972–73, 1977–78, 1984–85, 1991–92, 2011–12 and 2021–22.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2021-22 के कार्यकाल तक, भारत कितनी बार संयुक्त राष्ट्र सुरक्षा परिषद का अस्थायी सदस्य रहा है?","optionsHi":["छह","सात","आठ","नौ"],"explanationHi":"भारत आठ बार चुना गया है: 1950-51, 1967-68, 1972-73, 1977-78, 1984-85, 1991-92, 2011-12 और 2021-22।"},
  {"id":"gk-international-orgs-68","question":"Match the UN specialised agency with its headquarters: A. UNIDO B. ICAO C. IMO D. WMO — 1. Geneva 2. London 3. Montreal 4. Vienna","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"UNIDO – Vienna; ICAO (civil aviation) – Montreal; IMO (maritime) – London; WMO (meteorology) – Geneva.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र की विशिष्ट एजेंसी का उसके मुख्यालय से मिलान कीजिए: A. UNIDO B. ICAO C. IMO D. WMO — 1. जिनेवा 2. लंदन 3. मॉन्ट्रियल 4. वियना","optionsHi":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"explanationHi":"UNIDO - वियना; ICAO (नागरिक विमानन) - मॉन्ट्रियल; IMO (समुद्री) - लंदन; WMO (मौसम विज्ञान) - जिनेवा।"},
  {"id":"gk-international-orgs-69","question":"Arrange in chronological order: 1. The European Union comes into being under the Maastricht Treaty 2. The Treaty of Rome sets up the European Economic Community 3. The United Kingdom leaves the EU 4. Euro notes and coins enter circulation","options":["2-1-3-4","2-4-1-3","1-2-4-3","2-1-4-3"],"answer":3,"explanation":"Treaty of Rome 1957; Maastricht Treaty in force 1993; euro cash 2002; Brexit on 31 January 2020.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. मास्ट्रिख्ट संधि के अंतर्गत यूरोपीय संघ का अस्तित्व में आना 2. रोम की संधि द्वारा यूरोपीय आर्थिक समुदाय की स्थापना 3. यूनाइटेड किंगडम का यूरोपीय संघ से बाहर होना 4. यूरो के नोटों और सिक्कों का प्रचलन में आना","optionsHi":["2-1-3-4","2-4-1-3","1-2-4-3","2-1-4-3"],"explanationHi":"रोम की संधि 1957; मास्ट्रिख्ट संधि लागू 1993; यूरो नकद 2002; ब्रेक्ज़िट 31 जनवरी 2020 को।"},
  {"id":"gk-international-orgs-70","question":"How many of these statements about the UN General Assembly are correct? I. Each member state has one vote. II. Decisions on important questions need a two-thirds majority of members present and voting. III. Its resolutions are legally binding on all members. IV. Its President is elected for a two-year term.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. General Assembly resolutions are recommendations (only the Security Council's decisions bind members), and its President serves a one-year session.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र महासभा के बारे में इनमें से कितने कथन सही हैं? I. प्रत्येक सदस्य राज्य का एक मत होता है। II. महत्त्वपूर्ण प्रश्नों पर निर्णय के लिए उपस्थित और मतदान करने वाले सदस्यों के दो-तिहाई बहुमत की आवश्यकता होती है। III. इसके प्रस्ताव सभी सदस्यों पर विधिक रूप से बाध्यकारी होते हैं। IV. इसका अध्यक्ष दो वर्ष के कार्यकाल के लिए चुना जाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। महासभा के प्रस्ताव सिफारिशें होते हैं (केवल सुरक्षा परिषद के निर्णय सदस्यों पर बाध्यकारी होते हैं), और इसका अध्यक्ष एक वर्ष के सत्र के लिए कार्य करता है।"},
  {"id":"gk-international-orgs-71","question":"Assertion (A): India is not a member of the Nuclear Suppliers Group. Reason (R): India has not signed the Nuclear Non-Proliferation Treaty.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true, and R explains A: India's bid (since 2016) has been blocked mainly by China and a few others on the ground that NSG members should be NPT parties.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): भारत परमाणु आपूर्तिकर्ता समूह का सदस्य नहीं है। कारण (R): भारत ने परमाणु अप्रसार संधि पर हस्ताक्षर नहीं किए हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R से A की व्याख्या होती है: भारत की सदस्यता की कोशिश (2016 से) को मुख्यतः चीन और कुछ अन्य देशों ने इस आधार पर रोका है कि NSG के सदस्यों को NPT का पक्षकार होना चाहिए।"},
  {"id":"gk-international-orgs-72","question":"Assertion (A): The WTO's Appellate Body has been unable to hear appeals since December 2019. Reason (R): The WTO Ministerial Conference must meet at least once every two years.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but R does not explain A. The Appellate Body stopped working because the United States blocked the appointment of new members, leaving it without a quorum.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): WTO का अपील निकाय दिसंबर 2019 से अपीलों की सुनवाई करने में असमर्थ है। कारण (R): WTO के मंत्रिस्तरीय सम्मेलन की बैठक कम से कम प्रत्येक दो वर्ष में एक बार होनी चाहिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं, परंतु R से A की व्याख्या नहीं होती। अपील निकाय इसलिए काम करना बंद कर गया क्योंकि अमेरिका ने नए सदस्यों की नियुक्ति रोक दी, जिससे उसके पास गणपूर्ति नहीं रही।"},
  {"id":"gk-international-orgs-73","question":"Match the grouping with its members: A. IBSA B. BASIC C. RIC D. I2U2 — 1. Russia, India, China 2. India, Israel, UAE, USA 3. India, Brazil, South Africa 4. Brazil, South Africa, India, China","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"answer":0,"explanation":"IBSA (2003) – India, Brazil, South Africa; BASIC (climate bloc, 2009) – Brazil, South Africa, India, China; RIC – Russia, India, China; I2U2 (2021–22) – India, Israel, UAE, USA.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"समूह का उसके सदस्यों से मिलान कीजिए: A. IBSA B. BASIC C. RIC D. I2U2 — 1. रूस, भारत, चीन 2. भारत, इज़राइल, UAE, अमेरिका 3. भारत, ब्राजील, दक्षिण अफ्रीका 4. ब्राजील, दक्षिण अफ्रीका, भारत, चीन","optionsHi":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"explanationHi":"IBSA (2003) - भारत, ब्राजील, दक्षिण अफ्रीका; BASIC (जलवायु समूह, 2009) - ब्राजील, दक्षिण अफ्रीका, भारत, चीन; RIC - रूस, भारत, चीन; I2U2 (2021-22) - भारत, इज़राइल, UAE, अमेरिका।"},
  {"id":"gk-international-orgs-74","question":"As of 2024, how many of these statements about the Shanghai Cooperation Organisation are correct? I. It was founded in 2001 in Shanghai. II. Iran became a full member in 2023. III. Belarus became a full member in 2024. IV. Its official languages are Russian and Chinese.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Iran joined at the July 2023 summit hosted virtually by India, and Belarus at the Astana summit in July 2024.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"2024 की स्थिति के अनुसार, शंघाई सहयोग संगठन के बारे में इनमें से कितने कथन सही हैं? I. इसकी स्थापना 2001 में शंघाई में हुई। II. ईरान 2023 में पूर्ण सदस्य बना। III. बेलारूस 2024 में पूर्ण सदस्य बना। IV. इसकी आधिकारिक भाषाएँ रूसी और चीनी हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। ईरान जुलाई 2023 के शिखर सम्मेलन में शामिल हुआ, जिसकी मेजबानी भारत ने वर्चुअल रूप से की थी, और बेलारूस जुलाई 2024 के अस्ताना शिखर सम्मेलन में शामिल हुआ।"},
  {"id":"gk-international-orgs-75","question":"Which one of the following is NOT a member of the G20?","options":["Argentina","Saudi Arabia","Spain","Turkey"],"answer":2,"explanation":"Spain attends every G20 summit as a permanent guest but is not a member. The G20 has 19 countries plus the European Union and the African Union.","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"निम्नलिखित में से कौन G20 का सदस्य नहीं है?","optionsHi":["अर्जेंटीना","सऊदी अरब","स्पेन","तुर्की"],"explanationHi":"स्पेन प्रत्येक G20 शिखर सम्मेलन में स्थायी अतिथि के रूप में भाग लेता है, परंतु सदस्य नहीं है। G20 में 19 देश तथा यूरोपीय संघ और अफ्रीकी संघ हैं।"},
  {"id":"gk-international-orgs-76","question":"Match the UN Secretary-General with his country: A. Kofi Annan B. Ban Ki-moon C. Boutros Boutros-Ghali D. Javier Pérez de Cuéllar — 1. Peru 2. Egypt 3. South Korea 4. Ghana","options":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1"],"answer":1,"explanation":"Annan – Ghana (1997–2006); Ban Ki-moon – South Korea (2007–16); Boutros-Ghali – Egypt (1992–96); Pérez de Cuéllar – Peru (1982–91).","difficulty":"very-hard","source":"IBPS PO · SBI PO · SSC CGL","questionHi":"संयुक्त राष्ट्र महासचिव का उसके देश से मिलान कीजिए: A. कोफी अन्नान B. बान की-मून C. बुतरस बुतरस-घाली D. हाविएर पेरेज़ डी कुएयार — 1. पेरू 2. मिस्र 3. दक्षिण कोरिया 4. घाना","optionsHi":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"अन्नान - घाना (1997-2006); बान की-मून - दक्षिण कोरिया (2007-16); बुतरस-घाली - मिस्र (1992-96); पेरेज़ डी कुएयार - पेरू (1982-91)।"},
  {"id":"gk-international-orgs-77","question":"Arrange these UN Secretaries-General by the start of their term: 1. U Thant 2. Kurt Waldheim 3. Dag Hammarskjöld 4. António Guterres","options":["3-1-2-4","1-3-2-4","3-2-1-4","3-1-4-2"],"answer":0,"explanation":"Hammarskjöld 1953; U Thant 1961 (after Hammarskjöld died in an air crash); Waldheim 1972; Guterres 2017.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन संयुक्त राष्ट्र महासचिवों को उनके कार्यकाल के आरंभ के अनुसार व्यवस्थित कीजिए: 1. यू थांट 2. कर्ट वाल्डहाइम 3. डैग हैमरशोल्ड 4. एंटोनियो गुटेरेस","optionsHi":["3-1-2-4","1-3-2-4","3-2-1-4","3-1-4-2"],"explanationHi":"हैमरशोल्ड 1953; यू थांट 1961 (हैमरशोल्ड की विमान दुर्घटना में मृत्यु के बाद); वाल्डहाइम 1972; गुटेरेस 2017।"},
  {"id":"gk-international-orgs-78","question":"How many of these statements about the World Bank Group are correct? I. The IFC lends to and invests in the private sector. II. MIGA provides facilities for settling investment disputes. III. ICSID insures investors against political risk. IV. The President of the World Bank has traditionally been a European.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. The roles of II and III are swapped: MIGA insures investors against political risk and ICSID settles investment disputes. By convention the World Bank President is an American and the IMF head a European.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"विश्व बैंक समूह के बारे में इनमें से कितने कथन सही हैं? I. IFC निजी क्षेत्र को ऋण देता है और उसमें निवेश करता है। II. MIGA निवेश विवादों के निपटारे की सुविधाएँ प्रदान करता है। III. ICSID निवेशकों को राजनीतिक जोखिम के विरुद्ध बीमा देता है। IV. विश्व बैंक का अध्यक्ष परंपरागत रूप से यूरोपीय रहा है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। II और III की भूमिकाएँ आपस में बदल दी गई हैं: MIGA निवेशकों को राजनीतिक जोखिम के विरुद्ध बीमा देता है और ICSID निवेश विवादों का निपटारा करता है। परंपरा के अनुसार विश्व बैंक का अध्यक्ष अमेरिकी और IMF का प्रमुख यूरोपीय होता है।"},
  {"id":"gk-international-orgs-79","question":"Assertion (A): The United States has an effective veto over major decisions of the IMF. Reason (R): Such decisions need an 85% majority of votes, and the US holds more than 15% of the voting power.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: with about 16.5% of the votes, the US alone can block any decision that needs 85%.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): संयुक्त राज्य अमेरिका के पास IMF के प्रमुख निर्णयों पर प्रभावी वीटो है। कारण (R): ऐसे निर्णयों के लिए 85% मतों के बहुमत की आवश्यकता होती है, और अमेरिका के पास 15% से अधिक मताधिकार है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं और R से A की व्याख्या होती है: लगभग 16.5% मतों के साथ अमेरिका अकेले ही 85% वाले किसी भी निर्णय को रोक सकता है।"},
  {"id":"gk-international-orgs-80","question":"Match the organisation with the city of its headquarters: A. APEC B. Gulf Cooperation Council C. Organization of American States D. Arab League — 1. Cairo 2. Washington, D.C. 3. Riyadh 4. Singapore","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-2, D-3"],"answer":2,"explanation":"APEC secretariat – Singapore; GCC – Riyadh; OAS – Washington, D.C.; Arab League – Cairo.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संगठन का उसके मुख्यालय वाले शहर से मिलान कीजिए: A. APEC B. खाड़ी सहयोग परिषद C. अमेरिकी राज्यों का संगठन D. अरब लीग — 1. काहिरा 2. वाशिंगटन, D.C. 3. रियाद 4. सिंगापुर","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-4, B-1, C-2, D-3"],"explanationHi":"APEC सचिवालय - सिंगापुर; GCC - रियाद; OAS - वाशिंगटन, D.C.; अरब लीग - काहिरा।"},
  {"id":"gk-international-orgs-81","question":"Which one of the following countries is NOT a member of the Indian Ocean Rim Association?","options":["Pakistan","Mauritius","Bangladesh","Sri Lanka"],"answer":0,"explanation":"Pakistan is not an IORA member (its application has been blocked). IORA's 23 members include India, Australia, South Africa, Iran, the UAE, France and Bangladesh.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निम्नलिखित में से कौन-सा देश हिंद महासागर रिम संघ का सदस्य नहीं है?","optionsHi":["पाकिस्तान","मॉरीशस","बांग्लादेश","श्रीलंका"],"explanationHi":"पाकिस्तान IORA का सदस्य नहीं है (उसके आवेदन को रोका गया है)। IORA के 23 सदस्यों में भारत, ऑस्ट्रेलिया, दक्षिण अफ्रीका, ईरान, UAE, फ्रांस और बांग्लादेश शामिल हैं।"},
  {"id":"gk-international-orgs-82","question":"How many of these statements are correct? I. The International Criminal Court was set up under the Rome Statute, which came into force in 2002. II. The ICC is a principal organ of the United Nations. III. India is not a party to the Rome Statute. IV. The International Court of Justice settles legal disputes between states.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. The ICC is an independent treaty body at The Hague, not a UN organ; the ICJ is the UN's principal judicial organ.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. अंतर्राष्ट्रीय आपराधिक न्यायालय की स्थापना रोम संविधि के अंतर्गत हुई, जो 2002 में लागू हुई। II. ICC संयुक्त राष्ट्र का एक प्रमुख अंग है। III. भारत रोम संविधि का पक्षकार नहीं है। IV. अंतर्राष्ट्रीय न्यायालय राज्यों के बीच विधिक विवादों का निपटारा करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, III और IV सही हैं। ICC द हेग में स्थित एक स्वतंत्र संधि-आधारित निकाय है, संयुक्त राष्ट्र का अंग नहीं; ICJ संयुक्त राष्ट्र का प्रमुख न्यायिक अंग है।"},
  {"id":"gk-international-orgs-83","question":"Assertion (A): The G7 became the G8 in 1997 with the admission of China. Reason (R): Russia was suspended from the G8 in 2014 after it annexed Crimea.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A is false: the G8 was formed with Russia, not China (formally from 1997–98). R is true: Russia was suspended in 2014, and the group reverted to the G7.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): चीन को शामिल किए जाने के साथ 1997 में G7, G8 बन गया। कारण (R): 2014 में क्रीमिया के विलय के बाद रूस को G8 से निलंबित कर दिया गया।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"A असत्य है: G8 रूस के साथ बना था, चीन के साथ नहीं (औपचारिक रूप से 1997-98 से)। R सत्य है: रूस को 2014 में निलंबित कर दिया गया और समूह पुनः G7 हो गया।"},
  {"id":"gk-international-orgs-84","question":"Arrange in chronological order: 1. India becomes a full member of the SCO 2. First BRIC summit 3. First G20 leaders' summit 4. African Union joins the G20","options":["3-2-1-4","2-3-1-4","3-1-2-4","3-2-4-1"],"answer":0,"explanation":"First G20 leaders' summit, Washington, November 2008; first BRIC summit, Yekaterinburg, June 2009; India joined the SCO in 2017; the African Union joined the G20 in 2023.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. भारत का SCO का पूर्ण सदस्य बनना 2. पहला BRIC शिखर सम्मेलन 3. पहला G20 नेताओं का शिखर सम्मेलन 4. अफ्रीकी संघ का G20 में शामिल होना","optionsHi":["3-2-1-4","2-3-1-4","3-1-2-4","3-2-4-1"],"explanationHi":"पहला G20 नेताओं का शिखर सम्मेलन, वाशिंगटन, नवंबर 2008; पहला BRIC शिखर सम्मेलन, येकातेरिनबर्ग, जून 2009; भारत 2017 में SCO में शामिल हुआ; अफ्रीकी संघ 2023 में G20 में शामिल हुआ।"},
  {"id":"gk-international-orgs-85","question":"Match the body with its work: A. IRENA B. IPCC C. IEA D. IUCN — 1. Publishes the Red List of threatened species 2. Promotes renewable energy, from its seat in Abu Dhabi 3. Assesses the science of climate change 4. Works on energy security, from its seat in Paris","options":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":3,"explanation":"IRENA – renewable energy (Abu Dhabi); IPCC – climate science assessments (with UNEP and WMO); IEA – energy security (Paris, set up after the 1973 oil crisis); IUCN – Red List (Gland).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निकाय का उसके कार्य से मिलान कीजिए: A. IRENA B. IPCC C. IEA D. IUCN — 1. संकटग्रस्त प्रजातियों की रेड लिस्ट प्रकाशित करता है 2. अबू धाबी स्थित अपने मुख्यालय से नवीकरणीय ऊर्जा को बढ़ावा देता है 3. जलवायु परिवर्तन के विज्ञान का आकलन करता है 4. पेरिस स्थित अपने मुख्यालय से ऊर्जा सुरक्षा पर कार्य करता है","optionsHi":["A-2, B-3, C-1, D-4","A-3, B-2, C-4, D-1","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"explanationHi":"IRENA - नवीकरणीय ऊर्जा (अबू धाबी); IPCC - जलवायु विज्ञान के आकलन (UNEP और WMO के साथ); IEA - ऊर्जा सुरक्षा (पेरिस, 1973 के तेल संकट के बाद स्थापित); IUCN - रेड लिस्ट (ग्लैंड)।"},
  {"id":"gk-international-orgs-86","question":"The United Nations came into existence in the year:","options":["1919","1945","1948","1950"],"answer":1,"explanation":"The UN was founded in 1945 after the Second World War, replacing the League of Nations, which had been set up in 1919–20.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"संयुक्त राष्ट्र किस वर्ष अस्तित्व में आया?","optionsHi":["1919","1945","1948","1950"],"explanationHi":"द्वितीय विश्व युद्ध के बाद 1945 में संयुक्त राष्ट्र की स्थापना हुई, जिसने 1919-20 में बने राष्ट्र संघ का स्थान लिया।"},
  {"id":"gk-international-orgs-87","question":"The World Bank has its headquarters in:","options":["New York","Geneva","London","Washington, D.C."],"answer":3,"explanation":"Both the World Bank and the IMF, the Bretton Woods twins, are based in Washington, D.C. The UN itself is headquartered in New York.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"विश्व बैंक का मुख्यालय कहाँ है?","optionsHi":["न्यूयॉर्क","जिनेवा","लंदन","वाशिंगटन, D.C."],"explanationHi":"विश्व बैंक और IMF, दोनों ब्रेटन वुड्स जुड़वाँ संस्थाएँ, वाशिंगटन, D.C. में स्थित हैं। संयुक्त राष्ट्र का मुख्यालय स्वयं न्यूयॉर्क में है।"},
  {"id":"gk-international-orgs-88","question":"The secretariat of the UN Framework Convention on Climate Change (UNFCCC) is located in:","options":["Bonn","Nairobi","Geneva","Paris"],"answer":0,"explanation":"The UNFCCC secretariat is in Bonn, Germany. Nairobi hosts UNEP, and the Paris Agreement is named after the city of COP21, not the secretariat's seat.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"संयुक्त राष्ट्र जलवायु परिवर्तन फ्रेमवर्क कन्वेंशन (UNFCCC) का सचिवालय कहाँ स्थित है?","optionsHi":["बॉन","नैरोबी","जिनेवा","पेरिस"],"explanationHi":"UNFCCC का सचिवालय जर्मनी के बॉन में है। नैरोबी में UNEP है, और पेरिस समझौते का नाम COP21 के आयोजन-स्थल शहर पर है, सचिवालय के स्थान पर नहीं।"},
  {"id":"gk-international-orgs-89","question":"The United Nations Environment Programme (UNEP) has its headquarters in:","options":["Rome","Nairobi","Vienna","Bangkok"],"answer":1,"explanation":"UNEP, set up after the 1972 Stockholm Conference, is based in Nairobi, Kenya, making it one of the few UN bodies headquartered in the global South.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"संयुक्त राष्ट्र पर्यावरण कार्यक्रम (UNEP) का मुख्यालय कहाँ है?","optionsHi":["रोम","नैरोबी","वियना","बैंकॉक"],"explanationHi":"1972 के स्टॉकहोम सम्मेलन के बाद स्थापित UNEP का मुख्यालय केन्या के नैरोबी में है, जिससे यह वैश्विक दक्षिण में मुख्यालय वाले गिने-चुने संयुक्त राष्ट्र निकायों में से एक है।"},
  {"id":"gk-international-orgs-90","question":"The International Atomic Energy Agency (IAEA), which promotes peaceful use of nuclear energy and inspects nuclear facilities, is based in:","options":["Geneva","The Hague","Vienna","Brussels"],"answer":2,"explanation":"The IAEA, founded in 1957, is in Vienna. The Hague hosts the International Court of Justice and the chemical-weapons watchdog OPCW.","difficulty":"moderate","source":"SSC CGL · UPSC Prelims","questionHi":"अंतर्राष्ट्रीय परमाणु ऊर्जा एजेंसी (IAEA), जो परमाणु ऊर्जा के शांतिपूर्ण उपयोग को बढ़ावा देती है और परमाणु प्रतिष्ठानों का निरीक्षण करती है, कहाँ स्थित है?","optionsHi":["जिनेवा","द हेग","वियना","ब्रुसेल्स"],"explanationHi":"IAEA (स्थापना 1957) वियना में है। द हेग में अंतर्राष्ट्रीय न्यायालय और रासायनिक हथियारों पर निगरानी रखने वाला OPCW स्थित है।"},
  {"id":"gk-international-orgs-91","question":"Which UN agency is unique in being tripartite, with governments, employers and workers all represented in its decision-making?","options":["World Health Organization","UNESCO","World Bank","International Labour Organization"],"answer":3,"explanation":"The ILO, founded in 1919 and based in Geneva, gives employers' and workers' delegates a vote alongside governments when adopting labour conventions.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र की कौन-सी एजेंसी त्रिपक्षीय होने के कारण अद्वितीय है, जिसके निर्णय-प्रक्रिया में सरकारों, नियोक्ताओं और श्रमिकों, तीनों का प्रतिनिधित्व होता है?","optionsHi":["विश्व स्वास्थ्य संगठन","UNESCO","विश्व बैंक","अंतर्राष्ट्रीय श्रम संगठन"],"explanationHi":"ILO (स्थापना 1919, मुख्यालय जिनेवा) श्रम अभिसमयों को अपनाते समय सरकारों के साथ नियोक्ताओं और श्रमिकों के प्रतिनिधियों को भी मताधिकार देता है।"},
  {"id":"gk-international-orgs-92","question":"The UN agency mandated to protect refugees and stateless people is the:","options":["UNHCR, headquartered in Geneva","UNICEF, headquartered in New York","UNDP, headquartered in New York","IOM, headquartered in Vienna"],"answer":0,"explanation":"The Office of the UN High Commissioner for Refugees, set up in 1950, works from Geneva. UNICEF serves children and UNDP development; the IOM, a related migration body, is also in Geneva.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"शरणार्थियों और राज्यविहीन व्यक्तियों की रक्षा का दायित्व संयुक्त राष्ट्र की किस एजेंसी के पास है?","optionsHi":["UNHCR, मुख्यालय जिनेवा","UNICEF, मुख्यालय न्यूयॉर्क","UNDP, मुख्यालय न्यूयॉर्क","IOM, मुख्यालय वियना"],"explanationHi":"संयुक्त राष्ट्र शरणार्थी उच्चायुक्त कार्यालय, जिसकी स्थापना 1950 में हुई, जिनेवा से कार्य करता है। UNICEF बच्चों के लिए और UNDP विकास के लिए कार्य करता है; प्रवासन से संबंधित निकाय IOM भी जिनेवा में है।"},
  {"id":"gk-international-orgs-93","question":"The World Meteorological Organization, the UN agency for weather, climate and water, is headquartered in:","options":["Washington, D.C.","Geneva","Tokyo","Rome"],"answer":1,"explanation":"The WMO is in Geneva. Together with UNEP it set up the Intergovernmental Panel on Climate Change (IPCC) in 1988.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"मौसम, जलवायु और जल से संबंधित संयुक्त राष्ट्र एजेंसी, विश्व मौसम विज्ञान संगठन का मुख्यालय कहाँ है?","optionsHi":["वाशिंगटन, D.C.","जिनेवा","टोक्यो","रोम"],"explanationHi":"WMO जिनेवा में है। इसने UNEP के साथ मिलकर 1988 में जलवायु परिवर्तन पर अंतर-सरकारी पैनल (IPCC) की स्थापना की।"},
  {"id":"gk-international-orgs-94","question":"The UN Charter was signed at San Francisco on 26 June 1945. The UN formally came into existence on 24 October 1945 because on that date:","options":["The first General Assembly met","The first Secretary-General took office","The Charter came into force after ratification by the five permanent members and a majority of the other signatories","The UN headquarters building opened"],"answer":2,"explanation":"Ratification by China, France, the USSR, the UK, the US and most other signatories brought the Charter into force on 24 October, now UN Day. The first General Assembly met in London in January 1946.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र चार्टर पर 26 जून 1945 को सैन फ्रांसिस्को में हस्ताक्षर हुए थे। संयुक्त राष्ट्र औपचारिक रूप से 24 अक्टूबर 1945 को अस्तित्व में आया, क्योंकि उस तिथि को:","optionsHi":["महासभा की पहली बैठक हुई","पहले महासचिव ने कार्यभार संभाला","पाँचों स्थायी सदस्यों और अन्य हस्ताक्षरकर्ताओं के बहुमत द्वारा अनुसमर्थन के बाद चार्टर लागू हुआ","संयुक्त राष्ट्र मुख्यालय भवन का उद्घाटन हुआ"],"explanationHi":"चीन, फ्रांस, सोवियत संघ, ब्रिटेन, अमेरिका और अधिकांश अन्य हस्ताक्षरकर्ताओं के अनुसमर्थन से चार्टर 24 अक्टूबर को लागू हुआ, जो अब संयुक्त राष्ट्र दिवस है। महासभा की पहली बैठक जनवरी 1946 में लंदन में हुई थी।"},
  {"id":"gk-international-orgs-95","question":"CITES is an international agreement that regulates:","options":["International trade in endangered species of wild animals and plants","Emissions of greenhouse gases","Trade in hazardous waste","Use of ozone-depleting substances"],"answer":0,"explanation":"The Convention on International Trade in Endangered Species (1973) lists species in appendices that restrict trade. Hazardous waste falls under the Basel Convention and ozone depletion under the Montreal Protocol.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"CITES एक अंतर्राष्ट्रीय समझौता है जो किसे विनियमित करता है?","optionsHi":["संकटग्रस्त वन्य जीवों और वनस्पतियों की प्रजातियों का अंतर्राष्ट्रीय व्यापार","ग्रीनहाउस गैसों का उत्सर्जन","खतरनाक अपशिष्ट का व्यापार","ओज़ोन परत को क्षीण करने वाले पदार्थों का उपयोग"],"explanationHi":"संकटग्रस्त प्रजातियों के अंतर्राष्ट्रीय व्यापार पर कन्वेंशन (1973) प्रजातियों को परिशिष्टों में सूचीबद्ध करता है, जिनसे व्यापार प्रतिबंधित होता है। खतरनाक अपशिष्ट बेसल कन्वेंशन के अंतर्गत और ओज़ोन क्षरण मॉन्ट्रियल प्रोटोकॉल के अंतर्गत आता है।"},
  {"id":"gk-international-orgs-96","question":"Match the organisation with its headquarters. A. OPCW  B. UN Tourism (UNWTO)  C. ITU  D. International Seabed Authority; 1. Kingston, Jamaica  2. Geneva  3. Madrid  4. The Hague","options":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"The Organisation for the Prohibition of Chemical Weapons is at The Hague; UN Tourism in Madrid; the International Telecommunication Union, among the oldest international bodies, in Geneva; the Seabed Authority, set up under UNCLOS, in Kingston.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संगठन का उसके मुख्यालय से मिलान कीजिए। A. OPCW  B. UN Tourism (UNWTO)  C. ITU  D. अंतर्राष्ट्रीय समुद्र-तल प्राधिकरण; 1. किंग्स्टन, जमैका  2. जिनेवा  3. मैड्रिड  4. द हेग","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"explanationHi":"रासायनिक हथियार प्रतिषेध संगठन द हेग में है; UN Tourism मैड्रिड में; अंतर्राष्ट्रीय दूरसंचार संघ, जो सबसे पुराने अंतर्राष्ट्रीय निकायों में से है, जिनेवा में; UNCLOS के अंतर्गत स्थापित समुद्र-तल प्राधिकरण किंग्स्टन में।"},
  {"id":"gk-international-orgs-97","question":"How many of these statements are correct? I. The UN Economic and Social Council (ECOSOC) has 54 members. II. ECOSOC members are elected by the General Assembly for three-year terms. III. The Trusteeship Council suspended its operations in 1994 after the last trust territory, Palau, became independent. IV. ECOSOC can grant consultative status to non-governmental organisations.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. ECOSOC has 54 members elected by the General Assembly for three-year terms and, under Article 71 of the Charter, grants consultative status to NGOs; the Trusteeship Council suspended work in 1994 after Palau’s independence.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. संयुक्त राष्ट्र आर्थिक एवं सामाजिक परिषद (ECOSOC) के 54 सदस्य हैं। II. ECOSOC के सदस्य महासभा द्वारा तीन वर्ष के कार्यकाल के लिए चुने जाते हैं। III. न्यास परिषद ने 1994 में अपना कार्य निलंबित कर दिया, जब अंतिम न्यास क्षेत्र पलाउ स्वतंत्र हुआ। IV. ECOSOC गैर-सरकारी संगठनों को परामर्शदात्री दर्जा दे सकती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। ECOSOC के 54 सदस्य महासभा द्वारा तीन वर्ष के कार्यकाल के लिए चुने जाते हैं और चार्टर के अनुच्छेद 71 के अंतर्गत NGO को परामर्शदात्री दर्जा देती है; पलाउ की स्वतंत्रता के बाद न्यास परिषद ने 1994 में कार्य निलंबित कर दिया।"},
  {"id":"gk-international-orgs-98","question":"Assertion (A): Decisions of the UN Security Council can be binding on all UN member states. Reason (R): Under Article 25 of the UN Charter, members agree to accept and carry out the decisions of the Security Council.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Article 25, together with enforcement powers under Chapter VII, makes Security Council decisions binding, unlike General Assembly resolutions, which are recommendations.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): संयुक्त राष्ट्र सुरक्षा परिषद के निर्णय संयुक्त राष्ट्र के सभी सदस्य देशों पर बाध्यकारी हो सकते हैं। कारण (R): संयुक्त राष्ट्र चार्टर के अनुच्छेद 25 के अंतर्गत सदस्य सुरक्षा परिषद के निर्णयों को स्वीकार करने और उनका पालन करने के लिए सहमत होते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"अनुच्छेद 25, अध्याय VII के अंतर्गत प्रवर्तन शक्तियों के साथ मिलकर, सुरक्षा परिषद के निर्णयों को बाध्यकारी बनाता है, जबकि महासभा के प्रस्ताव केवल सिफारिशें होते हैं।"},
  {"id":"gk-international-orgs-99","question":"Arrange these organisations in the order they were founded: 1. International Labour Organization  2. International Monetary Fund  3. World Trade Organization  4. NATO","options":["1-4-2-3","1-2-4-3","2-1-4-3","1-2-3-4"],"answer":1,"explanation":"The ILO dates from 1919, the IMF from 1945 (agreed at Bretton Woods in 1944), NATO from 1949 and the WTO from 1995.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन संगठनों को उनकी स्थापना के क्रम में व्यवस्थित कीजिए: 1. अंतर्राष्ट्रीय श्रम संगठन  2. अंतर्राष्ट्रीय मुद्रा कोष  3. विश्व व्यापार संगठन  4. NATO","optionsHi":["1-4-2-3","1-2-4-3","2-1-4-3","1-2-3-4"],"explanationHi":"ILO की स्थापना 1919 में, IMF की 1945 में (1944 में ब्रेटन वुड्स में सहमति), NATO की 1949 में और WTO की 1995 में हुई।"},
  {"id":"gk-international-orgs-100","question":"How many of these statements about the Paris Agreement are correct? I. It was adopted at COP21 in 2015. II. It aims to keep global warming well below 2 °C and to pursue efforts to limit it to 1.5 °C. III. Each country sets its own targets through Nationally Determined Contributions (NDCs). IV. The emission targets in NDCs are legally binding, with financial penalties for missing them.","options":["Only three","Only one","Only two","All four"],"answer":0,"explanation":"I, II and III are correct. Countries are bound to prepare, report and update NDCs, but meeting the targets is not legally enforceable and there are no penalties, so IV is wrong.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"पेरिस समझौते के बारे में इनमें से कितने कथन सही हैं? I. इसे 2015 में COP21 में अपनाया गया। II. इसका लक्ष्य वैश्विक तापमान वृद्धि को 2 °C से काफी नीचे रखना और इसे 1.5 °C तक सीमित रखने के प्रयास करना है। III. प्रत्येक देश राष्ट्रीय स्तर पर निर्धारित योगदान (NDC) के माध्यम से अपने लक्ष्य स्वयं तय करता है। IV. NDC में उत्सर्जन लक्ष्य कानूनी रूप से बाध्यकारी हैं और उन्हें पूरा न करने पर आर्थिक दंड है।","optionsHi":["केवल तीन","केवल एक","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। देश NDC तैयार करने, रिपोर्ट करने और अद्यतन करने के लिए बाध्य हैं, परंतु लक्ष्यों की पूर्ति कानूनी रूप से लागू करने योग्य नहीं है और कोई दंड नहीं है, इसलिए IV गलत है।"},
  {"id":"gk-international-orgs-101","question":"The flag of the United Nations shows a map of the world surrounded by:","options":["Two olive branches","A ring of twelve stars","Five interlocking rings","A laurel crown and a dove"],"answer":0,"explanation":"The UN emblem is a world map centred on the North Pole, framed by olive branches as a symbol of peace. Twelve stars are on the EU flag and five rings on the Olympic flag.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"संयुक्त राष्ट्र के ध्वज में विश्व का मानचित्र किससे घिरा हुआ दिखाया गया है?","optionsHi":["दो जैतून की शाखाएँ","बारह तारों का घेरा","पाँच आपस में गुँथे हुए छल्ले","लॉरेल का मुकुट और एक कबूतर"],"explanationHi":"संयुक्त राष्ट्र का प्रतीक उत्तरी ध्रुव को केंद्र में रखकर बना विश्व मानचित्र है, जो शांति के प्रतीक जैतून की शाखाओं से घिरा है। बारह तारे यूरोपीय संघ के ध्वज पर और पाँच छल्ले ओलंपिक ध्वज पर होते हैं।"},
  {"id":"gk-international-orgs-102","question":"How many articles does the Charter of the United Nations contain?","options":["100","111","70","125"],"answer":1,"explanation":"The UN Charter has 111 articles in 19 chapters, and the Statute of the International Court of Justice is annexed to it.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र चार्टर में कितने अनुच्छेद हैं?","optionsHi":["100","111","70","125"],"explanationHi":"संयुक्त राष्ट्र चार्टर में 19 अध्यायों में 111 अनुच्छेद हैं, और अंतर्राष्ट्रीय न्यायालय की संविधि इससे संलग्न है।"},
  {"id":"gk-international-orgs-103","question":"FIFA, the world governing body of football, has its headquarters in:","options":["Paris","Lausanne","Zurich","Geneva"],"answer":2,"explanation":"FIFA is based in Zurich. Lausanne hosts the International Olympic Committee, and FIFA was founded in Paris in 1904.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"फुटबॉल की विश्व संचालन संस्था FIFA का मुख्यालय कहाँ है?","optionsHi":["पेरिस","लुज़ान","ज्यूरिख","जिनेवा"],"explanationHi":"FIFA का मुख्यालय ज्यूरिख में है। लुज़ान में अंतर्राष्ट्रीय ओलंपिक समिति है, और FIFA की स्थापना 1904 में पेरिस में हुई थी।"},
  {"id":"gk-international-orgs-104","question":"Match the convention with its subject. A. Basel Convention  B. Rotterdam Convention  C. Stockholm Convention  D. Minamata Convention; 1. Mercury  2. Persistent organic pollutants  3. Prior informed consent for trade in hazardous chemicals and pesticides  4. Transboundary movement of hazardous wastes","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"answer":3,"explanation":"Basel (1989) controls cross-border movement of hazardous waste; Rotterdam (1998) sets prior informed consent for trade in hazardous chemicals; Stockholm (2001) targets persistent organic pollutants; Minamata (2013), named after the Japanese mercury disaster, covers mercury.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कन्वेंशन का उसके विषय से मिलान कीजिए। A. बेसल कन्वेंशन  B. रॉटरडैम कन्वेंशन  C. स्टॉकहोम कन्वेंशन  D. मिनामाता कन्वेंशन; 1. पारा  2. स्थायी कार्बनिक प्रदूषक  3. खतरनाक रसायनों और कीटनाशकों के व्यापार के लिए पूर्व सूचित सहमति  4. खतरनाक अपशिष्टों का सीमा-पार संचलन","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1"],"explanationHi":"बेसल (1989) खतरनाक अपशिष्ट के सीमा-पार संचलन को नियंत्रित करता है; रॉटरडैम (1998) खतरनाक रसायनों के व्यापार के लिए पूर्व सूचित सहमति निर्धारित करता है; स्टॉकहोम (2001) स्थायी कार्बनिक प्रदूषकों को लक्षित करता है; मिनामाता (2013), जापान की पारा त्रासदी के नाम पर, पारे से संबंधित है।"},
  {"id":"gk-international-orgs-105","question":"The International Olympic Committee (IOC) is headquartered in:","options":["Lausanne","Geneva","Athens","Zurich"],"answer":0,"explanation":"The IOC has been based in Lausanne, Switzerland, since 1915. Athens hosted the first modern Games, and Zurich is FIFA's home.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"अंतर्राष्ट्रीय ओलंपिक समिति (IOC) का मुख्यालय कहाँ है?","optionsHi":["लुज़ान","जिनेवा","एथेंस","ज्यूरिख"],"explanationHi":"IOC का मुख्यालय 1915 से स्विट्जरलैंड के लुज़ान में है। एथेंस ने पहले आधुनिक खेलों की मेजबानी की थी, और ज्यूरिख FIFA का मुख्यालय है।"},
  {"id":"gk-international-orgs-106","question":"Who was the first Secretary-General of the United Nations?","options":["Dag Hammarskjöld","Trygve Lie","U Thant","Gladwyn Jebb"],"answer":1,"explanation":"Trygve Lie of Norway served from 1946 to 1952. Gladwyn Jebb was only acting Secretary-General in 1945–46, and Hammarskjöld succeeded Lie.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र के पहले महासचिव कौन थे?","optionsHi":["डैग हैमरशोल्ड","ट्रिग्वे ली","यू थांट","ग्लैडविन जेब"],"explanationHi":"नॉर्वे के ट्रिग्वे ली ने 1946 से 1952 तक सेवा की। ग्लैडविन जेब 1945-46 में केवल कार्यवाहक महासचिव थे, और हैमरशोल्ड ने ली का स्थान लिया।"},
  {"id":"gk-international-orgs-107","question":"The Commonwealth of Independent States (CIS) was formed in 1991 following the:","options":["End of British rule in Hong Kong","Breakup of Yugoslavia","Dissolution of the Soviet Union","Reunification of Germany"],"answer":2,"explanation":"The CIS was created in December 1991 by former Soviet republics as the USSR dissolved. It has nothing to do with the British Commonwealth of Nations.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"स्वतंत्र राष्ट्रों का राष्ट्रकुल (CIS) 1991 में किस घटना के बाद बना?","optionsHi":["हांगकांग में ब्रिटिश शासन की समाप्ति","यूगोस्लाविया का विघटन","सोवियत संघ का विघटन","जर्मनी का एकीकरण"],"explanationHi":"दिसंबर 1991 में सोवियत संघ के विघटन के समय पूर्व सोवियत गणराज्यों ने CIS बनाया। इसका ब्रिटिश राष्ट्रमंडल से कोई संबंध नहीं है।"},
  {"id":"gk-international-orgs-108","question":"Arrange in chronological order: 1. First summit of the Non-Aligned Movement  2. UN Conference on the Human Environment at Stockholm  3. Asian–African Conference at Bandung  4. Formation of the Group of 77","options":["3-1-2-4","1-3-4-2","3-4-1-2","3-1-4-2"],"answer":3,"explanation":"Bandung was held in 1955, the first NAM summit at Belgrade in 1961, the G77 was formed at the end of the first UNCTAD in 1964, and the Stockholm Conference took place in 1972.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. गुटनिरपेक्ष आंदोलन का पहला शिखर सम्मेलन 2. स्टॉकहोम में संयुक्त राष्ट्र मानव पर्यावरण सम्मेलन 3. बांडुंग में एशियाई-अफ्रीकी सम्मेलन 4. 77 के समूह का गठन","optionsHi":["3-1-2-4","1-3-4-2","3-4-1-2","3-1-4-2"],"explanationHi":"बांडुंग सम्मेलन 1955 में हुआ, पहला NAM शिखर सम्मेलन 1961 में बेलग्रेड में, G77 का गठन पहले UNCTAD के अंत में 1964 में हुआ, और स्टॉकहोम सम्मेलन 1972 में हुआ।"},
  {"id":"gk-international-orgs-109","question":"Who was the first woman to be elected President of the UN General Assembly?","options":["Vijaya Lakshmi Pandit","Eleanor Roosevelt","Indira Gandhi","Hansa Mehta"],"answer":0,"explanation":"India's Vijaya Lakshmi Pandit presided over the eighth session in 1953. Eleanor Roosevelt chaired the Commission on Human Rights, and Hansa Mehta helped draft the Universal Declaration of Human Rights.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र महासभा की अध्यक्ष चुनी जाने वाली पहली महिला कौन थीं?","optionsHi":["विजया लक्ष्मी पंडित","एलेनोर रूज़वेल्ट","इंदिरा गांधी","हंसा मेहता"],"explanationHi":"भारत की विजया लक्ष्मी पंडित ने 1953 में आठवें सत्र की अध्यक्षता की। एलेनोर रूज़वेल्ट ने मानवाधिकार आयोग की अध्यक्षता की, और हंसा मेहता ने मानवाधिकारों की सार्वभौमिक घोषणा का मसौदा तैयार करने में सहायता की।"},
  {"id":"gk-international-orgs-110","question":"The World Economic Forum holds its well-known annual meeting of political and business leaders at:","options":["Geneva","Davos","Vienna","Brussels"],"answer":1,"explanation":"The annual meeting is held at Davos, a Swiss ski resort. The Forum's own headquarters is at Cologny, near Geneva.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"विश्व आर्थिक मंच राजनीतिक और व्यापारिक नेताओं की अपनी प्रसिद्ध वार्षिक बैठक कहाँ आयोजित करता है?","optionsHi":["जिनेवा","दावोस","वियना","ब्रुसेल्स"],"explanationHi":"वार्षिक बैठक स्विट्जरलैंड के स्की रिसॉर्ट दावोस में होती है। मंच का अपना मुख्यालय जिनेवा के पास कोलोनी में है।"},
  {"id":"gk-international-orgs-111","question":"How many of these statements about the Universal Declaration of Human Rights are correct? I. It was adopted by the UN General Assembly on 10 December 1948. II. It was adopted at a session held in Paris. III. Hansa Mehta of India helped change its wording from 'all men' to 'all human beings'. IV. Eleanor Roosevelt chaired the UN Commission on Human Rights that drafted it.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. The UDHR was adopted in Paris on 10 December 1948 (now Human Rights Day), Eleanor Roosevelt chaired the drafting Commission, and India’s Hansa Mehta is credited with changing 'all men are born free and equal' to 'all human beings'.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"मानवाधिकारों की सार्वभौमिक घोषणा के बारे में इनमें से कितने कथन सही हैं? I. इसे 10 दिसंबर 1948 को संयुक्त राष्ट्र महासभा ने अपनाया। II. इसे पेरिस में हुए एक सत्र में अपनाया गया। III. भारत की हंसा मेहता ने इसके शब्दों को ‘सभी पुरुष’ से बदलकर ‘सभी मनुष्य’ कराने में योगदान दिया। IV. एलेनोर रूज़वेल्ट ने संयुक्त राष्ट्र मानवाधिकार आयोग की अध्यक्षता की, जिसने इसका मसौदा तैयार किया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। UDHR को 10 दिसंबर 1948 को पेरिस में अपनाया गया (जो अब मानवाधिकार दिवस है), एलेनोर रूज़वेल्ट ने मसौदा तैयार करने वाले आयोग की अध्यक्षता की, और भारत की हंसा मेहता को ‘सभी पुरुष जन्म से स्वतंत्र और समान हैं’ को ‘सभी मनुष्य’ में बदलने का श्रेय दिया जाता है।"},
  {"id":"gk-international-orgs-112","question":"The Kyoto Protocol, which set binding emission-reduction targets for developed countries, was adopted at:","options":["COP15 in 2009","The Rio Earth Summit in 1992","COP21 in 2015","COP3 in 1997"],"answer":3,"explanation":"The Kyoto Protocol was adopted at COP3 in Kyoto in 1997 and came into force in 2005. The UNFCCC itself was opened for signature at Rio in 1992, and the Paris Agreement came at COP21.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"क्योटो प्रोटोकॉल, जिसने विकसित देशों के लिए बाध्यकारी उत्सर्जन-कटौती लक्ष्य तय किए, कहाँ अपनाया गया था?","optionsHi":["COP15 (2009 में)","रियो पृथ्वी शिखर सम्मेलन (1992 में)","COP21 (2015 में)","COP3 (1997 में)"],"explanationHi":"क्योटो प्रोटोकॉल 1997 में क्योटो में COP3 में अपनाया गया और 2005 में लागू हुआ। UNFCCC स्वयं 1992 में रियो में हस्ताक्षर के लिए खोला गया था, और पेरिस समझौता COP21 में आया।"},
  {"id":"gk-international-orgs-113","question":"When UNICEF was set up in 1946, its name stood for:","options":["United Nations International Children's Emergency Fund","United Nations Initiative for Children's Education Fund","United Nations International Child Education Forum","Universal Network for International Child Care and Education"],"answer":0,"explanation":"UNICEF began as the United Nations International Children's Emergency Fund to help children after the Second World War. In 1953 it became the United Nations Children's Fund but kept the acronym.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"1946 में जब UNICEF की स्थापना हुई थी, तब इसका पूरा नाम क्या था?","optionsHi":["United Nations International Children's Emergency Fund","United Nations Initiative for Children's Education Fund","United Nations International Child Education Forum","Universal Network for International Child Care and Education"],"explanationHi":"UNICEF की शुरुआत द्वितीय विश्व युद्ध के बाद बच्चों की सहायता के लिए संयुक्त राष्ट्र अंतर्राष्ट्रीय बाल आपातकालीन कोष (United Nations International Children's Emergency Fund) के रूप में हुई। 1953 में यह संयुक्त राष्ट्र बाल कोष (United Nations Children's Fund) बन गया, पर संक्षिप्त नाम वही रखा गया।"},
  {"id":"gk-international-orgs-114","question":"Under the UN Convention on the Law of the Sea (UNCLOS), a coastal state's territorial sea may extend up to:","options":["24 nautical miles","12 nautical miles","200 nautical miles","350 nautical miles"],"answer":1,"explanation":"The territorial sea extends 12 nautical miles from the baseline. The contiguous zone reaches 24 nautical miles and the exclusive economic zone 200 nautical miles.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"संयुक्त राष्ट्र समुद्री कानून अभिसमय (UNCLOS) के अंतर्गत किसी तटवर्ती राज्य का प्रादेशिक समुद्र अधिकतम कितनी दूरी तक हो सकता है?","optionsHi":["24 समुद्री मील","12 समुद्री मील","200 समुद्री मील","350 समुद्री मील"],"explanationHi":"प्रादेशिक समुद्र आधार रेखा से 12 समुद्री मील तक विस्तृत होता है। संलग्न क्षेत्र 24 समुद्री मील तक और विशेष आर्थिक क्षेत्र 200 समुद्री मील तक जाता है।"},
  {"id":"gk-international-orgs-115","question":"Assertion (A): The Kigali Amendment (2016) to the Montreal Protocol provides for phasing down hydrofluorocarbons (HFCs). Reason (R): HFCs are major ozone-depleting substances.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true. HFCs replaced ozone-depleting CFCs and HCFCs and do not harm the ozone layer; they were targeted because they are very powerful greenhouse gases, so R is false.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अभिकथन (A): मॉन्ट्रियल प्रोटोकॉल में किगाली संशोधन (2016) हाइड्रोफ्लोरोकार्बन (HFC) को चरणबद्ध ढंग से घटाने का प्रावधान करता है। कारण (R): HFC ओज़ोन परत को क्षीण करने वाले प्रमुख पदार्थ हैं।","optionsHi":["A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"A सत्य है। HFC ने ओज़ोन परत को क्षीण करने वाले CFC और HCFC का स्थान लिया और ये ओज़ोन परत को हानि नहीं पहुँचाते; इन्हें इसलिए लक्षित किया गया क्योंकि ये अत्यंत शक्तिशाली ग्रीनहाउस गैसें हैं, अतः R असत्य है।"},
  {"id":"gk-international-orgs-116","question":"Médecins Sans Frontières (Doctors Without Borders), winner of the 1999 Nobel Peace Prize, was founded in 1971 in:","options":["The Netherlands","Switzerland","Belgium","France"],"answer":3,"explanation":"MSF was founded in Paris in 1971 by doctors and journalists. Switzerland is home to the separate International Committee of the Red Cross.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"मेडेसिन्स सैन्स फ्रंटियर्स (सीमा-रहित चिकित्सक), जिसे 1999 का नोबेल शांति पुरस्कार मिला, की स्थापना 1971 में कहाँ हुई थी?","optionsHi":["नीदरलैंड","स्विट्जरलैंड","बेल्जियम","फ्रांस"],"explanationHi":"MSF की स्थापना 1971 में पेरिस में चिकित्सकों और पत्रकारों ने की थी। स्विट्जरलैंड में अलग संस्था, अंतर्राष्ट्रीय रेड क्रॉस समिति, स्थित है।"},
  {"id":"gk-international-orgs-117","question":"Where is the official seat of the European Parliament, where most of its plenary sessions are held?","options":["Strasbourg","Brussels","Luxembourg","The Hague"],"answer":0,"explanation":"Under the EU treaties the Parliament's official seat is Strasbourg. Its committees meet in Brussels and its secretariat is in Luxembourg.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"यूरोपीय संसद का आधिकारिक मुख्यालय कहाँ है, जहाँ इसके अधिकांश पूर्ण सत्र होते हैं?","optionsHi":["स्ट्रासबर्ग","ब्रुसेल्स","लक्ज़मबर्ग","द हेग"],"explanationHi":"यूरोपीय संघ की संधियों के अंतर्गत संसद का आधिकारिक मुख्यालय स्ट्रासबर्ग है। इसकी समितियों की बैठकें ब्रुसेल्स में होती हैं और इसका सचिवालय लक्ज़मबर्ग में है।"},
  {"id":"gk-international-orgs-118","question":"How many of these statements about NATO are correct? I. It was founded in 1949. II. Its founding treaty was signed in Brussels. III. France left NATO's integrated military command in 1966 and returned in 2009. IV. Sweden became a member before Finland.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. The North Atlantic Treaty was signed in Washington, D.C. (Brussels is the present headquarters), and Finland joined in April 2023, before Sweden in March 2024, so II and IV are wrong.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"NATO के बारे में इनमें से कितने कथन सही हैं? I. इसकी स्थापना 1949 में हुई। II. इसकी संस्थापक संधि पर ब्रुसेल्स में हस्ताक्षर हुए। III. फ्रांस 1966 में NATO की एकीकृत सैन्य कमान से बाहर हो गया और 2009 में लौट आया। IV. स्वीडन फिनलैंड से पहले सदस्य बना।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और III सही हैं। उत्तरी अटलांटिक संधि पर वाशिंगटन, D.C. में हस्ताक्षर हुए थे (ब्रुसेल्स वर्तमान मुख्यालय है), और फिनलैंड अप्रैल 2023 में, स्वीडन से पहले, जबकि स्वीडन मार्च 2024 में शामिल हुआ, इसलिए II और IV गलत हैं।"},
  {"id":"gk-international-orgs-119","question":"The Colombo Plan, which began in 1951 to promote economic and social development in Asia and the Pacific, originated at a meeting of:","options":["ASEAN foreign ministers","Non-Aligned Movement leaders","Commonwealth foreign ministers","UN Economic Commission for Asia and the Far East members"],"answer":2,"explanation":"The plan was conceived at the Commonwealth Foreign Ministers' meeting in Colombo in January 1950. ASEAN did not exist until 1967 and NAM until 1961.","difficulty":"hard","source":"UPSC Prelims · State PSC","questionHi":"कोलंबो योजना, जो 1951 में एशिया और प्रशांत क्षेत्र के आर्थिक और सामाजिक विकास को बढ़ावा देने के लिए शुरू हुई, किसकी बैठक से उत्पन्न हुई थी?","optionsHi":["आसियान के विदेश मंत्री","गुटनिरपेक्ष आंदोलन के नेता","राष्ट्रमंडल के विदेश मंत्री","संयुक्त राष्ट्र एशिया और सुदूर पूर्व आर्थिक आयोग के सदस्य"],"explanationHi":"इस योजना की परिकल्पना जनवरी 1950 में कोलंबो में राष्ट्रमंडल विदेश मंत्रियों की बैठक में की गई थी। आसियान 1967 तक और NAM 1961 तक अस्तित्व में नहीं था।"},
  {"id":"gk-international-orgs-120","question":"Greenpeace International, the environmental campaigning organisation, is headquartered in:","options":["Vancouver","Gland","Nairobi","Amsterdam"],"answer":3,"explanation":"Greenpeace International is based in Amsterdam, although Greenpeace began in Vancouver in 1971. Gland, Switzerland, hosts WWF and IUCN.","difficulty":"moderate","source":"SSC CGL · State PSC","questionHi":"पर्यावरण अभियान चलाने वाली संस्था ग्रीनपीस इंटरनेशनल का मुख्यालय कहाँ है?","optionsHi":["वैंकूवर","ग्लैंड","नैरोबी","एम्स्टर्डम"],"explanationHi":"ग्रीनपीस इंटरनेशनल का मुख्यालय एम्स्टर्डम में है, यद्यपि ग्रीनपीस की शुरुआत 1971 में वैंकूवर में हुई थी। स्विट्जरलैंड के ग्लैंड में WWF और IUCN स्थित हैं।"},
  {"id":"gk-international-orgs-121","question":"How many of these statements about the Antarctic Treaty are correct? I. It was signed in Geneva in 1959. II. It allows Antarctica to be used for peaceful purposes only. III. India acceded to it in 1981. IV. It divided Antarctica among the countries that had claimed territory there.","options":["Only three","Only two","Only one","All four"],"answer":2,"explanation":"Only II is correct. The treaty was signed in Washington in 1959; India acceded in 1983 (its first expedition went in 1981); and the treaty froze existing territorial claims rather than dividing the continent.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"अंटार्कटिक संधि के बारे में इनमें से कितने कथन सही हैं? I. इस पर 1959 में जिनेवा में हस्ताक्षर हुए। II. यह अंटार्कटिका को केवल शांतिपूर्ण उद्देश्यों के लिए उपयोग करने की अनुमति देती है। III. भारत ने 1981 में इसे स्वीकार किया। IV. इसने अंटार्कटिका को उन देशों के बीच बाँट दिया जिन्होंने वहाँ भूमि पर दावा किया था।","optionsHi":["केवल तीन","केवल दो","केवल एक","सभी चार"],"explanationHi":"केवल II सही है। संधि पर 1959 में वाशिंगटन में हस्ताक्षर हुए; भारत ने 1983 में इसे स्वीकार किया (उसका पहला अभियान 1981 में गया था); और संधि ने महाद्वीप को बाँटने के बजाय मौजूदा क्षेत्रीय दावों को स्थगित कर दिया।"},
  {"id":"gk-international-orgs-122","question":"The World Heritage Convention, under which sites are placed on the World Heritage List, was adopted by UNESCO in:","options":["1945","1972","1965","1992"],"answer":1,"explanation":"UNESCO's General Conference adopted the Convention concerning the Protection of the World Cultural and Natural Heritage in Paris in November 1972. UNESCO itself was founded in 1945.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"विश्व धरोहर अभिसमय, जिसके अंतर्गत स्थलों को विश्व धरोहर सूची में रखा जाता है, UNESCO द्वारा कब अपनाया गया?","optionsHi":["1945","1972","1965","1992"],"explanationHi":"UNESCO के आम सम्मेलन ने नवंबर 1972 में पेरिस में विश्व सांस्कृतिक और प्राकृतिक धरोहर के संरक्षण से संबंधित अभिसमय को अपनाया। UNESCO की स्थापना स्वयं 1945 में हुई थी।"},
  {"id":"gk-international-orgs-123","question":"Match the agreement with its subject. A. Ramsar Convention  B. Bonn Convention  C. Vienna Convention (1985)  D. Cartagena Protocol; 1. Biosafety of living modified organisms  2. Protection of the ozone layer  3. Migratory species of wild animals  4. Wetlands of international importance","options":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"answer":2,"explanation":"Ramsar (1971) protects wetlands; the Bonn Convention (CMS, 1979) covers migratory species; the 1985 Vienna Convention is the framework for ozone protection that the Montreal Protocol implements; the Cartagena Protocol under the CBD deals with biosafety.","difficulty":"very-hard","source":"UPSC Prelims · State PSC","questionHi":"समझौते का उसके विषय से मिलान कीजिए। A. रामसर कन्वेंशन  B. बॉन कन्वेंशन  C. वियना कन्वेंशन (1985)  D. कार्टाजेना प्रोटोकॉल; 1. संशोधित जीवों की जैव सुरक्षा  2. ओज़ोन परत की सुरक्षा  3. वन्य जीवों की प्रवासी प्रजातियाँ  4. अंतर्राष्ट्रीय महत्त्व की आर्द्रभूमियाँ","optionsHi":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-3, D-1"],"explanationHi":"रामसर (1971) आर्द्रभूमियों की रक्षा करता है; बॉन कन्वेंशन (CMS, 1979) प्रवासी प्रजातियों से संबंधित है; 1985 का वियना कन्वेंशन ओज़ोन संरक्षण का ढाँचा है जिसे मॉन्ट्रियल प्रोटोकॉल लागू करता है; CBD के अंतर्गत कार्टाजेना प्रोटोकॉल जैव सुरक्षा से संबंधित है।"},
  {"id":"gk-international-orgs-124","question":"The Organisation of Islamic Cooperation (OIC), founded in 1969, has its general secretariat in:","options":["Rabat","Riyadh","Cairo","Jeddah"],"answer":3,"explanation":"The OIC secretariat is in Jeddah, Saudi Arabia. The organisation was founded at a summit in Rabat; Cairo hosts the Arab League.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"इस्लामी सहयोग संगठन (OIC), जिसकी स्थापना 1969 में हुई, का महासचिवालय कहाँ है?","optionsHi":["रबात","रियाद","काहिरा","जेद्दा"],"explanationHi":"OIC का सचिवालय सऊदी अरब के जेद्दा में है। संगठन की स्थापना रबात में एक शिखर सम्मेलन में हुई थी; काहिरा में अरब लीग है।"},
  {"id":"gk-international-orgs-125","question":"How many of these UN bodies are correctly matched with their headquarters? I. World Food Programme — Rome  II. UN Population Fund (UNFPA) — Nairobi  III. UN Women — Geneva  IV. International Organization for Migration — Geneva","options":["Only two","Only one","Only three","All four"],"answer":0,"explanation":"I and IV are correct. Both UNFPA and UN Women are headquartered in New York, so II and III are wrong. Nairobi hosts UNEP and UN-Habitat.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"संयुक्त राष्ट्र के इनमें से कितने निकाय अपने मुख्यालय से सही ढंग से सुमेलित हैं? I. विश्व खाद्य कार्यक्रम — रोम  II. संयुक्त राष्ट्र जनसंख्या कोष (UNFPA) — नैरोबी  III. UN Women — जिनेवा  IV. अंतर्राष्ट्रीय प्रवासन संगठन — जिनेवा","optionsHi":["केवल दो","केवल एक","केवल तीन","सभी चार"],"explanationHi":"I और IV सही हैं। UNFPA और UN Women दोनों का मुख्यालय न्यूयॉर्क में है, इसलिए II और III गलत हैं। नैरोबी में UNEP और UN-Habitat स्थित हैं।"},
  {"id":"gk-international-orgs-126","question":"Under which Chapter of the UN Charter can the Security Council decide on sanctions and military action against a threat to the peace, breach of the peace or act of aggression?","options":["Chapter VI","Chapter VII","Chapter VIII","Chapter XII"],"answer":1,"explanation":"Chapter VII (Articles 39–51) gives the Council enforcement powers. Chapter VI covers pacific settlement of disputes, Chapter VIII regional arrangements and Chapter XII the trusteeship system.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"संयुक्त राष्ट्र चार्टर के किस अध्याय के अंतर्गत सुरक्षा परिषद शांति के लिए खतरे, शांति भंग या आक्रामकता के कृत्य की स्थिति में प्रतिबंधों और सैन्य कार्रवाई का निर्णय ले सकती है?","optionsHi":["अध्याय VI","अध्याय VII","अध्याय VIII","अध्याय XII"],"explanationHi":"अध्याय VII (अनुच्छेद 39-51) परिषद को प्रवर्तन शक्तियाँ देता है। अध्याय VI विवादों के शांतिपूर्ण समाधान, अध्याय VIII क्षेत्रीय व्यवस्थाओं और अध्याय XII न्यास प्रणाली से संबंधित है।"},
  {"id":"gk-international-orgs-127","question":"Which Article of the UN Charter preserves a member state's 'inherent right' of individual or collective self-defence if an armed attack occurs, until the Security Council has taken the necessary measures?","options":["Article 2(4)","Article 39","Article 51","Article 99"],"answer":2,"explanation":"Article 51 is the self-defence clause. Article 2(4) prohibits the threat or use of force, Article 39 lets the Council determine a threat to peace, and Article 99 lets the Secretary-General bring matters to the Council.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र चार्टर का कौन-सा अनुच्छेद, सशस्त्र हमला होने पर सुरक्षा परिषद द्वारा आवश्यक उपाय किए जाने तक, किसी सदस्य राज्य के व्यक्तिगत या सामूहिक आत्मरक्षा के ‘नैसर्गिक अधिकार’ को सुरक्षित रखता है?","optionsHi":["अनुच्छेद 2(4)","अनुच्छेद 39","अनुच्छेद 51","अनुच्छेद 99"],"explanationHi":"अनुच्छेद 51 आत्मरक्षा संबंधी खंड है। अनुच्छेद 2(4) बल के प्रयोग या उसकी धमकी को प्रतिबंधित करता है, अनुच्छेद 39 परिषद को शांति के लिए खतरे का निर्धारण करने देता है, और अनुच्छेद 99 महासचिव को मामले परिषद के समक्ष लाने देता है।"},
  {"id":"gk-international-orgs-128","question":"Under Article 19 of the UN Charter, a member whose arrears equal or exceed the contributions due from it for the preceding two full years loses its vote in:","options":["The Security Council","The Economic and Social Council","Every principal organ of the UN","The General Assembly"],"answer":3,"explanation":"Article 19 suspends the defaulting member's vote in the General Assembly only, unless the Assembly decides the failure was beyond the member's control.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"संयुक्त राष्ट्र चार्टर के अनुच्छेद 19 के अंतर्गत, जिस सदस्य का बकाया पिछले पूरे दो वर्षों के लिए उससे देय अंशदान के बराबर या उससे अधिक हो जाता है, वह किसमें मताधिकार खो देता है?","optionsHi":["सुरक्षा परिषद","आर्थिक एवं सामाजिक परिषद","संयुक्त राष्ट्र के प्रत्येक प्रमुख अंग","महासभा"],"explanationHi":"अनुच्छेद 19 केवल महासभा में चूककर्ता सदस्य का मताधिकार निलंबित करता है, जब तक कि महासभा यह न माने कि चूक सदस्य के नियंत्रण से बाहर थी।"},
  {"id":"gk-international-orgs-129","question":"How many of these statements about amending the UN Charter under Article 108 are correct? I. An amendment must be adopted by a two-thirds vote of the Security Council. II. It must then be ratified by three-fourths of the UN members. III. The ratifying members must include all five permanent members of the Security Council. IV. The Charter has never been amended since 1945.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. Under Article 108 an amendment needs a two-thirds vote of the General Assembly (not the Security Council) and ratification by two-thirds of members, including all five permanent members. The Charter has been amended, e.g. in 1965 to enlarge the Security Council.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अनुच्छेद 108 के अंतर्गत संयुक्त राष्ट्र चार्टर में संशोधन के बारे में इनमें से कितने कथन सही हैं? I. संशोधन को सुरक्षा परिषद के दो-तिहाई मत से अपनाया जाना चाहिए। II. फिर उसका संयुक्त राष्ट्र के तीन-चौथाई सदस्यों द्वारा अनुसमर्थन होना चाहिए। III. अनुसमर्थन करने वाले सदस्यों में सुरक्षा परिषद के सभी पाँच स्थायी सदस्य शामिल होने चाहिए। IV. 1945 के बाद से चार्टर में कभी संशोधन नहीं हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल III सही है। अनुच्छेद 108 के अंतर्गत संशोधन के लिए महासभा (सुरक्षा परिषद नहीं) के दो-तिहाई मत और सभी पाँच स्थायी सदस्यों सहित दो-तिहाई सदस्यों के अनुसमर्थन की आवश्यकता होती है। चार्टर में संशोधन हुआ है, जैसे 1965 में सुरक्षा परिषद का विस्तार करने के लिए।"},
  {"id":"gk-international-orgs-130","question":"The amendment to the UN Charter that came into force in 1965 changed the number of non-permanent members of the Security Council from:","options":["4 to 8","6 to 10","5 to 10","6 to 9"],"answer":1,"explanation":"The Council grew from 11 members (5 permanent + 6 elected) to 15 (5 + 10). The same 1965 amendments raised ECOSOC from 18 to 27 members.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1965 में लागू हुए संयुक्त राष्ट्र चार्टर के संशोधन ने सुरक्षा परिषद के अस्थायी सदस्यों की संख्या कितनी से कितनी कर दी?","optionsHi":["4 से 8","6 से 10","5 से 10","6 से 9"],"explanationHi":"परिषद 11 सदस्यों (5 स्थायी + 6 निर्वाचित) से बढ़कर 15 सदस्यों (5 + 10) की हो गई। इन्हीं 1965 के संशोधनों ने ECOSOC को 18 से बढ़ाकर 27 सदस्यों का कर दिया।"},
  {"id":"gk-international-orgs-131","question":"The 'Uniting for Peace' resolution (377 A), adopted in 1950 during the Korean War, provides that:","options":["The Security Council may override a single permanent member's veto by a two-thirds vote when peace is threatened","The Secretary-General may send peacekeepers without Council approval while an armed attack continues","Regional organisations may use force against an aggressor once the General Assembly condemns it","The General Assembly may take up a threat to peace if a lack of permanent-member unanimity blocks the Council"],"answer":3,"explanation":"Resolution 377 A lets the General Assembly consider the matter and recommend collective measures when a veto blocks the Council. It does not override the veto in the Council itself.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"कोरियाई युद्ध के दौरान 1950 में अपनाया गया ‘शांति के लिए एकता’ प्रस्ताव (377 A) क्या प्रावधान करता है?","optionsHi":["शांति को खतरा होने पर सुरक्षा परिषद दो-तिहाई मत से किसी एक स्थायी सदस्य के वीटो को निरस्त कर सकती है","सशस्त्र हमला जारी रहने के दौरान महासचिव परिषद की स्वीकृति के बिना शांति सैनिक भेज सकता है","महासभा द्वारा निंदा किए जाने के बाद क्षेत्रीय संगठन आक्रमणकारी के विरुद्ध बल प्रयोग कर सकते हैं","यदि स्थायी सदस्यों की एकमतता के अभाव में परिषद बाधित हो, तो महासभा शांति के लिए खतरे के मामले पर विचार कर सकती है"],"explanationHi":"प्रस्ताव 377 A वीटो से परिषद के बाधित होने पर महासभा को मामले पर विचार करने और सामूहिक उपायों की सिफारिश करने देता है। यह परिषद में वीटो को निरस्त नहीं करता।"},
  {"id":"gk-international-orgs-132","question":"The name 'United Nations', first used officially in the Declaration by United Nations of 1 January 1942, was coined by:","options":["Franklin D. Roosevelt","Winston Churchill","Field Marshal Jan Smuts","Cordell Hull"],"answer":0,"explanation":"US President Franklin D. Roosevelt devised the name; it appeared in the 1942 Declaration in which the Allied nations pledged to fight the Axis together.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"‘संयुक्त राष्ट्र’ नाम, जिसका आधिकारिक प्रयोग पहली बार 1 जनवरी 1942 की संयुक्त राष्ट्र घोषणा में हुआ, किसने गढ़ा था?","optionsHi":["फ्रैंकलिन डी. रूज़वेल्ट","विंस्टन चर्चिल","फील्ड मार्शल जान स्मट्स","कॉर्डेल हल"],"explanationHi":"अमेरिकी राष्ट्रपति फ्रैंकलिन डी. रूज़वेल्ट ने यह नाम सुझाया था; यह 1942 की उस घोषणा में आया जिसमें मित्र राष्ट्रों ने धुरी शक्तियों से मिलकर लड़ने का संकल्प लिया।"},
  {"id":"gk-international-orgs-133","question":"The first detailed proposals for the structure of the future United Nations, including a Security Council, were drawn up in 1944 at:","options":["Yalta","San Francisco","Dumbarton Oaks","Tehran"],"answer":2,"explanation":"The Dumbarton Oaks Conference (Washington, 1944) drafted the outline. Yalta (February 1945) settled the Council voting formula and San Francisco (1945) adopted the Charter.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"भावी संयुक्त राष्ट्र की संरचना, जिसमें सुरक्षा परिषद भी शामिल थी, के पहले विस्तृत प्रस्ताव 1944 में कहाँ तैयार किए गए थे?","optionsHi":["याल्टा","सैन फ्रांसिस्को","डम्बार्टन ओक्स","तेहरान"],"explanationHi":"डम्बार्टन ओक्स सम्मेलन (वाशिंगटन, 1944) में रूपरेखा तैयार की गई। याल्टा (फरवरी 1945) में परिषद की मतदान प्रणाली तय हुई और सैन फ्रांसिस्को (1945) में चार्टर अपनाया गया।"},
  {"id":"gk-international-orgs-134","question":"Arrange in chronological order: 1. Yalta Conference  2. Atlantic Charter  3. Dumbarton Oaks Conference  4. Declaration by United Nations","options":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"answer":0,"explanation":"Atlantic Charter (August 1941), Declaration by United Nations (January 1942), Dumbarton Oaks (August–October 1944), Yalta (February 1945).","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. याल्टा सम्मेलन  2. अटलांटिक चार्टर  3. डम्बार्टन ओक्स सम्मेलन  4. संयुक्त राष्ट्र घोषणा","optionsHi":["2-4-3-1","4-2-3-1","2-3-4-1","2-4-1-3"],"explanationHi":"अटलांटिक चार्टर (अगस्त 1941), संयुक्त राष्ट्र घोषणा (जनवरी 1942), डम्बार्टन ओक्स (अगस्त-अक्टूबर 1944), याल्टा (फरवरी 1945)।"},
  {"id":"gk-international-orgs-135","question":"Match the Main Committee of the UN General Assembly with its subject. A. First Committee  B. Third Committee  C. Fourth Committee  D. Sixth Committee; 1. Social, humanitarian and cultural  2. Legal  3. Disarmament and international security  4. Special political and decolonisation","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4"],"answer":1,"explanation":"First: disarmament and security; Second: economic and financial; Third: social, humanitarian and cultural; Fourth: special political and decolonisation; Fifth: administrative and budgetary; Sixth: legal.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र महासभा की मुख्य समिति का उसके विषय से मिलान कीजिए। A. प्रथम समिति  B. तृतीय समिति  C. चतुर्थ समिति  D. छठी समिति; 1. सामाजिक, मानवीय और सांस्कृतिक  2. विधिक  3. निरस्त्रीकरण और अंतर्राष्ट्रीय सुरक्षा  4. विशेष राजनीतिक और उपनिवेशवाद-उन्मूलन","optionsHi":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4"],"explanationHi":"प्रथम: निरस्त्रीकरण और सुरक्षा; द्वितीय: आर्थिक और वित्तीय; तृतीय: सामाजिक, मानवीय और सांस्कृतिक; चतुर्थ: विशेष राजनीतिक और उपनिवेशवाद-उन्मूलन; पंचम: प्रशासनिक और बजटीय; छठी: विधिक।"},
  {"id":"gk-international-orgs-136","question":"Match the UN regional commission with its headquarters. A. ESCAP  B. ECA  C. ECLAC  D. ESCWA; 1. Santiago  2. Beirut  3. Bangkok  4. Addis Ababa","options":["A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"ESCAP (Asia-Pacific) sits in Bangkok, ECA (Africa) in Addis Ababa, ECLAC (Latin America and the Caribbean) in Santiago and ESCWA (Western Asia) in Beirut; ECE is in Geneva.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"संयुक्त राष्ट्र के क्षेत्रीय आयोग का उसके मुख्यालय से मिलान कीजिए। A. ESCAP  B. ECA  C. ECLAC  D. ESCWA; 1. सैंटियागो  2. बेरूत  3. बैंकॉक  4. अदीस अबाबा","optionsHi":["A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"explanationHi":"ESCAP (एशिया-प्रशांत) बैंकॉक में, ECA (अफ्रीका) अदीस अबाबा में, ECLAC (लैटिन अमेरिका और कैरिबियन) सैंटियागो में और ESCWA (पश्चिम एशिया) बेरूत में स्थित है; ECE जिनेवा में है।"},
  {"id":"gk-international-orgs-137","question":"The presidency of the UN Security Council rotates:","options":["Every month, following the order in which members were elected to it","Every three months, among the five permanent members only","Every month, in the English alphabetical order of member states' names","Every year, through an election held among all fifteen Council members"],"answer":2,"explanation":"Under the Council's rules of procedure the presidency passes each month to the next member in English alphabetical order, so permanent and elected members both hold it.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"संयुक्त राष्ट्र सुरक्षा परिषद की अध्यक्षता किस प्रकार बदलती रहती है?","optionsHi":["प्रत्येक माह, सदस्यों के परिषद में निर्वाचित होने के क्रम के अनुसार","प्रत्येक तीन माह, केवल पाँच स्थायी सदस्यों के बीच","प्रत्येक माह, सदस्य देशों के नामों के अंग्रेजी वर्णानुक्रम में","प्रत्येक वर्ष, परिषद के सभी पंद्रह सदस्यों के बीच चुनाव द्वारा"],"explanationHi":"परिषद की प्रक्रिया-नियमावली के अनुसार अध्यक्षता प्रत्येक माह अंग्रेजी वर्णानुक्रम में अगले सदस्य को मिलती है, इसलिए स्थायी और निर्वाचित, दोनों प्रकार के सदस्य इसे धारण करते हैं।"},
  {"id":"gk-international-orgs-138","question":"Chinese, English, French, Russian and Spanish were the UN's official languages from the start. Which language was added as an official language of the General Assembly in 1973?","options":["German","Hindi","Japanese","Arabic"],"answer":3,"explanation":"Arabic was added in 1973, giving the UN six official languages. Spanish, sometimes assumed to be a later addition, was official from 1946.","difficulty":"hard","source":"SSC CGL · State PCS","questionHi":"चीनी, अंग्रेजी, फ्रेंच, रूसी और स्पेनिश आरंभ से ही संयुक्त राष्ट्र की आधिकारिक भाषाएँ थीं। 1973 में महासभा की आधिकारिक भाषा के रूप में कौन-सी भाषा जोड़ी गई?","optionsHi":["जर्मन","हिंदी","जापानी","अरबी"],"explanationHi":"अरबी को 1973 में जोड़ा गया, जिससे संयुक्त राष्ट्र की छह आधिकारिक भाषाएँ हो गईं। स्पेनिश, जिसे कभी-कभी बाद में जोड़ा गया मान लिया जाता है, 1946 से ही आधिकारिक थी।"},
  {"id":"gk-international-orgs-139","question":"General Assembly Resolution 2758, adopted in 1971, provided that:","options":["Both Chinese governments would be seated as separate members, with the permanent veto staying with Taipei","The Republic of China would keep its Assembly seat but give up its Security Council seat","China's permanent seat would be suspended until the two governments agreed on representation","The People's Republic of China would take China's seat, including its permanent seat on the Council"],"answer":3,"explanation":"Resolution 2758 recognised the PRC's representatives as the only lawful representatives of China, so Beijing replaced Taipei in all UN organs, including the permanent Security Council seat.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"1971 में अपनाया गया महासभा का प्रस्ताव 2758 क्या प्रावधान करता था?","optionsHi":["दोनों चीनी सरकारों को अलग-अलग सदस्य के रूप में स्थान दिया जाएगा, और स्थायी वीटो ताइपे के पास रहेगा","चीन गणराज्य की महासभा में सीट बनी रहेगी, परंतु वह सुरक्षा परिषद की सीट छोड़ देगा","चीन की स्थायी सीट तब तक निलंबित रहेगी जब तक दोनों सरकारें प्रतिनिधित्व पर सहमत न हो जाएँ","जनवादी गणराज्य चीन, परिषद की स्थायी सीट सहित, चीन की सीट ग्रहण करेगा"],"explanationHi":"प्रस्ताव 2758 ने PRC के प्रतिनिधियों को चीन के एकमात्र वैध प्रतिनिधि के रूप में मान्यता दी, इसलिए बीजिंग ने सुरक्षा परिषद की स्थायी सीट सहित सभी संयुक्त राष्ट्र अंगों में ताइपे का स्थान लिया।"},
  {"id":"gk-international-orgs-140","question":"The UN Trusteeship Council suspended its operations in 1994 after the last trust territory gained independence. That territory was:","options":["Palau","Namibia","Nauru","Papua New Guinea"],"answer":0,"explanation":"Palau, part of the Trust Territory of the Pacific Islands, became independent in 1994. Namibia was a League mandate held by South Africa, not a UN trust territory.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"संयुक्त राष्ट्र न्यास परिषद ने 1994 में अंतिम न्यास क्षेत्र के स्वतंत्र होने के बाद अपना कार्य निलंबित कर दिया। वह क्षेत्र कौन-सा था?","optionsHi":["पलाउ","नामीबिया","नाउरू","पापुआ न्यू गिनी"],"explanationHi":"पलाउ, जो प्रशांत द्वीप समूह के न्यास क्षेत्र का हिस्सा था, 1994 में स्वतंत्र हुआ। नामीबिया राष्ट्र संघ का एक जनादेश-क्षेत्र था जो दक्षिण अफ्रीका के पास था, संयुक्त राष्ट्र का न्यास क्षेत्र नहीं।"},
  {"id":"gk-international-orgs-141","question":"How many of these statements are correct? I. UNTSO, set up in 1948 to observe the truce in Palestine, was the first UN peacekeeping operation. II. UNEF I, sent during the Suez Crisis of 1956, was the first armed UN peacekeeping force. III. UN Peacekeeping Forces received the Nobel Peace Prize in 1988. IV. UNMOGIP, which observes the ceasefire in Jammu and Kashmir, was set up in 1949.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. UNTSO (1948) was an unarmed observer mission; UNEF I (1956) was the first armed force; the 1988 Nobel went to UN peacekeepers; UNMOGIP's observers arrived in 1949.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कितने कथन सही हैं? I. UNTSO, जिसे 1948 में फिलिस्तीन में युद्धविराम की निगरानी के लिए बनाया गया, संयुक्त राष्ट्र का पहला शांति स्थापना अभियान था। II. 1956 के स्वेज़ संकट के दौरान भेजा गया UNEF I पहला सशस्त्र संयुक्त राष्ट्र शांति सेना बल था। III. संयुक्त राष्ट्र शांति सेनाओं को 1988 में नोबेल शांति पुरस्कार मिला। IV. UNMOGIP, जो जम्मू-कश्मीर में युद्धविराम की निगरानी करता है, 1949 में स्थापित हुआ।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। UNTSO (1948) निःशस्त्र पर्यवेक्षक मिशन था; UNEF I (1956) पहला सशस्त्र बल था; 1988 का नोबेल पुरस्कार संयुक्त राष्ट्र शांति सैनिकों को मिला; UNMOGIP के पर्यवेक्षक 1949 में पहुँचे।"},
  {"id":"gk-international-orgs-142","question":"India took the Jammu and Kashmir question to the UN Security Council on 1 January 1948 under which Article of the Charter, which lets a member bring a dispute to the Council's attention?","options":["Article 35","Article 39","Article 51","Article 2(7)"],"answer":0,"explanation":"India complained under Article 35, part of Chapter VI on pacific settlement, so the Council could only recommend. Article 39 opens Chapter VII enforcement and Article 2(7) protects domestic jurisdiction.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"भारत ने 1 जनवरी 1948 को जम्मू-कश्मीर का प्रश्न संयुक्त राष्ट्र सुरक्षा परिषद में चार्टर के किस अनुच्छेद के अंतर्गत उठाया, जो किसी सदस्य को विवाद परिषद के ध्यान में लाने देता है?","optionsHi":["अनुच्छेद 35","अनुच्छेद 39","अनुच्छेद 51","अनुच्छेद 2(7)"],"explanationHi":"भारत ने अनुच्छेद 35 के अंतर्गत शिकायत की, जो शांतिपूर्ण समाधान संबंधी अध्याय VI का भाग है, इसलिए परिषद केवल सिफारिश कर सकती थी। अनुच्छेद 39 अध्याय VII के प्रवर्तन की शुरुआत करता है और अनुच्छेद 2(7) घरेलू अधिकारिता की रक्षा करता है।"},
  {"id":"gk-international-orgs-143","question":"Which organisation has won the Nobel Peace Prize three times, in 1917, 1944 and 1963?","options":["International Committee of the Red Cross","Office of the UN High Commissioner for Refugees","International Labour Organization","United Nations Children's Fund"],"answer":0,"explanation":"The ICRC won in 1917, 1944 and 1963 (the last shared with the League of Red Cross Societies). UNHCR won twice (1954, 1981); the ILO (1969) and UNICEF (1965) once each.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"किस संगठन ने 1917, 1944 और 1963 में तीन बार नोबेल शांति पुरस्कार जीता है?","optionsHi":["अंतर्राष्ट्रीय रेड क्रॉस समिति","संयुक्त राष्ट्र शरणार्थी उच्चायुक्त कार्यालय","अंतर्राष्ट्रीय श्रम संगठन","संयुक्त राष्ट्र बाल कोष"],"explanationHi":"ICRC ने 1917, 1944 और 1963 में पुरस्कार जीता (अंतिम बार रेड क्रॉस सोसाइटियों के लीग के साथ साझा)। UNHCR ने दो बार (1954, 1981) जीता; ILO (1969) और UNICEF (1965) ने एक-एक बार।"},
  {"id":"gk-international-orgs-144","question":"Match the organisation with the year it won the Nobel Peace Prize. A. UNICEF  B. International Labour Organization  C. International Atomic Energy Agency  D. World Food Programme; 1. 2020  2. 1965  3. 2005  4. 1969","options":["A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"answer":2,"explanation":"UNICEF won in 1965, the ILO in 1969 (its 50th year), the IAEA in 2005 (with Mohamed ElBaradei) and the WFP in 2020.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"संगठन का उस वर्ष से मिलान कीजिए जब उसने नोबेल शांति पुरस्कार जीता। A. UNICEF  B. अंतर्राष्ट्रीय श्रम संगठन  C. अंतर्राष्ट्रीय परमाणु ऊर्जा एजेंसी  D. विश्व खाद्य कार्यक्रम; 1. 2020  2. 1965  3. 2005  4. 1969","optionsHi":["A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1"],"explanationHi":"UNICEF ने 1965 में, ILO ने 1969 में (अपने 50वें वर्ष में), IAEA ने 2005 में (मोहम्मद अलबरदेई के साथ) और WFP ने 2020 में पुरस्कार जीता।"},
  {"id":"gk-international-orgs-145","question":"The WHO Regional Office for South-East Asia, whose region includes India, is located in:","options":["Manila","Kathmandu","New Delhi","Cairo"],"answer":2,"explanation":"The South-East Asia Regional Office is in New Delhi. Manila hosts the Western Pacific office and Cairo the Eastern Mediterranean office.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"WHO का दक्षिण-पूर्व एशिया क्षेत्रीय कार्यालय, जिसके क्षेत्र में भारत आता है, कहाँ स्थित है?","optionsHi":["मनीला","काठमांडू","नई दिल्ली","काहिरा"],"explanationHi":"दक्षिण-पूर्व एशिया क्षेत्रीय कार्यालय नई दिल्ली में है। मनीला में पश्चिमी प्रशांत कार्यालय और काहिरा में पूर्वी भूमध्यसागरीय कार्यालय है।"},
  {"id":"gk-international-orgs-146","question":"World Health Day is observed on 7 April because on that date in 1948:","options":["The first World Health Assembly opened in Geneva","WHO's constitution came into force","WHO declared the worldwide eradication of smallpox","The Alma-Ata Declaration on primary health care was adopted"],"answer":1,"explanation":"WHO's constitution entered into force on 7 April 1948. The first World Health Assembly met in June 1948, smallpox eradication was declared in 1980 and Alma-Ata was in 1978.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"विश्व स्वास्थ्य दिवस 7 अप्रैल को इसलिए मनाया जाता है क्योंकि 1948 में उस तिथि को:","optionsHi":["जिनेवा में प्रथम विश्व स्वास्थ्य सभा शुरू हुई","WHO का संविधान लागू हुआ","WHO ने चेचक के विश्वव्यापी उन्मूलन की घोषणा की","प्राथमिक स्वास्थ्य देखभाल पर अल्मा-अता घोषणा अपनाई गई"],"explanationHi":"WHO का संविधान 7 अप्रैल 1948 को लागू हुआ था। प्रथम विश्व स्वास्थ्य सभा जून 1948 में हुई, चेचक उन्मूलन की घोषणा 1980 में हुई और अल्मा-अता घोषणा 1978 में हुई थी।"},
  {"id":"gk-international-orgs-147","question":"Match the day with its date. A. World Food Day  B. World Meteorological Day  C. World Post Day  D. World Telecommunication and Information Society Day; 1. 9 October  2. 17 May  3. 16 October  4. 23 March","options":["A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2","A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2"],"answer":0,"explanation":"Each marks a founding: FAO on 16 October 1945, the WMO Convention on 23 March 1950, the UPU on 9 October 1874 and the ITU on 17 May 1865.","difficulty":"very-hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"दिवस का उसकी तिथि से मिलान कीजिए। A. विश्व खाद्य दिवस  B. विश्व मौसम विज्ञान दिवस  C. विश्व डाक दिवस  D. विश्व दूरसंचार और सूचना समाज दिवस; 1. 9 अक्टूबर  2. 17 मई  3. 16 अक्टूबर  4. 23 मार्च","optionsHi":["A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2","A-3, B-2, C-1, D-4","A-4, B-3, C-1, D-2"],"explanationHi":"प्रत्येक एक स्थापना की स्मृति में है: FAO की 16 अक्टूबर 1945, WMO अभिसमय की 23 मार्च 1950, UPU की 9 अक्टूबर 1874 और ITU की 17 मई 1865।"},
  {"id":"gk-international-orgs-148","question":"Judges of the International Court of Justice are elected by:","options":["The General Assembly alone, by a two-thirds majority of members present and voting","Both the General Assembly and the Security Council, with an absolute majority in each","The Security Council on the Secretary-General's recommendation, with the veto applying","The states parties to the ICJ Statute, voting at a special conference held in The Hague"],"answer":1,"explanation":"Under the ICJ Statute both organs vote independently and a candidate needs an absolute majority in each; the permanent members' veto does not apply to this vote.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अंतर्राष्ट्रीय न्यायालय के न्यायाधीशों का चुनाव कौन करता है?","optionsHi":["केवल महासभा, उपस्थित और मतदान करने वाले सदस्यों के दो-तिहाई बहुमत से","महासभा और सुरक्षा परिषद दोनों, प्रत्येक में पूर्ण बहुमत से","महासचिव की सिफारिश पर सुरक्षा परिषद, वीटो लागू होने के साथ","ICJ संविधि के पक्षकार राज्य, द हेग में आयोजित विशेष सम्मेलन में मतदान द्वारा"],"explanationHi":"ICJ संविधि के अंतर्गत दोनों अंग स्वतंत्र रूप से मतदान करते हैं और उम्मीदवार को प्रत्येक में पूर्ण बहुमत चाहिए; इस मतदान में स्थायी सदस्यों का वीटो लागू नहीं होता।"},
  {"id":"gk-international-orgs-149","question":"Assertion (A): The International Court of Justice can decide a contentious case between two states only if both have accepted its jurisdiction. Reason (R): Only states, not individuals or companies, can be parties to contentious cases before the ICJ.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true, but jurisdiction rests on state consent (special agreement, treaty clause or optional-clause declaration); the rule that only states may be parties is a separate limit.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): अंतर्राष्ट्रीय न्यायालय दो राज्यों के बीच किसी विवादास्पद मामले का निर्णय तभी कर सकता है जब दोनों ने उसकी अधिकारिता स्वीकार की हो। कारण (R): ICJ में विवादास्पद मामलों में केवल राज्य ही पक्षकार हो सकते हैं, व्यक्ति या कंपनियाँ नहीं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोनों सत्य हैं, परंतु अधिकारिता राज्य की सहमति पर आधारित होती है (विशेष समझौता, संधि का खंड या वैकल्पिक खंड की घोषणा); केवल राज्यों के पक्षकार होने का नियम एक अलग सीमा है।"},
  {"id":"gk-international-orgs-150","question":"The International Court of Justice replaced which court that had been set up under the League of Nations system?","options":["Permanent Court of International Justice","Permanent Court of Arbitration","International Criminal Court","International Tribunal for the Law of the Sea"],"answer":0,"explanation":"The PCIJ (1922) was succeeded by the ICJ in 1946. The Permanent Court of Arbitration (1899) still exists separately, also at The Hague.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"अंतर्राष्ट्रीय न्यायालय ने राष्ट्र संघ प्रणाली के अंतर्गत स्थापित किस न्यायालय का स्थान लिया?","optionsHi":["स्थायी अंतर्राष्ट्रीय न्याय न्यायालय","स्थायी मध्यस्थता न्यायालय","अंतर्राष्ट्रीय आपराधिक न्यायालय","अंतर्राष्ट्रीय समुद्री कानून न्यायाधिकरण"],"explanationHi":"PCIJ (1922) का उत्तराधिकारी 1946 में ICJ बना। स्थायी मध्यस्थता न्यायालय (1899) अब भी अलग से मौजूद है, और वह भी द हेग में है।"},
  {"id":"gk-international-orgs-151","question":"The constitution of the International Labour Organization, founded in 1919, was originally contained in:","options":["The Declaration of Philadelphia","The Atlantic Charter","Part XIII of the Treaty of Versailles","A resolution of the League of Nations Assembly"],"answer":2,"explanation":"The ILO's constitution formed Part XIII of the Treaty of Versailles (1919). The Declaration of Philadelphia (1944) restated its aims and was later annexed to the constitution.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1919 में स्थापित अंतर्राष्ट्रीय श्रम संगठन का संविधान मूलतः किसमें निहित था?","optionsHi":["फिलाडेल्फिया घोषणा","अटलांटिक चार्टर","वर्साय की संधि का भाग XIII","राष्ट्र संघ की सभा का एक प्रस्ताव"],"explanationHi":"ILO का संविधान वर्साय की संधि (1919) का भाग XIII था। फिलाडेल्फिया घोषणा (1944) ने इसके उद्देश्यों को पुनः व्यक्त किया और बाद में इसे संविधान के साथ संलग्न किया गया।"},
  {"id":"gk-international-orgs-152","question":"Arrange these World Bank Group institutions in the order they were established: 1. International Development Association  2. Multilateral Investment Guarantee Agency  3. International Finance Corporation  4. International Centre for Settlement of Investment Disputes","options":["1-3-4-2","3-1-2-4","3-1-4-2","3-4-1-2"],"answer":2,"explanation":"IFC (1956), IDA (1960), ICSID (1966), MIGA (1988); the IBRD itself dates from 1944.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"विश्व बैंक समूह की इन संस्थाओं को उनकी स्थापना के क्रम में व्यवस्थित कीजिए: 1. अंतर्राष्ट्रीय विकास संघ  2. बहुपक्षीय निवेश गारंटी एजेंसी  3. अंतर्राष्ट्रीय वित्त निगम  4. निवेश विवादों के निपटारे के लिए अंतर्राष्ट्रीय केंद्र","optionsHi":["1-3-4-2","3-1-2-4","3-1-4-2","3-4-1-2"],"explanationHi":"IFC (1956), IDA (1960), ICSID (1966), MIGA (1988); IBRD की स्थापना स्वयं 1944 की है।"},
  {"id":"gk-international-orgs-153","question":"India is a member of four of the five World Bank Group institutions. Which one has India NOT joined?","options":["International Finance Corporation","International Development Association","Multilateral Investment Guarantee Agency","International Centre for Settlement of Investment Disputes"],"answer":3,"explanation":"India has not signed the ICSID Convention, so it is outside the Centre that arbitrates investor–state disputes; it is a member of the IBRD, IDA, IFC and MIGA.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत विश्व बैंक समूह की पाँच में से चार संस्थाओं का सदस्य है। भारत किसमें शामिल नहीं हुआ है?","optionsHi":["अंतर्राष्ट्रीय वित्त निगम","अंतर्राष्ट्रीय विकास संघ","बहुपक्षीय निवेश गारंटी एजेंसी","निवेश विवादों के निपटारे के लिए अंतर्राष्ट्रीय केंद्र"],"explanationHi":"भारत ने ICSID अभिसमय पर हस्ताक्षर नहीं किए हैं, इसलिए वह निवेशक-राज्य विवादों में मध्यस्थता करने वाले इस केंद्र से बाहर है; वह IBRD, IDA, IFC और MIGA का सदस्य है।"},
  {"id":"gk-international-orgs-154","question":"The World Bank (IBRD) made its first loan, of 250 million dollars for post-war reconstruction, in 1947 to:","options":["India","France","The Netherlands","Chile"],"answer":1,"explanation":"France received the first IBRD loan in May 1947. Reconstruction of war-hit Europe was the Bank's first task before it turned mainly to development.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"विश्व बैंक (IBRD) ने युद्धोत्तर पुनर्निर्माण के लिए अपना पहला ऋण, 250 मिलियन डॉलर का, 1947 में किसे दिया?","optionsHi":["भारत","फ्रांस","नीदरलैंड","चिली"],"explanationHi":"पहला IBRD ऋण मई 1947 में फ्रांस को मिला। युद्ध से प्रभावित यूरोप का पुनर्निर्माण बैंक का पहला कार्य था, इसके बाद वह मुख्यतः विकास की ओर मुड़ा।"},
  {"id":"gk-international-orgs-155","question":"The IMF created the Special Drawing Right (SDR) in 1969 in order to:","options":["Replace the US dollar as the anchor of the gold-exchange system","Supplement the official reserves held by member countries","Fund concessional loans to the poorest member countries","Settle trade payments between firms in different countries"],"answer":1,"explanation":"The SDR is an international reserve asset allocated to members to add to their official reserves; it is not a currency used by private firms and did not itself replace the dollar.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"IMF ने 1969 में विशेष आहरण अधिकार (SDR) किस उद्देश्य से बनाया?","optionsHi":["स्वर्ण-विनिमय प्रणाली के आधार के रूप में अमेरिकी डॉलर का स्थान लेना","सदस्य देशों के पास मौजूद आधिकारिक भंडारों का पूरक बनना","सबसे गरीब सदस्य देशों को रियायती ऋण देने के लिए कोष जुटाना","विभिन्न देशों की कंपनियों के बीच व्यापार भुगतान का निपटारा करना"],"explanationHi":"SDR एक अंतर्राष्ट्रीय आरक्षित परिसंपत्ति है जो सदस्यों को उनके आधिकारिक भंडारों में वृद्धि के लिए आवंटित की जाती है; यह निजी कंपनियों द्वारा प्रयुक्त मुद्रा नहीं है और इसने स्वयं डॉलर का स्थान नहीं लिया।"},
  {"id":"gk-international-orgs-156","question":"How many of these statements are correct? I. IMF quotas are expressed in US dollars and largely decide a member's voting power. II. India was a founding member of both the IMF and the IBRD. III. The IMF's Articles of Agreement came into force in July 1944. IV. The IMF lends mainly for long-term infrastructure projects.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. IMF quotas are expressed in Special Drawing Rights (SDRs), not dollars; July 1944 was the Bretton Woods conference, while the Articles came into force in December 1945; and long-term project lending is the World Bank's role.","difficulty":"very-hard","source":"UPSC Prelims · RBI Grade B","questionHi":"इनमें से कितने कथन सही हैं? I. IMF के कोटे अमेरिकी डॉलर में व्यक्त किए जाते हैं और काफी हद तक सदस्य की मताधिकार शक्ति तय करते हैं। II. भारत IMF और IBRD दोनों का संस्थापक सदस्य था। III. IMF के समझौता अनुच्छेद जुलाई 1944 में लागू हुए। IV. IMF मुख्यतः दीर्घकालिक अवसंरचना परियोजनाओं के लिए ऋण देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है। IMF के कोटे डॉलर में नहीं, विशेष आहरण अधिकारों (SDR) में व्यक्त किए जाते हैं; जुलाई 1944 ब्रेटन वुड्स सम्मेलन था, जबकि समझौता अनुच्छेद दिसंबर 1945 में लागू हुए; और दीर्घकालिक परियोजना ऋण विश्व बैंक की भूमिका है।"},
  {"id":"gk-international-orgs-157","question":"The General Agreement on Tariffs and Trade (GATT) was signed in 1947 at:","options":["Havana","Bretton Woods","Marrakesh","Geneva"],"answer":3,"explanation":"GATT was signed at Geneva in October 1947 by 23 countries, India among them. The Havana Charter (1948) for an International Trade Organization was never ratified.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"टैरिफ और व्यापार पर सामान्य समझौते (GATT) पर 1947 में कहाँ हस्ताक्षर हुए थे?","optionsHi":["हवाना","ब्रेटन वुड्स","मराकेश","जिनेवा"],"explanationHi":"GATT पर अक्टूबर 1947 में जिनेवा में 23 देशों ने हस्ताक्षर किए, जिनमें भारत भी था। अंतर्राष्ट्रीय व्यापार संगठन के लिए हवाना चार्टर (1948) का कभी अनुसमर्थन नहीं हुआ।"},
  {"id":"gk-international-orgs-158","question":"Arrange these GATT/WTO trade rounds in chronological order of launch: 1. Uruguay Round  2. Kennedy Round  3. Tokyo Round  4. Doha Round","options":["2-3-1-4","3-2-1-4","2-1-3-4","2-3-4-1"],"answer":0,"explanation":"Kennedy (1964), Tokyo (1973), Uruguay (1986) and Doha (2001).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इन GATT/WTO व्यापार दौरों को उनके आरंभ के कालक्रम में व्यवस्थित कीजिए: 1. उरुग्वे दौर  2. कैनेडी दौर  3. टोक्यो दौर  4. दोहा दौर","optionsHi":["2-3-1-4","3-2-1-4","2-1-3-4","2-3-4-1"],"explanationHi":"कैनेडी (1964), टोक्यो (1973), उरुग्वे (1986) और दोहा (2001)।"},
  {"id":"gk-international-orgs-159","question":"The Uruguay Round of GATT negotiations, which led to the WTO, was launched in 1986 at:","options":["Montevideo","Punta del Este","Marrakesh","Doha"],"answer":1,"explanation":"Ministers launched the round at Punta del Este, Uruguay, in September 1986; it ended with the Marrakesh Agreement of 1994.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"GATT की उरुग्वे दौर की वार्ताएँ, जिनसे WTO बना, 1986 में कहाँ शुरू हुई थीं?","optionsHi":["मोंटेविडियो","पुंता डेल एस्टे","मराकेश","दोहा"],"explanationHi":"मंत्रियों ने सितंबर 1986 में उरुग्वे के पुंता डेल एस्टे में इस दौर की शुरुआत की; यह 1994 के मराकेश समझौते के साथ समाप्त हुआ।"},
  {"id":"gk-international-orgs-160","question":"Match the WTO agriculture category with what it covers. A. Amber box  B. Blue box  C. Green box  D. De minimis; 1. Support causing no or minimal trade distortion  2. Trade-distorting support subject to reduction commitments  3. Direct payments tied to production-limiting programmes  4. Small trade-distorting support allowed up to a set share of output value","options":["A-2, B-1, C-3, D-4","A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Amber box support (e.g. price support) must be cut; blue box payments come with production limits; green box support is permitted without limits; de minimis allows small amber support (10% for most developing countries).","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"WTO की कृषि श्रेणी का उसके विषय से मिलान कीजिए। A. एम्बर बॉक्स  B. ब्लू बॉक्स  C. ग्रीन बॉक्स  D. डी मिनिमिस; 1. व्यापार को कोई या न्यूनतम विकृति न पहुँचाने वाली सहायता  2. कटौती की प्रतिबद्धताओं के अधीन व्यापार-विकृतिकारी सहायता  3. उत्पादन-सीमित करने वाले कार्यक्रमों से जुड़े प्रत्यक्ष भुगतान  4. उत्पादन मूल्य के एक निर्धारित हिस्से तक अनुमत छोटी व्यापार-विकृतिकारी सहायता","optionsHi":["A-2, B-1, C-3, D-4","A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4"],"explanationHi":"एम्बर बॉक्स सहायता (जैसे मूल्य समर्थन) में कटौती करनी होती है; ब्लू बॉक्स भुगतान उत्पादन सीमाओं के साथ आते हैं; ग्रीन बॉक्स सहायता बिना सीमा के अनुमत है; डी मिनिमिस छोटी एम्बर सहायता की अनुमति देता है (अधिकांश विकासशील देशों के लिए 10%)।"},
  {"id":"gk-international-orgs-161","question":"The 'peace clause' agreed at the WTO's Bali Ministerial Conference in 2013, important to India, shields developing countries from legal challenge over:","options":["Compulsory licensing of patented medicines in health emergencies","Export bans on food grains during domestic shortages","Public stockholding of food grains for food security","Fuel subsidies given to fishing fleets within their EEZ"],"answer":2,"explanation":"The interim peace clause protects public stockholding programmes (such as India's grain procurement at minimum support prices) from disputes even if they breach subsidy limits.","difficulty":"hard","source":"UPSC Prelims","questionHi":"2013 में WTO के बाली मंत्रिस्तरीय सम्मेलन में सहमत ‘शांति खंड’, जो भारत के लिए महत्त्वपूर्ण है, विकासशील देशों को किस बात पर कानूनी चुनौती से बचाता है?","optionsHi":["स्वास्थ्य आपातकाल में पेटेंट दवाओं के अनिवार्य लाइसेंस","घरेलू कमी के दौरान खाद्यान्न के निर्यात पर प्रतिबंध","खाद्य सुरक्षा के लिए खाद्यान्न का सार्वजनिक भंडारण","अपने EEZ के भीतर मत्स्य बेड़ों को दी जाने वाली ईंधन सब्सिडी"],"explanationHi":"अंतरिम शांति खंड सार्वजनिक भंडारण कार्यक्रमों (जैसे न्यूनतम समर्थन मूल्य पर भारत की अनाज खरीद) को, सब्सिडी की सीमाओं का उल्लंघन होने पर भी, विवादों से बचाता है।"},
  {"id":"gk-international-orgs-162","question":"Which agreement, adopted at the WTO's Bali Ministerial Conference in 2013, is described as the first multilateral agreement concluded since the WTO was set up?","options":["Trade Facilitation Agreement","Information Technology Agreement","Agreement on Agriculture","Agreement on Fisheries Subsidies"],"answer":0,"explanation":"The Trade Facilitation Agreement eases customs procedures; it came into force in 2017. The ITA (1996) is plurilateral, the Agreement on Agriculture is a Uruguay Round text and the fisheries deal came in 2022.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2013 में WTO के बाली मंत्रिस्तरीय सम्मेलन में अपनाया गया कौन-सा समझौता WTO की स्थापना के बाद संपन्न पहला बहुपक्षीय समझौता माना जाता है?","optionsHi":["व्यापार सुविधा समझौता","सूचना प्रौद्योगिकी समझौता","कृषि समझौता","मत्स्य सब्सिडी समझौता"],"explanationHi":"व्यापार सुविधा समझौता सीमा-शुल्क प्रक्रियाओं को सरल बनाता है; यह 2017 में लागू हुआ। ITA (1996) बहुपक्षीय के बजाय कुछ सदस्यों के बीच है, कृषि समझौता उरुग्वे दौर का पाठ है और मत्स्य समझौता 2022 में आया।"},
  {"id":"gk-international-orgs-163","question":"How many of these statements about the WTO are correct? I. The Doha Development Agenda was launched at the fourth Ministerial Conference in 2001. II. The Doha Declaration on TRIPS and Public Health affirmed members' right to grant compulsory licences. III. The first Ministerial Conference was held in Singapore in 1996. IV. The Nairobi Ministerial Conference of 2015 decided to eliminate agricultural export subsidies.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Singapore (1996) also gave its name to the 'Singapore issues' such as investment and competition policy.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"WTO के बारे में इनमें से कितने कथन सही हैं? I. दोहा विकास एजेंडा 2001 में चौथे मंत्रिस्तरीय सम्मेलन में शुरू किया गया। II. TRIPS और सार्वजनिक स्वास्थ्य पर दोहा घोषणा ने सदस्यों के अनिवार्य लाइसेंस देने के अधिकार की पुष्टि की। III. पहला मंत्रिस्तरीय सम्मेलन 1996 में सिंगापुर में हुआ। IV. 2015 के नैरोबी मंत्रिस्तरीय सम्मेलन ने कृषि निर्यात सब्सिडी को समाप्त करने का निर्णय लिया।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन सही हैं। सिंगापुर (1996) ने निवेश और प्रतिस्पर्धा नीति जैसे ‘सिंगापुर मुद्दों’ को भी अपना नाम दिया।"},
  {"id":"gk-international-orgs-164","question":"Under GATT, the principle that a trade advantage given to one member must be extended immediately and unconditionally to all members is called:","options":["National treatment","Special and differential treatment","Reciprocity","Most-favoured-nation treatment"],"answer":3,"explanation":"MFN (GATT Article I) bars discrimination between trading partners; national treatment (Article III) bars discrimination between imported and domestic goods.","difficulty":"moderate","source":"SSC CGL Tier 2 · RBI Grade B","questionHi":"GATT के अंतर्गत वह सिद्धांत, जिसके अनुसार किसी एक सदस्य को दिया गया व्यापारिक लाभ तुरंत और बिना शर्त सभी सदस्यों को दिया जाना चाहिए, क्या कहलाता है?","optionsHi":["राष्ट्रीय व्यवहार","विशेष और विभेदक व्यवहार","पारस्परिकता","सर्वाधिक तरजीही राष्ट्र व्यवहार"],"explanationHi":"MFN (GATT अनुच्छेद I) व्यापारिक भागीदारों के बीच भेदभाव को रोकता है; राष्ट्रीय व्यवहार (अनुच्छेद III) आयातित और घरेलू वस्तुओं के बीच भेदभाव को रोकता है।"},
  {"id":"gk-international-orgs-165","question":"Match the WTO agreement with its subject. A. TRIPS  B. TRIMs  C. SPS Agreement  D. TBT Agreement; 1. Food safety and animal and plant health measures  2. Technical regulations and product standards  3. Investment measures such as local-content rules  4. Intellectual property rights","options":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-1, C-3, D-2"],"answer":0,"explanation":"TRIPS covers intellectual property, TRIMs trade-related investment measures, SPS sanitary and phytosanitary measures and TBT technical barriers such as standards and labelling.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"WTO समझौते का उसके विषय से मिलान कीजिए। A. TRIPS  B. TRIMs  C. SPS समझौता  D. TBT समझौता; 1. खाद्य सुरक्षा तथा पशु और पादप स्वास्थ्य संबंधी उपाय  2. तकनीकी विनियम और उत्पाद मानक  3. स्थानीय-सामग्री नियमों जैसे निवेश उपाय  4. बौद्धिक संपदा अधिकार","optionsHi":["A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-1, C-3, D-2"],"explanationHi":"TRIPS बौद्धिक संपदा, TRIMs व्यापार-संबंधित निवेश उपायों, SPS स्वच्छता और पादप-स्वच्छता उपायों तथा TBT मानकों और लेबलिंग जैसी तकनीकी बाधाओं से संबंधित है।"},
  {"id":"gk-international-orgs-166","question":"The Bank for International Settlements, called the central bank of central banks and founded in 1930, is based at:","options":["Zurich","Geneva","Basel","Frankfurt"],"answer":2,"explanation":"The BIS is in Basel, Switzerland, and hosts the Basel Committee on Banking Supervision, whose norms are known as the Basel accords.","difficulty":"moderate","source":"SSC CGL · RBI Grade B","questionHi":"बैंक फॉर इंटरनेशनल सेटलमेंट्स, जिसे केंद्रीय बैंकों का केंद्रीय बैंक कहा जाता है और जिसकी स्थापना 1930 में हुई, कहाँ स्थित है?","optionsHi":["ज्यूरिख","जिनेवा","बेसल","फ्रैंकफर्ट"],"explanationHi":"BIS स्विट्जरलैंड के बेसल में है और बैंकिंग पर्यवेक्षण पर बेसल समिति की मेजबानी करता है, जिसके मानदंड बेसल समझौते कहलाते हैं।"},
  {"id":"gk-international-orgs-167","question":"The Basel III norms, framed after the 2008 financial crisis, mainly aim to:","options":["Harmonise deposit insurance limits across G20 countries","Strengthen banks' capital, liquidity and leverage standards","Fix interest-rate ceilings on cross-border bank lending","Set one minimum cash reserve ratio for all central banks"],"answer":1,"explanation":"Basel III raised the quality and quantity of bank capital and added a leverage ratio and liquidity ratios (LCR and NSFR); it does not set deposit insurance or reserve ratios.","difficulty":"hard","source":"RBI Grade B · IBPS PO Mains","questionHi":"2008 के वित्तीय संकट के बाद बनाए गए बेसल III मानदंडों का मुख्य उद्देश्य क्या है?","optionsHi":["G20 देशों में जमा बीमा की सीमाओं में एकरूपता लाना","बैंकों के पूँजी, तरलता और उत्तोलन मानकों को मजबूत करना","सीमा-पार बैंक ऋण पर ब्याज दरों की अधिकतम सीमा तय करना","सभी केंद्रीय बैंकों के लिए एक समान न्यूनतम नकद आरक्षित अनुपात निर्धारित करना"],"explanationHi":"बेसल III ने बैंक पूँजी की गुणवत्ता और मात्रा बढ़ाई तथा उत्तोलन अनुपात और तरलता अनुपात (LCR और NSFR) जोड़े; यह जमा बीमा या आरक्षित अनुपात तय नहीं करता।"},
  {"id":"gk-international-orgs-168","question":"The Financial Stability Board, set up by the G20 in 2009 to coordinate financial regulation, replaced the:","options":["Basel Committee on Banking Supervision","Financial Stability Forum","Group of Thirty","Paris Club"],"answer":1,"explanation":"The Financial Stability Forum, created by the G7 in 1999, was turned into the FSB with a broader membership after the 2008 crisis; it is hosted by the BIS in Basel.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"वित्तीय विनियमन में समन्वय के लिए 2009 में G20 द्वारा स्थापित वित्तीय स्थिरता बोर्ड ने किसका स्थान लिया?","optionsHi":["बैंकिंग पर्यवेक्षण पर बेसल समिति","वित्तीय स्थिरता मंच","ग्रुप ऑफ थर्टी","पेरिस क्लब"],"explanationHi":"वित्तीय स्थिरता मंच, जिसे G7 ने 1999 में बनाया था, को 2008 के संकट के बाद व्यापक सदस्यता के साथ FSB में बदल दिया गया; इसकी मेजबानी बेसल में BIS करता है।"},
  {"id":"gk-international-orgs-169","question":"The Paris Club is an informal group of:","options":["Commercial banks that renegotiate loans made to sovereign borrowers","Central banks that coordinate intervention in currency markets","Official creditor countries that coordinate debt relief for borrowers","Rich countries that fund the OECD's development assistance work"],"answer":2,"explanation":"The Paris Club brings together official (government) creditors to restructure debts of borrower countries; private bank creditors meet in the London Club.","difficulty":"hard","source":"UPSC Prelims · RBI Grade B","questionHi":"पेरिस क्लब किसका एक अनौपचारिक समूह है?","optionsHi":["वाणिज्यिक बैंकों का, जो संप्रभु उधारकर्ताओं को दिए गए ऋणों पर पुनः वार्ता करते हैं","केंद्रीय बैंकों का, जो मुद्रा बाजारों में हस्तक्षेप का समन्वय करते हैं","आधिकारिक ऋणदाता देशों का, जो उधारकर्ताओं के लिए ऋण राहत का समन्वय करते हैं","धनी देशों का, जो OECD के विकास सहायता कार्य को धन देते हैं"],"explanationHi":"पेरिस क्लब उधारकर्ता देशों के ऋणों के पुनर्गठन के लिए आधिकारिक (सरकारी) ऋणदाताओं को एक साथ लाता है; निजी बैंक ऋणदाता लंदन क्लब में मिलते हैं।"},
  {"id":"gk-international-orgs-170","question":"The OECD (1961) grew out of the OEEC, which was set up in 1948 to:","options":["Run the common market of the European Coal and Steel Community","Administer Marshall Plan aid for the rebuilding of Europe","Coordinate Western European defence against the Soviet bloc","Set a common external tariff for the six founding EEC states"],"answer":1,"explanation":"The Organisation for European Economic Co-operation managed US Marshall Plan aid; in 1961 it became the OECD, with the US and Canada as members, headquartered in Paris.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"OECD (1961) का विकास OEEC से हुआ, जिसे 1948 में किस उद्देश्य से बनाया गया था?","optionsHi":["यूरोपीय कोयला और इस्पात समुदाय का साझा बाजार चलाना","यूरोप के पुनर्निर्माण के लिए मार्शल योजना की सहायता का प्रबंधन करना","सोवियत गुट के विरुद्ध पश्चिमी यूरोप की रक्षा का समन्वय करना","छह संस्थापक EEC राज्यों के लिए एक साझा बाह्य शुल्क तय करना"],"explanationHi":"यूरोपीय आर्थिक सहयोग संगठन ने अमेरिकी मार्शल योजना की सहायता का प्रबंधन किया; 1961 में यह OECD बन गया, जिसमें अमेरिका और कनाडा सदस्य थे और जिसका मुख्यालय पेरिस में है।"},
  {"id":"gk-international-orgs-171","question":"OPEC was founded at the Baghdad Conference of September 1960 by Iran, Iraq, Kuwait, Saudi Arabia and:","options":["Libya","Qatar","Venezuela","United Arab Emirates"],"answer":2,"explanation":"Venezuela was the fifth founder; Qatar joined in 1961, Libya in 1962 and the UAE (through Abu Dhabi) in 1967.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"OPEC की स्थापना सितंबर 1960 के बगदाद सम्मेलन में ईरान, इराक, कुवैत, सऊदी अरब और किस देश ने की थी?","optionsHi":["लीबिया","कतर","वेनेजुएला","संयुक्त अरब अमीरात"],"explanationHi":"वेनेजुएला पाँचवाँ संस्थापक था; कतर 1961 में, लीबिया 1962 में और UAE (अबू धाबी के माध्यम से) 1967 में शामिल हुआ।"},
  {"id":"gk-international-orgs-172","question":"OPEC is headquartered in Vienna, although Austria is not a member. Where was its secretariat during its first five years, until 1965?","options":["Geneva","Baghdad","Caracas","Kuwait City"],"answer":0,"explanation":"OPEC's secretariat was in Geneva from 1961 and moved to Vienna in 1965 after Switzerland declined to extend diplomatic privileges.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"OPEC का मुख्यालय वियना में है, यद्यपि ऑस्ट्रिया इसका सदस्य नहीं है। 1965 तक के अपने पहले पाँच वर्षों में इसका सचिवालय कहाँ था?","optionsHi":["जिनेवा","बगदाद","काराकास","कुवैत सिटी"],"explanationHi":"OPEC का सचिवालय 1961 से जिनेवा में था और स्विट्जरलैंड द्वारा राजनयिक विशेषाधिकार देने से इनकार करने के बाद 1965 में वियना चला गया।"},
  {"id":"gk-international-orgs-173","question":"The African Development Bank is headquartered in:","options":["Addis Ababa","Nairobi","Lagos","Abidjan"],"answer":3,"explanation":"The AfDB is based at Abidjan, Côte d'Ivoire. Addis Ababa hosts the African Union and the UN Economic Commission for Africa.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"अफ्रीकी विकास बैंक का मुख्यालय कहाँ है?","optionsHi":["अदीस अबाबा","नैरोबी","लागोस","आबिदजान"],"explanationHi":"AfDB का मुख्यालय कोट डी आइवर के आबिदजान में है। अदीस अबाबा में अफ्रीकी संघ और अफ्रीका के लिए संयुक्त राष्ट्र आर्थिक आयोग हैं।"},
  {"id":"gk-international-orgs-174","question":"The European Bank for Reconstruction and Development, founded in 1991 to help former communist countries move to market economies, is headquartered in:","options":["London","Frankfurt","Luxembourg","Brussels"],"answer":0,"explanation":"The EBRD is in London. Luxembourg hosts the European Investment Bank and Frankfurt the European Central Bank.","difficulty":"hard","source":"UPSC Prelims · SSC CGL Tier 2","questionHi":"पूर्व साम्यवादी देशों को बाजार अर्थव्यवस्था की ओर बढ़ने में सहायता के लिए 1991 में स्थापित यूरोपीय पुनर्निर्माण एवं विकास बैंक का मुख्यालय कहाँ है?","optionsHi":["लंदन","फ्रैंकफर्ट","लक्ज़मबर्ग","ब्रुसेल्स"],"explanationHi":"EBRD लंदन में है। लक्ज़मबर्ग में यूरोपीय निवेश बैंक और फ्रैंकफर्ट में यूरोपीय केंद्रीय बैंक स्थित है।"},
  {"id":"gk-international-orgs-175","question":"Match the development bank with its headquarters. A. Islamic Development Bank  B. Inter-American Development Bank  C. European Investment Bank  D. New Development Bank; 1. Luxembourg  2. Shanghai  3. Washington, D.C.  4. Jeddah","options":["A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"answer":1,"explanation":"IsDB: Jeddah; IDB: Washington, D.C.; EIB: Luxembourg; NDB (BRICS bank): Shanghai.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"विकास बैंक का उसके मुख्यालय से मिलान कीजिए। A. इस्लामी विकास बैंक  B. अंतर-अमेरिकी विकास बैंक  C. यूरोपीय निवेश बैंक  D. न्यू डेवलपमेंट बैंक; 1. लक्ज़मबर्ग  2. शंघाई  3. वाशिंगटन, D.C.  4. जेद्दा","optionsHi":["A-4, B-1, C-3, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"explanationHi":"IsDB: जेद्दा; IDB: वाशिंगटन, D.C.; EIB: लक्ज़मबर्ग; NDB (ब्रिक्स बैंक): शंघाई।"},
  {"id":"gk-international-orgs-176","question":"The World Customs Organization, which maintains the Harmonized System (HS) for classifying traded goods, is headquartered in:","options":["Geneva","Vienna","Paris","Brussels"],"answer":3,"explanation":"The WCO, founded in 1952 as the Customs Co-operation Council, is based in Brussels; Geneva hosts the WTO.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"विश्व सीमा शुल्क संगठन, जो व्यापारिक वस्तुओं के वर्गीकरण के लिए सामंजस्यपूर्ण प्रणाली (HS) का रखरखाव करता है, का मुख्यालय कहाँ है?","optionsHi":["जिनेवा","वियना","पेरिस","ब्रुसेल्स"],"explanationHi":"WCO, जिसकी स्थापना 1952 में सीमा शुल्क सहयोग परिषद के रूप में हुई, ब्रुसेल्स में है; जिनेवा में WTO है।"},
  {"id":"gk-international-orgs-177","question":"The Contingent Reserve Arrangement agreed by the BRICS countries at Fortaleza in 2014 is meant to:","options":["Give members liquidity support against short-term balance-of-payments pressure","Finance infrastructure and sustainable development projects in member countries","Launch a common BRICS reserve currency to replace the US dollar in trade","Pool members' gold reserves to back a joint cross-border payments system"],"answer":0,"explanation":"The CRA is a reserve-pooling safety net for balance-of-payments stress; project finance is the job of the New Development Bank set up by the same Fortaleza declaration.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"2014 में फोर्टालेज़ा में ब्रिक्स देशों द्वारा सहमत आकस्मिक आरक्षित व्यवस्था (Contingent Reserve Arrangement) का उद्देश्य क्या है?","optionsHi":["अल्पकालिक भुगतान संतुलन दबाव के विरुद्ध सदस्यों को तरलता सहायता देना","सदस्य देशों में अवसंरचना और सतत विकास परियोजनाओं का वित्तपोषण करना","व्यापार में अमेरिकी डॉलर का स्थान लेने के लिए एक साझा ब्रिक्स आरक्षित मुद्रा शुरू करना","एक संयुक्त सीमा-पार भुगतान प्रणाली को समर्थन देने के लिए सदस्यों के स्वर्ण भंडार को एकत्र करना"],"explanationHi":"CRA भुगतान संतुलन के दबाव के लिए भंडार एकत्र करने वाली सुरक्षा व्यवस्था है; परियोजना वित्तपोषण उसी फोर्टालेज़ा घोषणा से बने न्यू डेवलपमेंट बैंक का कार्य है।"},
  {"id":"gk-international-orgs-178","question":"Arrange these countries in the order in which they joined ASEAN: 1. Vietnam  2. Brunei  3. Cambodia  4. Myanmar","options":["2-1-4-3","1-2-4-3","2-1-3-4","2-4-1-3"],"answer":0,"explanation":"Brunei joined in 1984, Vietnam in 1995, Laos and Myanmar in 1997 and Cambodia in 1999.","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"इन देशों को आसियान में शामिल होने के क्रम में व्यवस्थित कीजिए: 1. वियतनाम  2. ब्रुनेई  3. कंबोडिया  4. म्यांमार","optionsHi":["2-1-4-3","1-2-4-3","2-1-3-4","2-4-1-3"],"explanationHi":"ब्रुनेई 1984 में, वियतनाम 1995 में, लाओस और म्यांमार 1997 में तथा कंबोडिया 1999 में शामिल हुआ।"},
  {"id":"gk-international-orgs-179","question":"ASEAN was established in August 1967 by the:","options":["Manila Declaration","Bali Concord","Bangkok Declaration","Singapore Declaration"],"answer":2,"explanation":"Indonesia, Malaysia, the Philippines, Singapore and Thailand signed the ASEAN (Bangkok) Declaration on 8 August 1967.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"आसियान की स्थापना अगस्त 1967 में किसके द्वारा हुई?","optionsHi":["मनीला घोषणा","बाली समझौता","बैंकॉक घोषणा","सिंगापुर घोषणा"],"explanationHi":"इंडोनेशिया, मलेशिया, फिलीपींस, सिंगापुर और थाईलैंड ने 8 अगस्त 1967 को आसियान (बैंकॉक) घोषणा पर हस्ताक्षर किए।"},
  {"id":"gk-international-orgs-180","question":"The ASEAN Charter, which gave the grouping a legal personality, entered into force in:","options":["1997","2003","2015","2008"],"answer":3,"explanation":"The Charter was signed in 2007 and came into force in December 2008. The ASEAN Community was formally launched later, at the end of 2015.","difficulty":"hard","source":"UPSC Prelims","questionHi":"आसियान चार्टर, जिसने इस समूह को विधिक व्यक्तित्व दिया, किस वर्ष लागू हुआ?","optionsHi":["1997","2003","2015","2008"],"explanationHi":"चार्टर पर 2007 में हस्ताक्षर हुए और यह दिसंबर 2008 में लागू हुआ। आसियान समुदाय की औपचारिक शुरुआत बाद में, 2015 के अंत में हुई।"},
  {"id":"gk-international-orgs-181","question":"The first East Asia Summit, in which India took part as a founding participant, was held in 2005 at:","options":["Bandar Seri Begawan","Kuala Lumpur","Cebu","Jakarta"],"answer":1,"explanation":"The first EAS met in Kuala Lumpur in December 2005 with the ten ASEAN states, China, Japan, South Korea, India, Australia and New Zealand.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पहला पूर्वी एशिया शिखर सम्मेलन, जिसमें भारत ने संस्थापक भागीदार के रूप में भाग लिया, 2005 में कहाँ आयोजित हुआ था?","optionsHi":["बंदर सेरी बेगावान","कुआलालंपुर","सेबू","जकार्ता"],"explanationHi":"पहला EAS दिसंबर 2005 में कुआलालंपुर में हुआ, जिसमें दस आसियान राज्य, चीन, जापान, दक्षिण कोरिया, भारत, ऑस्ट्रेलिया और न्यूज़ीलैंड शामिल थे।"},
  {"id":"gk-international-orgs-182","question":"The ASEAN Regional Forum (ARF), set up in 1994, is mainly a platform for:","options":["Negotiating a free trade area between ASEAN and its dialogue partners","Coordinating disaster relief among ASEAN's own members","Settling maritime boundary disputes by binding arbitration","Dialogue on political and security issues in the Asia-Pacific"],"answer":3,"explanation":"The ARF is a consultative forum for security dialogue and confidence-building; it makes no binding decisions and has no trade or arbitration role.","difficulty":"hard","source":"UPSC Prelims","questionHi":"1994 में स्थापित आसियान क्षेत्रीय मंच (ARF) मुख्यतः किसका मंच है?","optionsHi":["आसियान और उसके संवाद भागीदारों के बीच मुक्त व्यापार क्षेत्र पर वार्ता","आसियान के अपने सदस्यों के बीच आपदा राहत का समन्वय","बाध्यकारी मध्यस्थता द्वारा समुद्री सीमा विवादों का निपटारा","एशिया-प्रशांत में राजनीतिक और सुरक्षा मुद्दों पर संवाद"],"explanationHi":"ARF सुरक्षा संवाद और विश्वास-निर्माण का परामर्शी मंच है; यह कोई बाध्यकारी निर्णय नहीं लेता और इसकी कोई व्यापारिक या मध्यस्थता भूमिका नहीं है।"},
  {"id":"gk-international-orgs-183","question":"Which of these statements about the Regional Comprehensive Economic Partnership (RCEP) are correct? I. It was signed in November 2020. II. India took part in the negotiations but pulled out in 2019. III. It includes the ten ASEAN states with China, Japan, South Korea, Australia and New Zealand. IV. The United States is a member.","options":["I and II only","I, II and III only","II, III and IV only","I, III and IV only"],"answer":1,"explanation":"I, II and III are correct. The United States is not in RCEP; it had earlier withdrawn from the separate Trans-Pacific Partnership in 2017.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"क्षेत्रीय व्यापक आर्थिक साझेदारी (RCEP) के बारे में इनमें से कौन-से कथन सही हैं? I. इस पर नवंबर 2020 में हस्ताक्षर हुए। II. भारत ने वार्ताओं में भाग लिया परंतु 2019 में बाहर हो गया। III. इसमें दस आसियान राज्य तथा चीन, जापान, दक्षिण कोरिया, ऑस्ट्रेलिया और न्यूज़ीलैंड शामिल हैं। IV. संयुक्त राज्य अमेरिका इसका सदस्य है।","optionsHi":["केवल I और II","केवल I, II और III","केवल II, III और IV","केवल I, III और IV"],"explanationHi":"I, II और III सही हैं। अमेरिका RCEP में नहीं है; वह 2017 में अलग ट्रांस-पैसिफिक पार्टनरशिप से पहले ही हट चुका था।"},
  {"id":"gk-international-orgs-184","question":"SAARC was formally established at its first summit, held in December 1985 in:","options":["Kathmandu","Colombo","New Delhi","Dhaka"],"answer":3,"explanation":"The SAARC Charter was adopted at Dhaka on 8 December 1985; the secretariat was later set up in Kathmandu in 1987.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"सार्क की औपचारिक स्थापना दिसंबर 1985 में उसके पहले शिखर सम्मेलन में कहाँ हुई?","optionsHi":["काठमांडू","कोलंबो","नई दिल्ली","ढाका"],"explanationHi":"सार्क चार्टर 8 दिसंबर 1985 को ढाका में अपनाया गया; सचिवालय बाद में 1987 में काठमांडू में स्थापित हुआ।"},
  {"id":"gk-international-orgs-185","question":"The South Asian Free Trade Area (SAFTA) agreement was signed at the SAARC summit in ______ and came into force in ______.","options":["Dhaka; 2004","Islamabad; 2004","Islamabad; 2006","Colombo; 2006"],"answer":2,"explanation":"SAFTA was signed at the 12th SAARC summit in Islamabad in January 2004 and took effect on 1 January 2006, succeeding SAPTA (1995).","difficulty":"very-hard","source":"UPSC Prelims · State PCS","questionHi":"दक्षिण एशियाई मुक्त व्यापार क्षेत्र (SAFTA) समझौते पर सार्क के ______ शिखर सम्मेलन में हस्ताक्षर हुए और यह ______ में लागू हुआ।","optionsHi":["ढाका; 2004","इस्लामाबाद; 2004","इस्लामाबाद; 2006","कोलंबो; 2006"],"explanationHi":"SAFTA पर जनवरी 2004 में इस्लामाबाद में 12वें सार्क शिखर सम्मेलन में हस्ताक्षर हुए और यह 1 जनवरी 2006 को प्रभावी हुआ, जिसने SAPTA (1995) का स्थान लिया।"},
  {"id":"gk-international-orgs-186","question":"BIMSTEC began in June 1997 as 'BIST-EC'. Which four countries founded it?","options":["Bangladesh, India, Myanmar, Thailand","Bhutan, India, Sri Lanka, Thailand","Bangladesh, India, Sri Lanka, Thailand","Bangladesh, India, Maldives, Thailand"],"answer":2,"explanation":"The initials stand for Bangladesh, India, Sri Lanka and Thailand. Myanmar joined later in 1997 (BIMST-EC) and Nepal and Bhutan in 2004.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"BIMSTEC की शुरुआत जून 1997 में ‘BIST-EC’ के रूप में हुई थी। इसकी स्थापना किन चार देशों ने की थी?","optionsHi":["बांग्लादेश, भारत, म्यांमार, थाईलैंड","भूटान, भारत, श्रीलंका, थाईलैंड","बांग्लादेश, भारत, श्रीलंका, थाईलैंड","बांग्लादेश, भारत, मालदीव, थाईलैंड"],"explanationHi":"संक्षिप्त नाम बांग्लादेश, भारत, श्रीलंका और थाईलैंड के लिए है। म्यांमार 1997 में ही बाद में जुड़ा (BIMST-EC) और नेपाल तथा भूटान 2004 में।"},
  {"id":"gk-international-orgs-187","question":"The BIMSTEC Charter was adopted in 2022 at the grouping's fifth summit, hosted by:","options":["Nepal","Sri Lanka","Thailand","Bangladesh"],"answer":1,"explanation":"Sri Lanka hosted the fifth summit (held in hybrid mode from Colombo) in March 2022, where the Charter was signed. Nepal hosted the fourth summit in Kathmandu in 2018.","difficulty":"hard","source":"UPSC Prelims","questionHi":"BIMSTEC चार्टर 2022 में समूह के पाँचवें शिखर सम्मेलन में अपनाया गया, जिसकी मेजबानी किसने की?","optionsHi":["नेपाल","श्रीलंका","थाईलैंड","बांग्लादेश"],"explanationHi":"श्रीलंका ने मार्च 2022 में पाँचवें शिखर सम्मेलन (कोलंबो से हाइब्रिड रूप में आयोजित) की मेजबानी की, जिसमें चार्टर पर हस्ताक्षर हुए। नेपाल ने 2018 में काठमांडू में चौथे शिखर सम्मेलन की मेजबानी की थी।"},
  {"id":"gk-international-orgs-188","question":"The Shanghai Cooperation Organisation grew out of the 'Shanghai Five', formed in 1996 by China, Russia, Kazakhstan, Kyrgyzstan and:","options":["Uzbekistan","Turkmenistan","Tajikistan","Mongolia"],"answer":2,"explanation":"Tajikistan was the fifth member. Uzbekistan joined in 2001, when the group became the SCO; Turkmenistan is not a member and Mongolia is an observer.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"शंघाई सहयोग संगठन ‘शंघाई फाइव’ से विकसित हुआ, जिसका गठन 1996 में चीन, रूस, कज़ाखस्तान, किर्गिज़स्तान और किस देश ने किया था?","optionsHi":["उज़्बेकिस्तान","तुर्कमेनिस्तान","ताजिकिस्तान","मंगोलिया"],"explanationHi":"ताजिकिस्तान पाँचवाँ सदस्य था। उज़्बेकिस्तान 2001 में शामिल हुआ, जब समूह SCO बना; तुर्कमेनिस्तान सदस्य नहीं है और मंगोलिया पर्यवेक्षक है।"},
  {"id":"gk-international-orgs-189","question":"Which of these statements about the SCO are correct? I. Its Regional Anti-Terrorist Structure (RATS) is headquartered in Tashkent. II. Chinese and Russian are its official languages. III. Its Charter was signed at St Petersburg in 2002. IV. India and Pakistan became full members at the Bishkek summit of 2019.","options":["I and III only","II, III and IV only","I, II and III only","I, II, III and IV"],"answer":2,"explanation":"I, II and III are correct. India and Pakistan became full members at the Astana summit in June 2017, not at Bishkek.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"SCO के बारे में इनमें से कौन-से कथन सही हैं? I. इसकी क्षेत्रीय आतंकवाद-रोधी संरचना (RATS) का मुख्यालय ताशकंद में है। II. चीनी और रूसी इसकी आधिकारिक भाषाएँ हैं। III. इसके चार्टर पर 2002 में सेंट पीटर्सबर्ग में हस्ताक्षर हुए। IV. भारत और पाकिस्तान 2019 के बिश्केक शिखर सम्मेलन में पूर्ण सदस्य बने।","optionsHi":["केवल I और III","केवल II, III और IV","केवल I, II और III","I, II, III और IV"],"explanationHi":"I, II और III सही हैं। भारत और पाकिस्तान जून 2017 के अस्ताना शिखर सम्मेलन में पूर्ण सदस्य बने, बिश्केक में नहीं।"},
  {"id":"gk-international-orgs-190","question":"The acronym 'BRIC' for Brazil, Russia, India and China was coined in 2001 by:","options":["Jim O'Neill of Goldman Sachs","Joseph Stiglitz of the World Bank","Paul Krugman of Princeton University","Jeffrey Sachs of Columbia University"],"answer":0,"explanation":"Goldman Sachs economist Jim O'Neill used the term in a 2001 paper on fast-growing economies; the countries began meeting as a group only later.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"ब्राजील, रूस, भारत और चीन के लिए संक्षिप्त नाम ‘BRIC’ 2001 में किसने गढ़ा था?","optionsHi":["गोल्डमैन सैक्स के जिम ओ’नील","विश्व बैंक के जोसेफ स्टिग्लिट्ज़","प्रिंसटन विश्वविद्यालय के पॉल क्रुगमैन","कोलंबिया विश्वविद्यालय के जेफ्री सैक्स"],"explanationHi":"गोल्डमैन सैक्स के अर्थशास्त्री जिम ओ’नील ने 2001 के एक शोध-पत्र में तेजी से बढ़ती अर्थव्यवस्थाओं के लिए इस शब्द का प्रयोग किया; ये देश बाद में ही एक समूह के रूप में मिलने लगे।"},
  {"id":"gk-international-orgs-191","question":"The first summit of the BRIC countries was held in 2009 at:","options":["Brasília","New Delhi","Rio de Janeiro","Yekaterinburg"],"answer":3,"explanation":"Yekaterinburg, Russia, hosted the first summit in June 2009. Sanya, China, hosted the 2011 summit, the first attended by South Africa.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"BRIC देशों का पहला शिखर सम्मेलन 2009 में कहाँ आयोजित हुआ?","optionsHi":["ब्रासीलिया","नई दिल्ली","रियो डी जनेरियो","येकातेरिनबर्ग"],"explanationHi":"रूस के येकातेरिनबर्ग ने जून 2009 में पहले शिखर सम्मेलन की मेजबानी की। चीन के सान्या ने 2011 के शिखर सम्मेलन की मेजबानी की, जिसमें पहली बार दक्षिण अफ्रीका ने भाग लिया।"},
  {"id":"gk-international-orgs-192","question":"Which of these statements about the G20 are correct? I. It began in 1999 as a forum of finance ministers and central bank governors after the Asian financial crisis. II. Its first leaders' summit was held in Washington, D.C., in 2008. III. It has a permanent secretariat in Geneva. IV. Each presidency works with a troika of the previous, current and next presidencies.","options":["I, II and IV only","I and II only","I, III and IV only","II, III and IV only"],"answer":0,"explanation":"I, II and IV are correct. The G20 has no permanent secretariat; the presidency country runs it for that year.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"G20 के बारे में इनमें से कौन-से कथन सही हैं? I. इसकी शुरुआत 1999 में एशियाई वित्तीय संकट के बाद वित्त मंत्रियों और केंद्रीय बैंक गवर्नरों के मंच के रूप में हुई। II. इसका पहला नेताओं का शिखर सम्मेलन 2008 में वाशिंगटन, D.C. में हुआ। III. जिनेवा में इसका एक स्थायी सचिवालय है। IV. प्रत्येक अध्यक्षता पिछली, वर्तमान और अगली अध्यक्षताओं की त्रयी (ट्रोइका) के साथ कार्य करती है।","optionsHi":["केवल I, II और IV","केवल I और II","केवल I, III और IV","केवल II, III और IV"],"explanationHi":"I, II और IV सही हैं। G20 का कोई स्थायी सचिवालय नहीं है; अध्यक्षता वाला देश उस वर्ष इसका संचालन करता है।"},
  {"id":"gk-international-orgs-193","question":"The first summit of what became the G7 was held in 1975 at Rambouillet with six countries. Which country joined in 1976 to make it seven?","options":["Canada","Italy","Japan","Russia"],"answer":0,"explanation":"Canada joined at the 1976 Puerto Rico summit. Italy was already at Rambouillet; Russia joined in 1997 to form the G8 and was suspended in 2014.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"जो आगे चलकर G7 बना, उसका पहला शिखर सम्मेलन 1975 में रैम्बूइये में छह देशों के साथ हुआ था। 1976 में कौन-सा देश शामिल होकर यह सात का समूह बन गया?","optionsHi":["कनाडा","इटली","जापान","रूस"],"explanationHi":"कनाडा 1976 के प्यूर्टो रिको शिखर सम्मेलन में शामिल हुआ। इटली रैम्बूइये में पहले से था; रूस 1997 में G8 बनाने के लिए शामिल हुआ और 2014 में निलंबित कर दिया गया।"},
  {"id":"gk-international-orgs-194","question":"The G4, whose members back one another's bids for permanent seats in the UN Security Council, are India, Brazil, Germany and:","options":["Japan","South Africa","Indonesia","Italy"],"answer":0,"explanation":"The G4 are India, Brazil, Germany and Japan. Italy leads the rival 'Uniting for Consensus' group that opposes new permanent seats.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"G4, जिसके सदस्य संयुक्त राष्ट्र सुरक्षा परिषद में स्थायी सीटों के लिए एक-दूसरे की दावेदारी का समर्थन करते हैं, भारत, ब्राजील, जर्मनी और किस देश का समूह है?","optionsHi":["जापान","दक्षिण अफ्रीका","इंडोनेशिया","इटली"],"explanationHi":"G4 में भारत, ब्राजील, जर्मनी और जापान हैं। इटली प्रतिद्वंद्वी ‘यूनाइटिंग फॉर कंसेंसस’ समूह का नेतृत्व करता है, जो नई स्थायी सीटों का विरोध करता है।"},
  {"id":"gk-international-orgs-195","question":"In the debate on Security Council reform, the 'Uniting for Consensus' group (which includes Italy and Pakistan):","options":["Backs permanent seats without a veto for India, Brazil, Germany and Japan","Opposes new permanent seats and favours more elected, non-permanent seats","Demands two permanent seats with full veto rights for African countries","Wants the veto abolished and the permanent seats rotated among regions"],"answer":1,"explanation":"Uniting for Consensus resists any new permanent members. The G4 seek permanent seats, and the African Union's Ezulwini Consensus asks for two permanent African seats with veto.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"सुरक्षा परिषद में सुधार की बहस में ‘यूनाइटिंग फॉर कंसेंसस’ समूह (जिसमें इटली और पाकिस्तान शामिल हैं) क्या करता है?","optionsHi":["भारत, ब्राजील, जर्मनी और जापान के लिए वीटो-रहित स्थायी सीटों का समर्थन करता है","नई स्थायी सीटों का विरोध करता है और अधिक निर्वाचित, अस्थायी सीटों का पक्ष लेता है","अफ्रीकी देशों के लिए पूर्ण वीटो अधिकारों के साथ दो स्थायी सीटों की माँग करता है","वीटो को समाप्त करना और स्थायी सीटों को क्षेत्रों के बीच बारी-बारी से देना चाहता है"],"explanationHi":"यूनाइटिंग फॉर कंसेंसस किसी भी नए स्थायी सदस्य का विरोध करता है। G4 स्थायी सीटें चाहता है, और अफ्रीकी संघ की एज़ुलविनी सहमति वीटो के साथ दो स्थायी अफ्रीकी सीटें माँगती है।"},
  {"id":"gk-international-orgs-196","question":"The Group of 77 was formed in 1964 through a joint declaration issued at the end of the first session of:","options":["The Non-Aligned Movement summit at Belgrade","The UN Conference on Trade and Development","The Asian–African Conference at Bandung","The UN Conference on the Human Environment"],"answer":1,"explanation":"Seventy-seven developing countries signed the joint declaration at the close of UNCTAD I in Geneva in June 1964. Belgrade (1961) and Bandung (1955) came earlier; Stockholm was in 1972.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"77 के समूह का गठन 1964 में किसके पहले सत्र के अंत में जारी एक संयुक्त घोषणा के माध्यम से हुआ?","optionsHi":["बेलग्रेड में गुटनिरपेक्ष आंदोलन का शिखर सम्मेलन","संयुक्त राष्ट्र व्यापार और विकास सम्मेलन","बांडुंग में एशियाई-अफ्रीकी सम्मेलन","संयुक्त राष्ट्र मानव पर्यावरण सम्मेलन"],"explanationHi":"सतहत्तर विकासशील देशों ने जून 1964 में जिनेवा में UNCTAD I के समापन पर संयुक्त घोषणा पर हस्ताक्षर किए। बेलग्रेड (1961) और बांडुंग (1955) पहले हुए थे; स्टॉकहोम 1972 में हुआ।"},
  {"id":"gk-international-orgs-197","question":"In WTO farm negotiations, the G-33 coalition of developing countries, which includes India, mainly seeks:","options":["Rapid elimination of all farm subsidies and tariffs by every WTO member","Removal of the cotton subsidies that rich countries pay to their own cotton farmers","Binding WTO rules to stop the patenting of traditional knowledge abroad","Flexibilities for developing countries on food security and special products"],"answer":3,"explanation":"The G-33 pushes for special products, a special safeguard mechanism and food-security stockholding. Full liberalisation is the Cairns Group's line and cotton the focus of the 'Cotton Four'.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"WTO की कृषि वार्ताओं में, विकासशील देशों का गठबंधन G-33, जिसमें भारत शामिल है, मुख्यतः क्या चाहता है?","optionsHi":["सभी WTO सदस्यों द्वारा सभी कृषि सब्सिडी और शुल्कों का शीघ्र उन्मूलन","धनी देशों द्वारा अपने कपास किसानों को दी जाने वाली कपास सब्सिडी की समाप्ति","पारंपरिक ज्ञान के विदेशों में पेटेंट को रोकने के लिए बाध्यकारी WTO नियम","खाद्य सुरक्षा और विशेष उत्पादों पर विकासशील देशों के लिए लचीलापन"],"explanationHi":"G-33 विशेष उत्पादों, विशेष रक्षोपाय तंत्र और खाद्य सुरक्षा भंडारण पर जोर देता है। पूर्ण उदारीकरण केर्न्स समूह की माँग है और कपास ‘कॉटन फोर’ का केंद्र है।"},
  {"id":"gk-international-orgs-198","question":"Which of these leaders was NOT one of the founders of the Non-Aligned Movement at Belgrade in 1961?","options":["Josip Broz Tito","Zhou Enlai","Gamal Abdel Nasser","Sukarno"],"answer":1,"explanation":"NAM's founding figures were Nehru, Tito, Nasser, Sukarno and Kwame Nkrumah. Zhou Enlai attended Bandung (1955), but China never joined NAM.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"इनमें से कौन-सा नेता 1961 में बेलग्रेड में गुटनिरपेक्ष आंदोलन के संस्थापकों में से नहीं था?","optionsHi":["जोसिप ब्रोज़ टीटो","चाउ एन-लाई","गमाल अब्देल नासिर","सुकर्णो"],"explanationHi":"NAM के संस्थापक नेता नेहरू, टीटो, नासिर, सुकर्णो और क्वामे एनक्रूमा थे। चाउ एन-लाई ने बांडुंग (1955) में भाग लिया था, परंतु चीन कभी NAM में शामिल नहीं हुआ।"},
  {"id":"gk-international-orgs-199","question":"The Panchsheel principles were first formally stated in the 1954 agreement between India and China on:","options":["The boundary between Ladakh and Xinjiang in Aksai Chin","Trade and intercourse between Tibet and India","Sharing the waters of the Brahmaputra","Mutual recognition of the status of Sikkim"],"answer":1,"explanation":"The five principles formed the preamble of the April 1954 agreement on trade and intercourse between the Tibet region of China and India; they were later echoed at Bandung and in NAM.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"पंचशील सिद्धांतों का पहला औपचारिक उल्लेख भारत और चीन के बीच 1954 के किस समझौते में हुआ?","optionsHi":["अक्साई चिन में लद्दाख और शिनजियांग के बीच की सीमा","तिब्बत और भारत के बीच व्यापार और आवागमन","ब्रह्मपुत्र के जल का बँटवारा","सिक्किम की स्थिति की पारस्परिक मान्यता"],"explanationHi":"ये पाँच सिद्धांत चीन के तिब्बत क्षेत्र और भारत के बीच व्यापार और आवागमन पर अप्रैल 1954 के समझौते की प्रस्तावना थे; बाद में बांडुंग और NAM में भी इनकी गूँज रही।"},
  {"id":"gk-international-orgs-200","question":"The London Declaration of 1949 is a landmark for the Commonwealth because it:","options":["Allowed India to stay a member as a republic, accepting the King as Head of the Commonwealth","Set up the Commonwealth Secretariat at Marlborough House in London to coordinate members' work","Laid down the shared values of all members in a single written Commonwealth Charter","Admitted the first member state with no historical link to the British Empire"],"answer":0,"explanation":"The Declaration let republics remain members, recognising the monarch only as Head of the Commonwealth. The Secretariat came in 1965, the Charter in 2012–13 and the first member without a British link (Mozambique) in 1995.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"1949 की लंदन घोषणा राष्ट्रमंडल के लिए एक ऐतिहासिक पड़ाव क्यों है?","optionsHi":["इसने भारत को गणराज्य के रूप में सदस्य बने रहने दिया, जिसमें वह राजा को राष्ट्रमंडल का प्रमुख स्वीकार करता है","इसने सदस्यों के कार्य के समन्वय के लिए लंदन के मार्लबरो हाउस में राष्ट्रमंडल सचिवालय स्थापित किया","इसने एक ही लिखित राष्ट्रमंडल चार्टर में सभी सदस्यों के साझा मूल्य निर्धारित किए","इसने ब्रिटिश साम्राज्य से कोई ऐतिहासिक संबंध न रखने वाले पहले सदस्य राज्य को प्रवेश दिया"],"explanationHi":"घोषणा ने गणराज्यों को सदस्य बने रहने दिया और सम्राट को केवल राष्ट्रमंडल के प्रमुख के रूप में मान्यता दी। सचिवालय 1965 में आया, चार्टर 2012-13 में और ब्रिटेन से संबंध-रहित पहला सदस्य (मोज़ाम्बिक) 1995 में।"},
  {"id":"gk-international-orgs-201","question":"Which of these Commonwealth members was never under British rule?","options":["Seychelles","Cyprus","Kenya","Mozambique"],"answer":3,"explanation":"Mozambique, a former Portuguese colony, joined in 1995 as the first member with no historical link to the British Empire; Rwanda followed in 2009.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"राष्ट्रमंडल के इनमें से कौन-से सदस्य पर कभी ब्रिटिश शासन नहीं रहा?","optionsHi":["सेशेल्स","साइप्रस","केन्या","मोज़ाम्बिक"],"explanationHi":"मोज़ाम्बिक, जो पूर्व पुर्तगाली उपनिवेश था, 1995 में ब्रिटिश साम्राज्य से कोई ऐतिहासिक संबंध न रखने वाले पहले सदस्य के रूप में शामिल हुआ; रवांडा 2009 में उसके बाद शामिल हुआ।"},
  {"id":"gk-international-orgs-202","question":"The League of Arab States was founded in March 1945 at:","options":["Riyadh","Damascus","Cairo","Baghdad"],"answer":2,"explanation":"The Arab League's pact was signed in Cairo, which also hosts its headquarters (it moved to Tunis from 1979 to 1990).","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"अरब राष्ट्रों की लीग की स्थापना मार्च 1945 में कहाँ हुई थी?","optionsHi":["रियाद","दमिश्क","काहिरा","बगदाद"],"explanationHi":"अरब लीग की संधि पर काहिरा में हस्ताक्षर हुए, जहाँ इसका मुख्यालय भी है (1979 से 1990 तक यह ट्यूनिस चला गया था)।"},
  {"id":"gk-international-orgs-203","question":"Which of these countries is NOT a member of the Gulf Cooperation Council, founded in 1981?","options":["Oman","Bahrain","Qatar","Iraq"],"answer":3,"explanation":"The GCC's six members are Saudi Arabia, the UAE, Kuwait, Qatar, Bahrain and Oman; Iraq has never been a member. Its secretariat is in Riyadh.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"1981 में स्थापित खाड़ी सहयोग परिषद का सदस्य इनमें से कौन-सा देश नहीं है?","optionsHi":["ओमान","बहरीन","कतर","इराक"],"explanationHi":"GCC के छह सदस्य सऊदी अरब, UAE, कुवैत, कतर, बहरीन और ओमान हैं; इराक कभी सदस्य नहीं रहा। इसका सचिवालय रियाद में है।"},
  {"id":"gk-international-orgs-204","question":"The European Coal and Steel Community, the first step towards today's European Union, was created by the:","options":["Treaty of Rome (1957)","Treaty of Paris (1951)","Treaty of Brussels (1948)","Treaty of Maastricht (1992)"],"answer":1,"explanation":"The 1951 Treaty of Paris set up the ECSC among six states; the Treaties of Rome (1957) created the EEC and Euratom, and Maastricht created the EU.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"यूरोपीय कोयला और इस्पात समुदाय, जो आज के यूरोपीय संघ की ओर पहला कदम था, किसके द्वारा बनाया गया?","optionsHi":["रोम की संधि (1957)","पेरिस की संधि (1951)","ब्रुसेल्स की संधि (1948)","मास्ट्रिख्ट की संधि (1992)"],"explanationHi":"1951 की पेरिस संधि ने छह राज्यों के बीच ECSC की स्थापना की; रोम की संधियों (1957) ने EEC और यूरेटम बनाए, और मास्ट्रिख्ट ने यूरोपीय संघ बनाया।"},
  {"id":"gk-international-orgs-205","question":"Match the body with the city where it is based. A. European Central Bank  B. Court of Justice of the European Union  C. European Commission  D. Europol; 1. Brussels  2. The Hague  3. Frankfurt  4. Luxembourg","options":["A-3, B-2, C-1, D-4","A-1, B-4, C-3, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"The ECB is in Frankfurt, the Court of Justice in Luxembourg, the Commission in Brussels and Europol, the EU police agency, in The Hague.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"निकाय का उस शहर से मिलान कीजिए जहाँ वह स्थित है। A. यूरोपीय केंद्रीय बैंक  B. यूरोपीय संघ का न्यायालय  C. यूरोपीय आयोग  D. यूरोपोल; 1. ब्रुसेल्स  2. द हेग  3. फ्रैंकफर्ट  4. लक्ज़मबर्ग","optionsHi":["A-3, B-2, C-1, D-4","A-1, B-4, C-3, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"explanationHi":"ECB फ्रैंकफर्ट में, न्यायालय लक्ज़मबर्ग में, आयोग ब्रुसेल्स में और यूरोपीय संघ की पुलिस एजेंसी यूरोपोल द हेग में है।"},
  {"id":"gk-international-orgs-206","question":"The withdrawal clause used by the United Kingdom to leave the European Union in 2020, Article 50 of the Treaty on European Union, was introduced by the:","options":["Treaty of Maastricht","Treaty of Amsterdam","Treaty of Lisbon","Treaty of Nice"],"answer":2,"explanation":"The Treaty of Lisbon (in force from December 2009) added the first explicit exit procedure; the UK triggered it in 2017 and left on 31 January 2020.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"यूनाइटेड किंगडम ने 2020 में यूरोपीय संघ छोड़ने के लिए जिस निकासी खंड, यूरोपीय संघ की संधि के अनुच्छेद 50, का प्रयोग किया, उसे किस संधि ने शामिल किया?","optionsHi":["मास्ट्रिख्ट की संधि","एम्स्टर्डम की संधि","लिस्बन की संधि","नीस की संधि"],"explanationHi":"लिस्बन की संधि (दिसंबर 2009 से लागू) ने पहली स्पष्ट निकासी प्रक्रिया जोड़ी; ब्रिटेन ने 2017 में इसे प्रारंभ किया और 31 जनवरी 2020 को बाहर हो गया।"},
  {"id":"gk-international-orgs-207","question":"Euro banknotes and coins went into circulation on 1 January of:","options":["1999","2002","2001","2004"],"answer":1,"explanation":"The euro existed from 1999 only as book money; cash followed on 1 January 2002 and national currencies were withdrawn within weeks.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"यूरो के बैंकनोट और सिक्के किस वर्ष की 1 जनवरी को प्रचलन में आए?","optionsHi":["1999","2002","2001","2004"],"explanationHi":"यूरो 1999 से केवल बही-मुद्रा के रूप में था; नकद 1 जनवरी 2002 को आया और राष्ट्रीय मुद्राएँ कुछ सप्ताहों में वापस ले ली गईं।"},
  {"id":"gk-international-orgs-208","question":"Which of these statements about the Schengen Area are correct? I. The Schengen Agreement was signed in 1985 in Luxembourg. II. Every member of the European Union is part of the Schengen Area. III. Some non-EU countries, such as Norway and Switzerland, belong to the Schengen Area. IV. Ireland has stayed outside the Schengen Area.","options":["I and III only","II, III and IV only","I, II and III only","I, III and IV only"],"answer":3,"explanation":"Schengen is a village in Luxembourg where the 1985 agreement was signed. Not every EU state is in the area (Ireland has opted out), while non-EU Norway, Iceland, Switzerland and Liechtenstein are.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"शेंगेन क्षेत्र के बारे में इनमें से कौन-से कथन सही हैं? I. शेंगेन समझौते पर 1985 में लक्ज़मबर्ग में हस्ताक्षर हुए। II. यूरोपीय संघ का प्रत्येक सदस्य शेंगेन क्षेत्र का हिस्सा है। III. नॉर्वे और स्विट्जरलैंड जैसे कुछ गैर-यूरोपीय संघ देश शेंगेन क्षेत्र में शामिल हैं। IV. आयरलैंड शेंगेन क्षेत्र से बाहर रहा है।","optionsHi":["केवल I और III","केवल II, III और IV","केवल I, II और III","केवल I, III और IV"],"explanationHi":"शेंगेन लक्ज़मबर्ग का एक गाँव है जहाँ 1985 का समझौता हुआ था। यूरोपीय संघ का हर राज्य इस क्षेत्र में नहीं है (आयरलैंड ने बाहर रहना चुना है), जबकि गैर-यूरोपीय संघ वाले नॉर्वे, आइसलैंड, स्विट्जरलैंड और लिकटेंस्टाइन इसमें हैं।"},
  {"id":"gk-international-orgs-209","question":"NATO's Article 5, under which an armed attack on one member is treated as an attack on all, has been invoked:","options":["Only once, after the 11 September 2001 attacks on the United States","Only once, after North Korea invaded South Korea in June 1950","Twice, in the Gulf War of 1991 and after the attacks of 2001","Never, because no member has formally asked for it to be used"],"answer":0,"explanation":"Article 5 was invoked for the only time on 12 September 2001. Korea was a UN action, and the 1991 Gulf War was not fought under Article 5.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"NATO के अनुच्छेद 5, जिसके अंतर्गत किसी एक सदस्य पर सशस्त्र हमले को सभी पर हमला माना जाता है, का प्रयोग कब हुआ है?","optionsHi":["केवल एक बार, संयुक्त राज्य अमेरिका पर 11 सितंबर 2001 के हमलों के बाद","केवल एक बार, जून 1950 में उत्तर कोरिया द्वारा दक्षिण कोरिया पर आक्रमण के बाद","दो बार, 1991 के खाड़ी युद्ध में और 2001 के हमलों के बाद","कभी नहीं, क्योंकि किसी सदस्य ने इसके प्रयोग का औपचारिक अनुरोध नहीं किया"],"explanationHi":"अनुच्छेद 5 का एकमात्र प्रयोग 12 सितंबर 2001 को हुआ। कोरिया में संयुक्त राष्ट्र की कार्रवाई थी, और 1991 का खाड़ी युद्ध अनुच्छेद 5 के अंतर्गत नहीं लड़ा गया था।"},
  {"id":"gk-international-orgs-210","question":"The Warsaw Pact, the Soviet-led military alliance, was formed in May 1955 as a direct response to:","options":["The founding of NATO in 1949","West Germany's entry into NATO","The launch of the Marshall Plan","The Treaty of Rome setting up the EEC"],"answer":1,"explanation":"The Warsaw Pact was signed days after West Germany joined NATO in May 1955; NATO itself had been founded six years earlier, and the Treaty of Rome came in 1957.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"वारसॉ संधि, सोवियत-नेतृत्व वाला सैन्य गठबंधन, मई 1955 में किसकी सीधी प्रतिक्रिया के रूप में बना?","optionsHi":["1949 में NATO की स्थापना","पश्चिमी जर्मनी का NATO में प्रवेश","मार्शल योजना की शुरुआत","EEC की स्थापना करने वाली रोम की संधि"],"explanationHi":"वारसॉ संधि पर हस्ताक्षर मई 1955 में पश्चिमी जर्मनी के NATO में शामिल होने के कुछ दिनों बाद हुए; NATO की स्थापना स्वयं छह वर्ष पहले हुई थी, और रोम की संधि 1957 में आई।"},
  {"id":"gk-international-orgs-211","question":"The African Union, which replaced the Organisation of African Unity, was formally launched in July 2002 at:","options":["Addis Ababa","Lomé","Sirte","Durban"],"answer":3,"explanation":"The AU was launched at Durban, South Africa. The 1999 Sirte Declaration called for it and its Constitutive Act was adopted at Lomé in 2000; its seat is Addis Ababa.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अफ्रीकी एकता संगठन का स्थान लेने वाला अफ्रीकी संघ जुलाई 2002 में औपचारिक रूप से कहाँ शुरू हुआ?","optionsHi":["अदीस अबाबा","लोमे","सिर्ते","डरबन"],"explanationHi":"AU की शुरुआत दक्षिण अफ्रीका के डरबन में हुई। 1999 की सिर्ते घोषणा ने इसका आह्वान किया था और इसका संवैधानिक अधिनियम 2000 में लोमे में अपनाया गया; इसका मुख्यालय अदीस अबाबा है।"},
  {"id":"gk-international-orgs-212","question":"The Organisation of African Unity was founded in May 1963 at:","options":["Accra","Addis Ababa","Cairo","Dar es Salaam"],"answer":1,"explanation":"Thirty-two independent African states signed the OAU Charter at Addis Ababa, which remains the seat of its successor, the African Union.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"अफ्रीकी एकता संगठन की स्थापना मई 1963 में कहाँ हुई थी?","optionsHi":["अक्करा","अदीस अबाबा","काहिरा","दार एस सलाम"],"explanationHi":"बत्तीस स्वतंत्र अफ्रीकी राज्यों ने अदीस अबाबा में OAU चार्टर पर हस्ताक्षर किए, जो आज भी इसके उत्तराधिकारी अफ्रीकी संघ का मुख्यालय है।"},
  {"id":"gk-international-orgs-213","question":"Mercosur, the South American trade bloc, was set up in 1991 by the Treaty of:","options":["Montevideo","Ouro Preto","Asunción","Brasília"],"answer":2,"explanation":"Argentina, Brazil, Paraguay and Uruguay signed the Treaty of Asunción in 1991. The 1994 Ouro Preto Protocol gave the bloc its institutions; Montevideo hosts its secretariat.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"दक्षिण अमेरिकी व्यापार समूह मर्कोसुर की स्थापना 1991 में किस संधि द्वारा हुई?","optionsHi":["मोंटेविडियो","ओरो प्रेतो","असुनसियोन","ब्रासीलिया"],"explanationHi":"अर्जेंटीना, ब्राजील, पैराग्वे और उरुग्वे ने 1991 में असुनसियोन की संधि पर हस्ताक्षर किए। 1994 के ओरो प्रेतो प्रोटोकॉल ने समूह को उसके संस्थान दिए; मोंटेविडियो में इसका सचिवालय है।"},
  {"id":"gk-international-orgs-214","question":"Which of these countries is NOT a member economy of the Asia-Pacific Economic Cooperation (APEC) forum?","options":["Peru","Vietnam","Russia","India"],"answer":3,"explanation":"India has sought APEC membership but is not a member; Peru, Vietnam and Russia were the last to join, in 1998, after which APEC froze new admissions.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"इनमें से कौन-सी अर्थव्यवस्था एशिया-प्रशांत आर्थिक सहयोग (APEC) मंच की सदस्य नहीं है?","optionsHi":["पेरू","वियतनाम","रूस","भारत"],"explanationHi":"भारत ने APEC की सदस्यता चाही है परंतु वह सदस्य नहीं है; पेरू, वियतनाम और रूस 1998 में सबसे अंत में शामिल हुए, जिसके बाद APEC ने नए प्रवेश रोक दिए।"},
  {"id":"gk-international-orgs-215","question":"The Commission of the Economic Community of West African States (ECOWAS) is headquartered in:","options":["Abuja","Accra","Dakar","Lagos"],"answer":0,"explanation":"The ECOWAS Commission is in Abuja, Nigeria. The community was founded by the Treaty of Lagos in 1975, which is a common trap.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"पश्चिम अफ्रीकी राज्यों के आर्थिक समुदाय (ECOWAS) के आयोग का मुख्यालय कहाँ है?","optionsHi":["अबुजा","अक्करा","डकार","लागोस"],"explanationHi":"ECOWAS आयोग नाइजीरिया के अबुजा में है। समुदाय की स्थापना 1975 की लागोस संधि से हुई थी, जो एक आम भ्रम का कारण है।"},
  {"id":"gk-international-orgs-216","question":"Which of these statements about the Treaty on the Non-Proliferation of Nuclear Weapons (NPT) are correct? I. It was opened for signature in 1968 and came into force in 1970. II. It was extended indefinitely in 1995. III. It recognises as nuclear-weapon states only those that exploded a nuclear device before 1 January 1967. IV. India signed it in 1974 but never ratified it.","options":["I, II and III only","I and II only","II, III and IV only","I, III and IV only"],"answer":0,"explanation":"I, II and III are correct. India has never signed the NPT, calling it discriminatory, because the 1967 cut-off freezes the five nuclear powers.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"परमाणु अस्त्र अप्रसार संधि (NPT) के बारे में इनमें से कौन-से कथन सही हैं? I. इसे 1968 में हस्ताक्षर के लिए खोला गया और यह 1970 में लागू हुई। II. 1995 में इसे अनिश्चित काल के लिए बढ़ा दिया गया। III. यह केवल उन्हीं देशों को परमाणु-अस्त्र संपन्न राज्य मानती है जिन्होंने 1 जनवरी 1967 से पहले परमाणु उपकरण का विस्फोट किया। IV. भारत ने 1974 में इस पर हस्ताक्षर किए पर कभी अनुसमर्थन नहीं किया।","optionsHi":["केवल I, II और III","केवल I और II","केवल II, III और IV","केवल I, III और IV"],"explanationHi":"I, II और III सही हैं। भारत ने NPT पर कभी हस्ताक्षर नहीं किए और इसे भेदभावपूर्ण बताया है, क्योंकि 1967 की कटऑफ तिथि पाँच परमाणु शक्तियों को स्थायी बना देती है।"},
  {"id":"gk-international-orgs-217","question":"The Comprehensive Nuclear-Test-Ban Treaty (1996) has still not entered into force because:","options":["It needs ratification by two-thirds of all UN members, a mark it has not reached","Its verification system, run from Vienna, has not yet been completed or certified","It must be ratified by all 44 states listed in its Annex 2, and several have not done so","The Security Council has not passed the resolution needed to bring it into effect"],"answer":2,"explanation":"Entry into force needs all 44 Annex 2 states (those with nuclear reactors or research capacity in 1996); India, Pakistan and North Korea have not signed, and some others have not ratified.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"व्यापक परमाणु परीक्षण प्रतिबंध संधि (1996) अब तक लागू क्यों नहीं हुई है?","optionsHi":["इसके लिए संयुक्त राष्ट्र के सभी सदस्यों के दो-तिहाई का अनुसमर्थन चाहिए, जो अभी नहीं हुआ","वियना से संचालित इसकी सत्यापन प्रणाली अभी पूरी या प्रमाणित नहीं हुई है","इसके लिए सभी 44 राज्यों का अनुसमर्थन आवश्यक है, जो इसके अनुलग्नक 2 में सूचीबद्ध हैं, और कई ने ऐसा नहीं किया है","सुरक्षा परिषद ने इसे प्रभावी करने के लिए आवश्यक प्रस्ताव पारित नहीं किया है"],"explanationHi":"लागू होने के लिए सभी 44 अनुलग्नक 2 राज्यों (1996 में परमाणु रिएक्टर या अनुसंधान क्षमता वाले देश) की आवश्यकता है; भारत, पाकिस्तान और उत्तर कोरिया ने हस्ताक्षर नहीं किए हैं, और कुछ अन्य ने अनुसमर्थन नहीं किया है।"},
  {"id":"gk-international-orgs-218","question":"The Partial Test Ban Treaty of 1963, which India joined, prohibits nuclear test explosions everywhere EXCEPT:","options":["In outer space","Under water","In the atmosphere","Underground"],"answer":3,"explanation":"The PTBT bans tests in the atmosphere, outer space and under water, but not underground, which is why India's 1974 and 1998 tests were underground.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1963 की आंशिक परीक्षण प्रतिबंध संधि, जिसमें भारत शामिल हुआ, परमाणु परीक्षण विस्फोटों को हर जगह प्रतिबंधित करती है, सिवाय:","optionsHi":["बाह्य अंतरिक्ष में","जल के नीचे","वायुमंडल में","भूमिगत"],"explanationHi":"PTBT वायुमंडल, बाह्य अंतरिक्ष और जल के नीचे परीक्षणों पर प्रतिबंध लगाती है, भूमिगत पर नहीं, इसीलिए भारत के 1974 और 1998 के परीक्षण भूमिगत थे।"},
  {"id":"gk-international-orgs-219","question":"Which statement about the Biological Weapons Convention (1972) is correct?","options":["It was the first treaty to ban a whole category of weapons of mass destruction, but has no formal verification body","It is verified through routine inspections of member states by the OPCW from its headquarters at The Hague","It allows members to keep limited stocks of biological agents for use only in retaliation against an attack","It binds only those members that hold nuclear weapons, leaving all others free to research biological agents"],"answer":0,"explanation":"The BWC (in force 1975) bans development, production and stockpiling of biological weapons but lacks a verification agency; the OPCW verifies the separate Chemical Weapons Convention.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जैविक हथियार अभिसमय (1972) के बारे में कौन-सा कथन सही है?","optionsHi":["यह सामूहिक विनाश के हथियारों की एक पूरी श्रेणी को प्रतिबंधित करने वाली पहली संधि थी, परंतु इसकी कोई औपचारिक सत्यापन संस्था नहीं है","इसका सत्यापन द हेग स्थित मुख्यालय से OPCW द्वारा सदस्यों के नियमित निरीक्षण के माध्यम से होता है","यह सदस्यों को केवल हमले के प्रतिशोध में उपयोग के लिए जैविक एजेंटों का सीमित भंडार रखने की अनुमति देता है","यह केवल उन सदस्यों पर बाध्यकारी है जिनके पास परमाणु हथियार हैं, अन्य सभी जैविक एजेंटों पर अनुसंधान के लिए स्वतंत्र हैं"],"explanationHi":"BWC (1975 में लागू) जैविक हथियारों के विकास, उत्पादन और भंडारण पर प्रतिबंध लगाता है, परंतु इसकी कोई सत्यापन एजेंसी नहीं है; OPCW अलग रासायनिक हथियार अभिसमय का सत्यापन करता है।"},
  {"id":"gk-international-orgs-220","question":"The Outer Space Treaty of 1967 provides that:","options":["Only permanent members of the Security Council may place satellites in geostationary orbit","Nuclear weapons may be placed in Earth orbit as long as they are meant only for defence","No state may claim sovereignty over the Moon or other celestial bodies by any means","Minerals mined on the Moon become the property of the state whose firms extract them"],"answer":2,"explanation":"Article II bars national appropriation of outer space and celestial bodies, and Article IV bans placing nuclear weapons in orbit; it says nothing that reserves orbits for any state.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1967 की बाह्य अंतरिक्ष संधि क्या प्रावधान करती है?","optionsHi":["केवल सुरक्षा परिषद के स्थायी सदस्य ही भू-स्थिर कक्षा में उपग्रह स्थापित कर सकते हैं","पृथ्वी की कक्षा में परमाणु हथियार तब तक रखे जा सकते हैं जब तक वे केवल रक्षा के लिए हों","कोई भी राज्य किसी भी तरीके से चंद्रमा या अन्य खगोलीय पिंडों पर संप्रभुता का दावा नहीं कर सकता","चंद्रमा पर खनन किए गए खनिज उस राज्य की संपत्ति बन जाते हैं जिसकी कंपनियाँ उन्हें निकालती हैं"],"explanationHi":"अनुच्छेद II बाह्य अंतरिक्ष और खगोलीय पिंडों के राष्ट्रीय विनियोग पर रोक लगाता है, और अनुच्छेद IV कक्षा में परमाणु हथियार रखने पर प्रतिबंध लगाता है; यह किसी राज्य के लिए कक्षाएँ आरक्षित करने की बात नहीं कहता।"},
  {"id":"gk-international-orgs-221","question":"India is a party to most global disarmament treaties. Which one of these has India NOT joined?","options":["Chemical Weapons Convention","Biological Weapons Convention","Partial Test Ban Treaty","Ottawa Mine Ban Treaty"],"answer":3,"explanation":"India has not joined the 1997 Ottawa Treaty banning anti-personnel landmines, citing security needs on its borders; it is a party to the CWC, BWC and PTBT.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत अधिकांश वैश्विक निरस्त्रीकरण संधियों का पक्षकार है। इनमें से किसमें भारत शामिल नहीं हुआ है?","optionsHi":["रासायनिक हथियार अभिसमय","जैविक हथियार अभिसमय","आंशिक परीक्षण प्रतिबंध संधि","ओटावा बारूदी सुरंग प्रतिबंध संधि"],"explanationHi":"भारत ने अपनी सीमाओं पर सुरक्षा आवश्यकताओं का हवाला देते हुए कार्मिक-रोधी बारूदी सुरंगों पर प्रतिबंध लगाने वाली 1997 की ओटावा संधि में भाग नहीं लिया है; वह CWC, BWC और PTBT का पक्षकार है।"},
  {"id":"gk-international-orgs-222","question":"In which order did India join these export-control regimes? 1. Australia Group  2. Missile Technology Control Regime  3. Wassenaar Arrangement","options":["3-2-1","2-1-3","2-3-1","1-2-3"],"answer":2,"explanation":"India joined the MTCR in June 2016, the Wassenaar Arrangement in December 2017 and the Australia Group in January 2018; it is still outside the Nuclear Suppliers Group.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"भारत इन निर्यात-नियंत्रण व्यवस्थाओं में किस क्रम में शामिल हुआ? 1. ऑस्ट्रेलिया समूह  2. मिसाइल प्रौद्योगिकी नियंत्रण व्यवस्था  3. वासेनार व्यवस्था","optionsHi":["3-2-1","2-1-3","2-3-1","1-2-3"],"explanationHi":"भारत जून 2016 में MTCR में, दिसंबर 2017 में वासेनार व्यवस्था में और जनवरी 2018 में ऑस्ट्रेलिया समूह में शामिल हुआ; वह अब भी परमाणु आपूर्तिकर्ता समूह से बाहर है।"},
  {"id":"gk-international-orgs-223","question":"The Australia Group, an export-control regime that India joined in 2018, aims to stop the spread of:","options":["Ballistic missiles and cruise missiles","Chemical and biological weapons","Conventional arms and dual-use goods","Nuclear materials and reactor technology"],"answer":1,"explanation":"Formed in 1985 after chemical weapons were used in the Iran–Iraq war, it harmonises controls on chemical and biological items. Missiles fall under the MTCR, conventional arms under Wassenaar and nuclear items under the NSG.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"ऑस्ट्रेलिया समूह, जो एक निर्यात-नियंत्रण व्यवस्था है और जिसमें भारत 2018 में शामिल हुआ, किसके प्रसार को रोकने का लक्ष्य रखता है?","optionsHi":["बैलिस्टिक मिसाइलें और क्रूज़ मिसाइलें","रासायनिक और जैविक हथियार","पारंपरिक हथियार और दोहरे उपयोग वाली वस्तुएँ","परमाणु सामग्री और रिएक्टर प्रौद्योगिकी"],"explanationHi":"ईरान-इराक युद्ध में रासायनिक हथियारों के प्रयोग के बाद 1985 में गठित, यह रासायनिक और जैविक वस्तुओं पर नियंत्रणों में सामंजस्य लाता है। मिसाइलें MTCR के, पारंपरिक हथियार वासेनार के और परमाणु वस्तुएँ NSG के अंतर्गत आती हैं।"},
  {"id":"gk-international-orgs-224","question":"The four Geneva Conventions of 1949 and their Additional Protocols form the core of:","options":["International refugee law, which defines who is a refugee and bars sending them back","International humanitarian law, which protects people not or no longer taking part in fighting","International human rights law, which guarantees civil and political rights in peacetime","The law of the sea, which governs the passage of warships through territorial waters"],"answer":1,"explanation":"The Geneva Conventions regulate conduct in armed conflict, protecting the wounded, prisoners of war and civilians; refugee law rests on the separate 1951 Refugee Convention.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"1949 के चार जिनेवा अभिसमय और उनके अतिरिक्त प्रोटोकॉल किसके मूल आधार हैं?","optionsHi":["अंतर्राष्ट्रीय शरणार्थी कानून, जो परिभाषित करता है कि शरणार्थी कौन है और उन्हें वापस भेजने पर रोक लगाता है","अंतर्राष्ट्रीय मानवीय कानून, जो लड़ाई में भाग न ले रहे या न ले सकने वाले लोगों की रक्षा करता है","अंतर्राष्ट्रीय मानवाधिकार कानून, जो शांति काल में नागरिक और राजनीतिक अधिकारों की गारंटी देता है","समुद्री कानून, जो प्रादेशिक जल से युद्धपोतों के गुजरने को नियंत्रित करता है"],"explanationHi":"जिनेवा अभिसमय सशस्त्र संघर्ष में आचरण को विनियमित करते हैं और घायलों, युद्धबंदियों और नागरिकों की रक्षा करते हैं; शरणार्थी कानून अलग 1951 के शरणार्थी अभिसमय पर आधारित है।"},
  {"id":"gk-international-orgs-225","question":"Assertion (A): India is not a party to the 1951 Refugee Convention or its 1967 Protocol. Reason (R): The UN High Commissioner for Refugees has no office in India.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"India has not signed the Convention and handles refugees under its own laws, but UNHCR does work in India from an office in New Delhi, so R is false.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"अभिकथन (A): भारत 1951 के शरणार्थी अभिसमय या उसके 1967 के प्रोटोकॉल का पक्षकार नहीं है। कारण (R): संयुक्त राष्ट्र शरणार्थी उच्चायुक्त का भारत में कोई कार्यालय नहीं है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"भारत ने अभिसमय पर हस्ताक्षर नहीं किए हैं और शरणार्थियों को अपने कानूनों के अंतर्गत संभालता है, परंतु UNHCR नई दिल्ली स्थित कार्यालय से भारत में कार्य करता है, इसलिए R असत्य है।"},
  {"id":"gk-international-orgs-226","question":"An Interpol 'Red Notice' is a request to law-enforcement agencies worldwide to:","options":["Locate and provisionally arrest a person pending extradition or similar action","Collect more information about a person's identity, location or activities","Warn of a person whose criminal activities may threaten public safety","Help find a missing person, often a minor, or identify a person who cannot do so"],"answer":0,"explanation":"A Red Notice seeks the location and provisional arrest of a wanted person. Blue notices seek information, Green notices warn about criminals and Yellow notices concern missing persons.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"इंटरपोल का ‘रेड नोटिस’ विश्व भर की कानून-प्रवर्तन एजेंसियों से क्या अनुरोध है?","optionsHi":["प्रत्यर्पण या इसी प्रकार की कार्रवाई लंबित रहने तक किसी व्यक्ति का पता लगाना और उसे अस्थायी रूप से गिरफ्तार करना","किसी व्यक्ति की पहचान, ठिकाने या गतिविधियों के बारे में अधिक जानकारी एकत्र करना","ऐसे व्यक्ति के बारे में चेतावनी देना जिसकी आपराधिक गतिविधियाँ सार्वजनिक सुरक्षा के लिए खतरा हो सकती हैं","किसी लापता व्यक्ति, प्रायः नाबालिग, को खोजने में सहायता करना या ऐसे व्यक्ति की पहचान करना जो स्वयं नहीं बता सकता"],"explanationHi":"रेड नोटिस वांछित व्यक्ति का पता लगाने और उसे अस्थायी रूप से गिरफ्तार करने की माँग करता है। ब्लू नोटिस जानकारी माँगते हैं, ग्रीन नोटिस अपराधियों के बारे में चेतावनी देते हैं और येलो नोटिस लापता व्यक्तियों से संबंधित हैं।"},
  {"id":"gk-international-orgs-227","question":"The Convention on the Prevention and Punishment of the Crime of Genocide was adopted by the UN General Assembly in:","options":["1945","1966","1948","1998"],"answer":2,"explanation":"It was adopted on 9 December 1948, a day before the Universal Declaration of Human Rights. 1966 brought the two human rights Covenants and 1998 the Rome Statute.","difficulty":"moderate","source":"SSC CGL Tier 2 · State PCS","questionHi":"जनसंहार के अपराध की रोकथाम और दंड पर अभिसमय संयुक्त राष्ट्र महासभा द्वारा किस वर्ष अपनाया गया?","optionsHi":["1945","1966","1948","1998"],"explanationHi":"इसे 9 दिसंबर 1948 को अपनाया गया, जो मानवाधिकारों की सार्वभौमिक घोषणा से एक दिन पहले था। 1966 में दो मानवाधिकार प्रसंविदाएँ आईं और 1998 में रोम संविधि।"},
  {"id":"gk-international-orgs-228","question":"Which of these was NOT adopted at the Rio Earth Summit of June 1992, but separately at a later date?","options":["Agenda 21","UN Convention to Combat Desertification","Rio Declaration on Environment and Development","The Forest Principles"],"answer":1,"explanation":"Rio called for a desertification treaty, but the UNCCD was adopted only in June 1994 in Paris. Agenda 21, the Rio Declaration and the Forest Principles came out of the 1992 summit, where the UNFCCC and CBD were also opened for signature.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-सा जून 1992 के रियो पृथ्वी शिखर सम्मेलन में नहीं, बल्कि बाद की किसी तिथि पर अलग से अपनाया गया?","optionsHi":["एजेंडा 21","संयुक्त राष्ट्र मरुस्थलीकरण रोकथाम अभिसमय","पर्यावरण और विकास पर रियो घोषणा","वन सिद्धांत"],"explanationHi":"रियो ने मरुस्थलीकरण संधि का आह्वान किया था, परंतु UNCCD केवल जून 1994 में पेरिस में अपनाया गया। एजेंडा 21, रियो घोषणा और वन सिद्धांत 1992 के शिखर सम्मेलन से निकले, जहाँ UNFCCC और CBD भी हस्ताक्षर के लिए खोले गए।"},
  {"id":"gk-international-orgs-229","question":"The Nagoya Protocol (2010) under the Convention on Biological Diversity deals with:","options":["Safe handling and transfer of living modified organisms","Phasing down the production and use of hydrofluorocarbons","Access to genetic resources and fair sharing of their benefits","Protection of wetlands of international importance for birds"],"answer":2,"explanation":"Nagoya covers access and benefit-sharing. Living modified organisms fall under the Cartagena Protocol, HFCs under the Kigali Amendment and wetlands under the Ramsar Convention.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जैविक विविधता अभिसमय के अंतर्गत नागोया प्रोटोकॉल (2010) किससे संबंधित है?","optionsHi":["संशोधित जीवों का सुरक्षित संचालन और अंतरण","हाइड्रोफ्लोरोकार्बन के उत्पादन और उपयोग को चरणबद्ध ढंग से घटाना","आनुवंशिक संसाधनों तक पहुँच और उनके लाभों का न्यायसंगत बँटवारा","पक्षियों के लिए अंतर्राष्ट्रीय महत्त्व की आर्द्रभूमियों की रक्षा"],"explanationHi":"नागोया पहुँच और लाभ-साझाकरण से संबंधित है। संशोधित जीव कार्टाजेना प्रोटोकॉल के, HFC किगाली संशोधन के और आर्द्रभूमियाँ रामसर अभिसमय के अंतर्गत आते हैं।"},
  {"id":"gk-international-orgs-230","question":"The '30 by 30' target of the Kunming–Montreal Global Biodiversity Framework (2022) calls for:","options":["Cutting global greenhouse gas emissions by 30% from 2010 levels by 2030","Conserving at least 30% of the world's land and of its oceans by 2030","Restoring native cover on 30% of the world's cleared forests by 2030","Bringing at least 30% of farmland under organic cultivation by 2030"],"answer":1,"explanation":"Target 3 of the framework, adopted at CBD COP15 in December 2022, seeks effective conservation of at least 30% of terrestrial and of marine areas by 2030.","difficulty":"hard","source":"UPSC Prelims","questionHi":"कुनमिंग-मॉन्ट्रियल वैश्विक जैव विविधता ढाँचे (2022) का ‘30 by 30’ लक्ष्य क्या माँग करता है?","optionsHi":["वैश्विक ग्रीनहाउस गैस उत्सर्जन में 30% की कटौती, 2010 के स्तर से, 2030 तक","विश्व की कम से कम 30% भूमि और महासागरों का संरक्षण, 2030 तक","विश्व के साफ किए गए वनों के 30% पर स्थानीय आवरण की बहाली, 2030 तक","कम से कम 30% कृषि भूमि को जैविक खेती के अंतर्गत लाना, 2030 तक"],"explanationHi":"दिसंबर 2022 में CBD COP15 में अपनाए गए ढाँचे के लक्ष्य संख्या 3 में 2030 तक कम से कम 30% स्थलीय और समुद्री क्षेत्रों के प्रभावी संरक्षण की माँग की गई है।"},
  {"id":"gk-international-orgs-231","question":"The Intergovernmental Panel on Climate Change (IPCC) was set up in 1988 by:","options":["The UNFCCC secretariat and UNDP","UNESCO and the World Meteorological Organization","The World Meteorological Organization and UNEP","The World Bank and UNEP"],"answer":2,"explanation":"WMO and UNEP created the IPCC in 1988, four years before the UNFCCC existed; it shared the 2007 Nobel Peace Prize with Al Gore.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"जलवायु परिवर्तन पर अंतर-सरकारी पैनल (IPCC) की स्थापना 1988 में किसने की?","optionsHi":["UNFCCC सचिवालय और UNDP","UNESCO और विश्व मौसम विज्ञान संगठन","विश्व मौसम विज्ञान संगठन और UNEP","विश्व बैंक और UNEP"],"explanationHi":"WMO और UNEP ने 1988 में IPCC बनाया, यानी UNFCCC के अस्तित्व में आने से चार वर्ष पहले; इसने 2007 का नोबेल शांति पुरस्कार अल गोर के साथ साझा किया।"},
  {"id":"gk-international-orgs-232","question":"The Green Climate Fund, set up under the UNFCCC in 2010, is headquartered at:","options":["Bonn, Germany","Songdo, South Korea","Geneva, Switzerland","Nairobi, Kenya"],"answer":1,"explanation":"The GCF is based in Songdo, Incheon, South Korea. Bonn hosts the UNFCCC secretariat and Nairobi hosts UNEP.","difficulty":"moderate","source":"UPSC Prelims · State PCS","questionHi":"UNFCCC के अंतर्गत 2010 में स्थापित हरित जलवायु कोष (Green Climate Fund) का मुख्यालय कहाँ है?","optionsHi":["बॉन, जर्मनी","सोंगदो, दक्षिण कोरिया","जिनेवा, स्विट्जरलैंड","नैरोबी, केन्या"],"explanationHi":"GCF का मुख्यालय दक्षिण कोरिया के इंचियोन के सोंगदो में है। बॉन में UNFCCC सचिवालय और नैरोबी में UNEP है।"},
  {"id":"gk-international-orgs-233","question":"The decision to set up a dedicated fund for 'loss and damage' suffered by climate-vulnerable countries was taken in 2022 at:","options":["COP26, Glasgow, UK","COP28, Dubai, UAE","COP25, Madrid, Spain","COP27, Sharm el-Sheikh"],"answer":3,"explanation":"COP27 at Sharm el-Sheikh agreed to create the fund; COP28 at Dubai (2023) made it operational. COP26 produced the Glasgow Climate Pact.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"जलवायु-संवेदनशील देशों को हुई ‘हानि और क्षति’ के लिए समर्पित कोष बनाने का निर्णय 2022 में कहाँ लिया गया?","optionsHi":["COP26, ग्लासगो, यूके","COP28, दुबई, UAE","COP25, मैड्रिड, स्पेन","COP27, शर्म अल-शेख"],"explanationHi":"शर्म अल-शेख में COP27 ने कोष बनाने पर सहमति दी; दुबई में COP28 (2023) ने इसे क्रियाशील बनाया। COP26 से ग्लासगो जलवायु समझौता निकला।"},
  {"id":"gk-international-orgs-234","question":"Which of these statements about the Montreal Protocol are correct? I. It was adopted in 1987 to phase out ozone-depleting substances. II. It was the first UN treaty to be ratified by every country in the world. III. The Kigali Amendment brought hydrofluorocarbons under it. IV. Its Multilateral Fund helps developing countries meet their phase-out commitments.","options":["I and III only","I, III and IV only","I, II and IV only","I, II, III and IV"],"answer":3,"explanation":"All four are correct. Universal ratification came in 2009, and the Multilateral Fund (1991) finances phase-out in developing countries such as India.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"मॉन्ट्रियल प्रोटोकॉल के बारे में इनमें से कौन-से कथन सही हैं? I. इसे 1987 में ओज़ोन क्षयकारी पदार्थों को चरणबद्ध ढंग से समाप्त करने के लिए अपनाया गया। II. यह दुनिया के प्रत्येक देश द्वारा अनुसमर्थित होने वाली पहली संयुक्त राष्ट्र संधि थी। III. किगाली संशोधन ने हाइड्रोफ्लोरोकार्बन को इसके अंतर्गत ला दिया। IV. इसका बहुपक्षीय कोष विकासशील देशों को उनकी चरणबद्ध समाप्ति की प्रतिबद्धताओं को पूरा करने में सहायता करता है।","optionsHi":["केवल I और III","केवल I, III और IV","केवल I, II और IV","I, II, III और IV"],"explanationHi":"चारों कथन सही हैं। सार्वभौमिक अनुसमर्थन 2009 में हुआ, और बहुपक्षीय कोष (1991) भारत जैसे विकासशील देशों में चरणबद्ध समाप्ति के लिए वित्त प्रदान करता है।"},
  {"id":"gk-international-orgs-235","question":"The International Solar Alliance, launched in 2015 and headquartered at Gurugram, is notable as:","options":["The first UN specialised agency to have its headquarters in South Asia","The first treaty-based international intergovernmental body to be based in India","A body whose membership is legally restricted to countries within the tropics","A body created by a resolution of the UN General Assembly at its 2015 session"],"answer":1,"explanation":"The ISA's framework agreement entered into force in 2017, making it the first treaty-based intergovernmental organisation headquartered in India. Membership, first meant for tropical countries, was later opened to all UN member states.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"2015 में शुरू हुआ और गुरुग्राम में मुख्यालय वाला अंतर्राष्ट्रीय सौर गठबंधन किस रूप में उल्लेखनीय है?","optionsHi":["दक्षिण एशिया में मुख्यालय वाली पहली संयुक्त राष्ट्र विशिष्ट एजेंसी","भारत में स्थित पहला संधि-आधारित अंतर्राष्ट्रीय अंतर-सरकारी निकाय","ऐसा निकाय जिसकी सदस्यता कानूनी रूप से उष्णकटिबंधीय देशों तक सीमित है","संयुक्त राष्ट्र महासभा के 2015 के सत्र में एक प्रस्ताव द्वारा बनाया गया निकाय"],"explanationHi":"ISA का रूपरेखा समझौता 2017 में लागू हुआ, जिससे यह भारत में मुख्यालय वाला पहला संधि-आधारित अंतर-सरकारी संगठन बन गया। सदस्यता, जो पहले उष्णकटिबंधीय देशों के लिए थी, बाद में संयुक्त राष्ट्र के सभी सदस्य देशों के लिए खोल दी गई।"},
  {"id":"gk-international-orgs-236","question":"The Coalition for Disaster Resilient Infrastructure (CDRI), launched by India in 2019 at the UN Climate Action Summit in New York, has its secretariat in:","options":["Geneva","Gurugram","Bengaluru","New Delhi"],"answer":3,"explanation":"CDRI's secretariat is in New Delhi. Gurugram is the seat of the separate International Solar Alliance.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"2019 में न्यूयॉर्क में संयुक्त राष्ट्र जलवायु कार्रवाई शिखर सम्मेलन में भारत द्वारा शुरू किए गए आपदा-रोधी अवसंरचना गठबंधन (CDRI) का सचिवालय कहाँ है?","optionsHi":["जिनेवा","गुरुग्राम","बेंगलुरु","नई दिल्ली"],"explanationHi":"CDRI का सचिवालय नई दिल्ली में है। गुरुग्राम अलग संस्था, अंतर्राष्ट्रीय सौर गठबंधन, का मुख्यालय है।"},
  {"id":"gk-international-orgs-237","question":"Which of these statements are correct? I. The Arctic Council was set up by the Ottawa Declaration of 1996. II. India has been an observer of the Arctic Council since 2013. III. Observer states have voting rights in the Council's decisions. IV. India's Arctic research station, Himadri, is at Ny-Ålesund in Svalbard, Norway.","options":["I, II and IV only","I and II only","II, III and IV only","I, III and IV only"],"answer":0,"explanation":"I, II and IV are correct. Decisions are taken by consensus of the eight Arctic states; observers such as India cannot vote. Himadri opened in 2008.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-से कथन सही हैं? I. आर्कटिक परिषद की स्थापना 1996 की ओटावा घोषणा से हुई। II. भारत 2013 से आर्कटिक परिषद का पर्यवेक्षक है। III. परिषद के निर्णयों में पर्यवेक्षक राज्यों को मताधिकार प्राप्त है। IV. भारत का आर्कटिक अनुसंधान केंद्र, हिमाद्री, नॉर्वे के स्वालबार्ड में न्यू-एलेसुंड में है।","optionsHi":["केवल I, II और IV","केवल I और II","केवल II, III और IV","केवल I, III और IV"],"explanationHi":"I, II और IV सही हैं। निर्णय आठ आर्कटिक राज्यों की सर्वसम्मति से लिए जाते हैं; भारत जैसे पर्यवेक्षक मतदान नहीं कर सकते। हिमाद्री 2008 में शुरू हुआ।"},
  {"id":"gk-international-orgs-238","question":"The International Tribunal for the Law of the Sea, set up under UNCLOS, sits at:","options":["Kingston","The Hague","Hamburg","Montego Bay"],"answer":2,"explanation":"ITLOS is in Hamburg, Germany. Kingston, Jamaica, hosts the International Seabed Authority, and Montego Bay is where UNCLOS was signed.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"UNCLOS के अंतर्गत स्थापित अंतर्राष्ट्रीय समुद्री कानून न्यायाधिकरण कहाँ स्थित है?","optionsHi":["किंग्स्टन","द हेग","हैम्बर्ग","मॉन्टेगो बे"],"explanationHi":"ITLOS जर्मनी के हैम्बर्ग में है। जमैका का किंग्स्टन अंतर्राष्ट्रीय समुद्र-तल प्राधिकरण का मुख्यालय है, और मॉन्टेगो बे वह स्थान है जहाँ UNCLOS पर हस्ताक्षर हुए।"},
  {"id":"gk-international-orgs-239","question":"Under UNCLOS, which maritime zone is correctly paired with its maximum breadth measured from the baseline?","options":["Territorial sea — 6 nautical miles","Exclusive economic zone — 150 nautical miles","Contiguous zone — 24 nautical miles","Contiguous zone — 12 nautical miles"],"answer":2,"explanation":"The territorial sea may extend to 12 nm, the contiguous zone to 24 nm and the exclusive economic zone to 200 nm from the baseline.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"UNCLOS के अंतर्गत कौन-सा समुद्री क्षेत्र आधार रेखा से मापी गई अपनी अधिकतम चौड़ाई के साथ सही ढंग से जोड़ा गया है?","optionsHi":["प्रादेशिक समुद्र — 6 समुद्री मील","विशेष आर्थिक क्षेत्र — 150 समुद्री मील","संलग्न क्षेत्र — 24 समुद्री मील","संलग्न क्षेत्र — 12 समुद्री मील"],"explanationHi":"प्रादेशिक समुद्र आधार रेखा से 12 समुद्री मील तक, संलग्न क्षेत्र 24 समुद्री मील तक और विशेष आर्थिक क्षेत्र 200 समुद्री मील तक विस्तृत हो सकता है।"},
  {"id":"gk-international-orgs-240","question":"The UN Convention on the Law of the Sea was opened for signature in 1982 at:","options":["Montego Bay, Jamaica","Kingston, Jamaica","Geneva, Switzerland","New York, USA"],"answer":0,"explanation":"UNCLOS was signed at Montego Bay in December 1982 and entered into force in 1994. Kingston is the seat of the International Seabed Authority.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र समुद्री कानून अभिसमय 1982 में कहाँ हस्ताक्षर के लिए खोला गया?","optionsHi":["मॉन्टेगो बे, जमैका","किंग्स्टन, जमैका","जिनेवा, स्विट्जरलैंड","न्यूयॉर्क, अमेरिका"],"explanationHi":"UNCLOS पर दिसंबर 1982 में मॉन्टेगो बे में हस्ताक्षर हुए और यह 1994 में लागू हुआ। किंग्स्टन अंतर्राष्ट्रीय समुद्र-तल प्राधिकरण का मुख्यालय है।"},
  {"id":"gk-international-orgs-241","question":"Henri Dunant was moved to found the Red Cross movement after seeing the wounded left on the battlefield of:","options":["Waterloo","Sevastopol","Sedan","Solferino"],"answer":3,"explanation":"Dunant witnessed the aftermath of Solferino (1859) in northern Italy and wrote 'A Memory of Solferino', which led to the ICRC's founding in Geneva in 1863.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"हेनरी ड्यूनेंट को रेड क्रॉस आंदोलन की स्थापना की प्रेरणा किस युद्धक्षेत्र में घायलों को असहाय छोड़ दिए जाने का दृश्य देखकर मिली?","optionsHi":["वाटरलू","सेवस्तोपोल","सेदान","सोल्फ़ेरीनो"],"explanationHi":"ड्यूनेंट ने उत्तरी इटली में सोल्फ़ेरीनो (1859) के बाद का दृश्य देखा और ‘ए मेमोरी ऑफ सोल्फ़ेरीनो’ लिखी, जिससे 1863 में जिनेवा में ICRC की स्थापना हुई।"},
  {"id":"gk-international-orgs-242","question":"The UN agency created in 1949 specifically to help Palestine refugees is:","options":["UNHCR","UNRWA","OCHA","UNFPA"],"answer":1,"explanation":"UNRWA (UN Relief and Works Agency) predates UNHCR (1950); Palestine refugees in its areas of operation fall under UNRWA rather than UNHCR.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"1949 में विशेष रूप से फिलिस्तीनी शरणार्थियों की सहायता के लिए बनाई गई संयुक्त राष्ट्र एजेंसी कौन-सी है?","optionsHi":["UNHCR","UNRWA","OCHA","UNFPA"],"explanationHi":"UNRWA (संयुक्त राष्ट्र राहत एवं निर्माण एजेंसी) UNHCR (1950) से पहले की है; इसके संचालन क्षेत्रों में फिलिस्तीनी शरणार्थी UNHCR के बजाय UNRWA के अंतर्गत आते हैं।"},
  {"id":"gk-international-orgs-243","question":"The 'International Bill of Human Rights' consists of the Universal Declaration of Human Rights together with:","options":["The two International Covenants of 1966 on civil-political and on economic-social rights","The four Geneva Conventions of 1949 and the Refugee Convention adopted in 1951","The Convention on the Rights of the Child and the women's rights convention CEDAW","The European and the American human rights conventions adopted after the war"],"answer":0,"explanation":"The UDHR (1948), the ICCPR and the ICESCR (both adopted in 1966, in force 1976) and the ICCPR's optional protocols make up the International Bill of Human Rights.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"‘मानवाधिकारों का अंतर्राष्ट्रीय विधेयक’ (International Bill of Human Rights) मानवाधिकारों की सार्वभौमिक घोषणा और किन के मिलने से बनता है?","optionsHi":["नागरिक-राजनीतिक तथा आर्थिक-सामाजिक अधिकारों पर 1966 की दो अंतर्राष्ट्रीय प्रसंविदाएँ","1949 के चार जिनेवा अभिसमय और 1951 में अपनाया गया शरणार्थी अभिसमय","बाल अधिकार अभिसमय और महिला अधिकार अभिसमय CEDAW","युद्ध के बाद अपनाए गए यूरोपीय और अमेरिकी मानवाधिकार अभिसमय"],"explanationHi":"UDHR (1948), ICCPR और ICESCR (दोनों 1966 में अपनाई गईं, 1976 में लागू) और ICCPR के वैकल्पिक प्रोटोकॉल मिलकर मानवाधिकारों का अंतर्राष्ट्रीय विधेयक बनाते हैं।"},
  {"id":"gk-international-orgs-244","question":"The post of UN High Commissioner for Human Rights was created in 1993, following the World Conference on Human Rights held at:","options":["Geneva","Beijing","Vienna","Copenhagen"],"answer":2,"explanation":"The 1993 Vienna Declaration and Programme of Action recommended the post, and the General Assembly created it that December. Beijing (1995) hosted the women's conference.","difficulty":"hard","source":"UPSC Prelims","questionHi":"संयुक्त राष्ट्र मानवाधिकार उच्चायुक्त का पद 1993 में कहाँ आयोजित मानवाधिकार विश्व सम्मेलन के बाद बनाया गया?","optionsHi":["जिनेवा","बीजिंग","वियना","कोपेनहेगन"],"explanationHi":"1993 की वियना घोषणा और कार्य-योजना ने इस पद की सिफारिश की, और महासभा ने उसी दिसंबर में इसे बनाया। बीजिंग (1995) ने महिला सम्मेलन की मेजबानी की।"},
  {"id":"gk-international-orgs-245","question":"Which of these statements are correct? I. The 17 Sustainable Development Goals were adopted by the UN General Assembly in 2015 as part of the 2030 Agenda. II. The SDGs have 169 targets. III. The eight Millennium Development Goals covered the period up to 2015. IV. Like the MDGs, the SDGs apply only to developing countries.","options":["I and II only","II, III and IV only","I, II and III only","I, III and IV only"],"answer":2,"explanation":"I, II and III are correct. Unlike the MDGs, which targeted developing countries, the SDGs are universal and apply to all countries.","difficulty":"very-hard","source":"UPSC Prelims","questionHi":"इनमें से कौन-से कथन सही हैं? I. 17 सतत विकास लक्ष्य 2015 में 2030 एजेंडा के भाग के रूप में संयुक्त राष्ट्र महासभा द्वारा अपनाए गए। II. SDG के 169 लक्ष्य (टारगेट) हैं। III. आठ सहस्राब्दी विकास लक्ष्य 2015 तक की अवधि के लिए थे। IV. MDG की तरह SDG केवल विकासशील देशों पर लागू होते हैं।","optionsHi":["केवल I और II","केवल II, III और IV","केवल I, II और III","केवल I, III और IV"],"explanationHi":"I, II और III सही हैं। विकासशील देशों को लक्षित करने वाले MDG के विपरीत, SDG सार्वभौमिक हैं और सभी देशों पर लागू होते हैं।"},
  {"id":"gk-international-orgs-246","question":"The UN General Assembly declared 2023 the International Year of Millets on a proposal from:","options":["Nigeria","Ethiopia","India","China"],"answer":2,"explanation":"India sponsored the resolution, adopted in March 2021; FAO led the observance in 2023.","difficulty":"moderate","source":"SSC CGL · State PCS","questionHi":"संयुक्त राष्ट्र महासभा ने 2023 को अंतर्राष्ट्रीय मिलेट वर्ष किसके प्रस्ताव पर घोषित किया?","optionsHi":["नाइजीरिया","इथियोपिया","भारत","चीन"],"explanationHi":"भारत ने प्रस्ताव प्रायोजित किया, जो मार्च 2021 में अपनाया गया; 2023 में FAO ने इस आयोजन का नेतृत्व किया।"},
  {"id":"gk-international-orgs-247","question":"The UN General Assembly resolution declaring 21 June as the International Day of Yoga was adopted in:","options":["2014","2016","2015","2021"],"answer":0,"explanation":"The resolution was adopted on 11 December 2014, after India proposed it that September. 2015 is the year of the first observance, 2016 is when yoga entered UNESCO's intangible heritage list, and 2021 is when India's millets resolution was adopted.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"21 जून को अंतर्राष्ट्रीय योग दिवस घोषित करने वाला संयुक्त राष्ट्र महासभा का प्रस्ताव किस वर्ष अपनाया गया?","optionsHi":["2014","2016","2015","2021"],"explanationHi":"भारत द्वारा उस वर्ष सितंबर में प्रस्ताव रखे जाने के बाद यह प्रस्ताव 11 दिसंबर 2014 को अपनाया गया। 2015 पहले आयोजन का वर्ष है, 2016 वह वर्ष है जब योग UNESCO की अमूर्त विरासत सूची में शामिल हुआ, और 2021 वह वर्ष है जब भारत का मिलेट प्रस्ताव अपनाया गया।"},
  {"id":"gk-international-orgs-248","question":"The World Organisation for Animal Health, founded in 1924 as the OIE, is headquartered in:","options":["Rome","Geneva","Bern","Paris"],"answer":3,"explanation":"WOAH is based in Paris. Rome hosts FAO and Geneva hosts WHO, its partners on animal and human health.","difficulty":"hard","source":"SSC CGL Tier 2 · State PCS","questionHi":"विश्व पशु स्वास्थ्य संगठन, जिसकी स्थापना 1924 में OIE के रूप में हुई थी, का मुख्यालय कहाँ है?","optionsHi":["रोम","जिनेवा","बर्न","पेरिस"],"explanationHi":"WOAH का मुख्यालय पेरिस में है। रोम में FAO और जिनेवा में WHO है, जो पशु और मानव स्वास्थ्य पर इसके भागीदार हैं।"},
  {"id":"gk-international-orgs-249","question":"The Codex Alimentarius Commission, which sets international food standards, was set up in 1963 jointly by:","options":["FAO and WHO","FAO and the WTO","WHO and UNICEF","WFP and IFAD"],"answer":0,"explanation":"Codex is a joint FAO/WHO body with its secretariat in Rome; the WTO's SPS Agreement later made Codex standards a reference point in trade disputes.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अंतर्राष्ट्रीय खाद्य मानक तय करने वाला कोडेक्स एलिमेंटेरियस आयोग 1963 में किन दोनों ने मिलकर बनाया था?","optionsHi":["FAO और WHO","FAO और WTO","WHO और UNICEF","WFP और IFAD"],"explanationHi":"कोडेक्स FAO/WHO का संयुक्त निकाय है, जिसका सचिवालय रोम में है; WTO के SPS समझौते ने बाद में व्यापार विवादों में कोडेक्स मानकों को एक संदर्भ बिंदु बना दिया।"},
  {"id":"gk-international-orgs-250","question":"The International Energy Agency, which India joined as an association country in 2017, was created in 1974 mainly in response to:","options":["The 1960 founding of OPEC by five oil-exporting countries","The 1973 oil crisis, to coordinate responses to supply cuts","The collapse of the Bretton Woods fixed exchange rate system","The need to control the spread of civilian nuclear technology"],"answer":1,"explanation":"Set up within the OECD framework after the 1973–74 Arab oil embargo, the IEA coordinates emergency oil stocks; nuclear safeguards are the IAEA's job.","difficulty":"hard","source":"UPSC Prelims · State PCS","questionHi":"अंतर्राष्ट्रीय ऊर्जा एजेंसी, जिसमें भारत 2017 में सहयोगी देश के रूप में शामिल हुआ, की स्थापना 1974 में मुख्यतः किसकी प्रतिक्रिया में हुई थी?","optionsHi":["पाँच तेल-निर्यातक देशों द्वारा 1960 में OPEC की स्थापना","1973 का तेल संकट, ताकि आपूर्ति कटौतियों पर प्रतिक्रियाओं का समन्वय हो सके","ब्रेटन वुड्स की स्थिर विनिमय दर प्रणाली का पतन","नागरिक परमाणु प्रौद्योगिकी के प्रसार को नियंत्रित करने की आवश्यकता"],"explanationHi":"OECD के ढाँचे में 1973-74 के अरब तेल प्रतिबंध के बाद स्थापित IEA आपातकालीन तेल भंडारों का समन्वय करती है; परमाणु सुरक्षा उपाय IAEA का कार्य हैं।"},
];

export default questions;
